-- ============================================================================
-- Migration: 000028_beginner_friendly_grammar_guides_and_progress.up.sql
-- Description:
--   1. Add structured beginner-friendly learning_guide JSONB column to grammar_points.
--   2. Create user_grammar_progress table for interactive understanding check & SRS.
--   3. Seed learning guides across all 56 JLPT N5-N1 grammar points.
-- ============================================================================

BEGIN;

ALTER TABLE grammar_points
    ADD COLUMN IF NOT EXISTS learning_guide JSONB NOT NULL DEFAULT '{}'::jsonb;

CREATE TABLE IF NOT EXISTS user_grammar_progress (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    grammar_point_id UUID NOT NULL REFERENCES grammar_points(id) ON DELETE CASCADE,
    quiz_score INT NOT NULL DEFAULT 0 CHECK (quiz_score >= 0 AND quiz_score <= 100),
    correct_count INT NOT NULL DEFAULT 0 CHECK (correct_count >= 0),
    total_questions INT NOT NULL DEFAULT 3 CHECK (total_questions > 0),
    attempts_count INT NOT NULL DEFAULT 1 CHECK (attempts_count >= 1),
    is_understood BOOLEAN NOT NULL DEFAULT false,
    understood_at TIMESTAMPTZ,
    next_review_at TIMESTAMPTZ,
    last_attempted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (user_id, grammar_point_id)
);

CREATE INDEX IF NOT EXISTS idx_user_grammar_progress_user ON user_grammar_progress(user_id);
CREATE INDEX IF NOT EXISTS idx_user_grammar_progress_review ON user_grammar_progress(user_id, next_review_at);

UPDATE grammar_points SET learning_guide = '{"analogy": "～に至って (ni itatte) artinya ''Hingga akhirnya sampai di titik kritis ini...'' atau ''Baru sekarang ketika keadaannya sudah terlanjur begini...''. Dipakai ketika sesuatu sudah berjalan jauh sampai tahap ekstrem atau terlambat.", "when_to_use": ["Menggambarkan krisis atau konflik yang memuncak setelah lama dibiarkan (''hingga akhirnya perang pecah / pasien pingsan baru sadar'')", "Artikel berita, novel, atau pidato resmi mengenai pencapaian tahap puncak", "Bila dikombinasi dengan はじめて (''baru di titik inilah menyadari...'')"], "formula_parts": [{"text": "Nomina / Kamus Verba", "label": "Titik kritis / Tahap akhir", "role": "time"}, {"text": "に至って / に至っては", "label": "Hingga sampai titik...", "role": "connector"}, {"text": "Konsekuensi Serius", "label": "Reaksi atau kesadaran terlambat", "role": "predicate"}], "steps": ["Siapkan peristiwa atau kondisi ekstrem sebagai puncaknya (misal: じたいの あっか = memburuknya keadaan, しゅじゅつ = harus dioperasi).", "Tambahkan に至って (atau に至ってはじめて = baru pada tahap itulah..., に至っては = kalau sudah sampai segitunya maka...).", "Selesaikan dengan hasil berat yang akhirnya muncul atau kesadaran yang terlambat."], "breakdowns": [{"tokens": [{"jp": "ここ", "reading": "koko", "meaning": "titik ini", "role": "place"}, {"jp": "に至って", "reading": "ni itatte", "meaning": "hingga sampai di", "role": "connector"}, {"jp": "ようやく", "reading": "youyaku", "meaning": "akhirnya baru", "role": "time"}, {"jp": "きがつきました", "reading": "ki ga tsukimashita", "meaning": "saya menyadari", "role": "verb"}], "translation": "Setelah sampai di titik ini, barulah saya menyadari."}, {"tokens": [{"jp": "びょうき", "reading": "byouki", "meaning": "penyakit", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "悪化する", "reading": "akka suru", "meaning": "memburuk (kamus)", "role": "verb"}, {"jp": "に至って", "reading": "ni itatte", "meaning": "hingga mencapai tahap", "role": "connector"}, {"jp": "病院", "reading": "byouin", "meaning": "rumah sakit", "role": "place"}, {"jp": "へ", "reading": "e", "meaning": "ke", "role": "particle"}, {"jp": "いった", "reading": "itta", "meaning": "pergi", "role": "verb"}], "translation": "Baru setelah penyakitnya parah memburuk, ia akhirnya pergi ke rumah sakit."}, {"tokens": [{"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "段階", "reading": "dankai", "meaning": "tahap", "role": "noun"}, {"jp": "に至っては", "reading": "ni itatte wa", "meaning": "kalau sudah sampai tahap ini", "role": "connector"}, {"jp": "もう", "reading": "mou", "meaning": "sudah tidak", "role": "time"}, {"jp": "ひきかえせない", "reading": "hikikaesenai", "meaning": "bisa mundur lagi", "role": "verb"}], "translation": "Jika sudah sampai pada tahap seperti ini, kita tidak bisa mundur lagi."}], "forms": [{"label": "Baru Sadar", "jp": "ここに至ってはじめて", "reading": "koko ni itatte hajimete", "id": "baru pada titik inilah..."}, {"label": "Sudah Kelewatan", "jp": "ここに至っては", "reading": "koko ni itatte wa", "id": "kalau sudah sampai begini..."}, {"label": "Berujung pada (Menerangkan)", "jp": "じこに至る原因", "reading": "jiko ni itaru gen''in", "id": "penyebab yang berujung kecelakaan"}], "mistakes": [{"wrong": "スーパーへ いく に至って、パンを かった", "right": "スーパーへ いって、パンを かった", "why": "Jangan dipakai untuk aktivitas ringan sehari-hari; ～に至って hanya untuk titik puncak situasi serius/ekstrem setelah proses panjang."}, {"wrong": "しっぱい した に至って", "right": "しっぱい する に至って", "why": "Bila memakai kata kerja, bentuknya wajib Bentuk Kamus (する), bukan lampau."}], "quiz": [{"question": "Kalimat mana yang memakai ～に至って secara PALING TEPAT?", "options": ["あさ おきる に至って、みずを のみました", "なんども けいこくされたが、ついに へいてんする に至った", "あした とうきょうへ いく に至って、たのしみだ", "この ケーキは おいしい に至って やすい"], "answer": 1, "why": "Peringatan berkali-kali yang berujung penutupan toko mencerminkan klimaks situasi serius."}, {"question": "Apa nuansa ungkapan ''ここ に 至って（ようやく）''?", "options": ["Masih sangat awal sebelum mulai", "Sudah sampai di tahap genting atau sudah terlambat barulah bereaksi", "Kegiatan rutin setiap hari", "Rencana liburan menyenangkan"], "answer": 1, "why": "ここ 至って menyoroti situasi yang sudah menumpuk hingga tahap puncak / terlambat."}, {"question": "Jika diletakkan sebelum kata benda ''成功（せいこう = kesuksesan） ___ 道（みち = jalan）'', bentuknya adalah:", "options": ["に至る", "に至って", "に至っては", "に至っても"], "answer": 0, "why": "Bentuk kamus 至る memodifikasi nomina di belakangnya (''jalan menuju kesuksesan'')."}]}'::jsonb WHERE code = 'GP-JA-N1-001';
UPDATE grammar_points SET learning_guide = '{"analogy": "～を余儀なくされる artinya ''Terpaksa tidak punya pilihan lain karena tekanan keadaan luar'' — lebih berat dan formal lagi dari ～ざるを得ない. Biasanya perusahaan, pemerintah, atau publik yang ''dipaksa keadaan'' mundur atau berubah.", "when_to_use": ["Berita bencana alam atau ekonomi yang memaksa warga mengungsi atau perusahaan tutup", "Laporan resmi tentang penundaan proyek akibat regulasi atau kondisi eksternal berat", "Menjelaskan pengorbanan berat yang sama sekali tidak bisa dihindari"], "formula_parts": [{"text": "Nomina (Tindakan Aksi)", "label": "Keputusan berat", "role": "noun"}, {"text": "を余儀なくされる", "label": "Dipaksa keadaan untuk...", "role": "verb"}], "steps": ["Pilih kata benda yang bermakna tindakan (biasanya kata benda berpasangan 2 kanji seperti ちゅうし = pembatalan, へいさ = penutupan, へんこう = perubahan, ひなん = pengungsian).", "Tempelkan langsung を余儀なくされる di belakang kata benda tersebut (sudah bentuk pasif!).", "Kalau pihak lain yang MEMAKSA (''memaksa mereka menutup toko''), akhiran aktifnya adalah ～を余儀なくさせる."], "breakdowns": [{"tokens": [{"jp": "おおゆき", "reading": "ooyuki", "meaning": "salju lebat", "role": "noun"}, {"jp": "で", "reading": "de", "meaning": "akibat", "role": "particle"}, {"jp": "けいかく", "reading": "keikaku", "meaning": "rencana", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "へんこう", "reading": "henkou", "meaning": "perubahan", "role": "object"}, {"jp": "を余儀なくされた", "reading": "o yogi naku sareta", "meaning": "terpaksa harus (oleh keadaan)", "role": "verb"}], "translation": "Akibat salju lebat, kami terpaksa mengubah rencana."}, {"tokens": [{"jp": "あのかいしゃ", "reading": "ano kaisha", "meaning": "perusahaan itu", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "へいてん", "reading": "heiten", "meaning": "penutupan toko", "role": "object"}, {"jp": "を余儀なくされました", "reading": "o yogi naku saremashita", "meaning": "terpaksa harus", "role": "verb"}], "translation": "Perusahaan itu terpaksa harus menutup tokonya."}, {"tokens": [{"jp": "おおぜいの", "reading": "oozei no", "meaning": "banyak", "role": "adjective"}, {"jp": "じゅうみん", "reading": "juumin", "meaning": "warga", "role": "topic"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "ひなん", "reading": "hinan", "meaning": "evakuasi / mengungsi", "role": "object"}, {"jp": "を余儀なくされている", "reading": "o yogi naku sarete iru", "meaning": "terpaksa harus menjalani", "role": "verb"}], "translation": "Banyak warga terpaksa harus mengungsi akibat kondisi saat ini."}], "forms": [{"label": "Lampau (Terpaksa)", "jp": "ちゅうしを余儀なくされた", "reading": "chuushi o yogi naku sareta", "id": "terpaksa dibatalkan"}, {"label": "Masih Berlangsung", "jp": "たいきを余儀なくされている", "reading": "taiki o yogi naku sarete iru", "id": "masih terpaksa menunggu"}, {"label": "Bentuk Kausatif (Memaksa)", "jp": "てったいを余儀なくさせた", "reading": "tettai o yogi naku saseta", "id": "memaksanya harus mundur"}], "mistakes": [{"wrong": "へんこうする を余儀なくされた", "right": "へんこう を余儀なくされた", "why": "Tidak boleh memakai kata kerja langsung; ambil KATA BENDA aksinya saja (する dibuang) sebelum を余儀なくされる."}, {"wrong": "ねむいから ねるを余儀なくされた", "right": "ねむくて ねてしまった / やむをえず ねた", "why": "余儀なくされる adalah ungkapan berita/tulisan super resmi untuk situasi berat eksternal, jangan dipakai untuk hal sepele seperti mengantuk."}], "quiz": [{"question": "Lengkapi kutipan koran ''工場は 経営悪化（けいえいあっか = memburuknya bisnis）により、___ を余儀なくされた'' (terpaksa melakukan pemangkasan):", "options": ["閉鎖（へいさ = penutupan）", "閉鎖する", "閉鎖した", "閉鎖して"], "answer": 0, "why": "Di depan を余儀なくされる wajib langsung berupa Nomina (kata benda) tanpa する."}, {"question": "Bagaimana bacaan huruf Kanji ''を余儀なくされる''?", "options": ["o yoki naku sareru", "o yogi naku sareru", "o amari gi naku", "o yougi naku sareru"], "answer": 1, "why": "余儀 dibaca よぎ (yogi) dengan dakuten pada gi."}, {"question": "Siapa atau apa pendorong tindakan dalam kalimat ～を余儀なくされる?", "options": ["Keinginan sukarela dari dalam hati", "Desakan keadaan berat dari luar sehingga tidak ada pilihan lain", "Nasihat santai dari teman dekat", "Hobi di waktu senggang"], "answer": 1, "why": "Maknanya secara harfiah adalah ''dibuat tidak punya ruang pilihan lain oleh keadaan''."}]}'::jsonb WHERE code = 'GP-JA-N1-002';
UPDATE grammar_points SET learning_guide = '{"analogy": "～とはいえ artinya ''Meskipun memang benar begitu adanya, tapi kenyataannya...''. Mirip ungkapan Indonesia ''Memang sih sudah [A], tapi tetap saja [B]!''.", "when_to_use": ["Mengakui suatu fakta resmi lalu membalik dengan kenyataan lapangan (''memang sudah musim semi sih, tapi masih dingin banget!'')", "Merendah saat dipuji atau mengakui keunggulan lawan sambil memberi catatan (''meski masih pemula, dia cepat belajar'')", "Artikel opini & esai penyeimbang argumen"], "formula_parts": [{"text": "Nomina / Bentuk Biasa", "label": "Fakta yg diakui benar", "role": "noun"}, {"text": "とはいえ", "label": "Memang demikian, namun", "role": "connector"}, {"text": "Kenyataan Bertolak Belakang", "label": "Sisi lain / catatan", "role": "predicate"}], "steps": ["Sebutkan fakta yang memang benar (misal: はる = musim semi, やすみ = hari libur, かった = menang).", "Sambungkan langsung dengan とはいえ (untuk Kata Benda dan Sifat-Na, boleh langsung tempel atau memakai だ, misalnya はる とはいえ / はるだ とはいえ).", "Tambahkan fakta nyata yang agak bertolak belakang atau perlu diperhatikan."], "breakdowns": [{"tokens": [{"jp": "はる", "reading": "haru", "meaning": "musim semi", "role": "time"}, {"jp": "とはいえ", "reading": "to wa ie", "meaning": "memang sih..., tapi", "role": "connector"}, {"jp": "まだ", "reading": "mada", "meaning": "masih", "role": "time"}, {"jp": "さむい", "reading": "samui", "meaning": "dingin", "role": "adjective"}, {"jp": "ひ", "reading": "hi", "meaning": "hari", "role": "noun"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "つづいています", "reading": "tsuzuite imasu", "meaning": "terus berlanjut", "role": "verb"}], "translation": "Meskipun secara kalender sudah musim semi, hari-hari dingin masih berlanjut."}, {"tokens": [{"jp": "やすみ", "reading": "yasumi", "meaning": "hari libur", "role": "noun"}, {"jp": "とはいえ", "reading": "to wa ie", "meaning": "walaupun namanya", "role": "connector"}, {"jp": "かじ", "reading": "kaji", "meaning": "pekerjaan rumah", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "あって", "reading": "atte", "meaning": "ada dan", "role": "verb"}, {"jp": "いそがしい", "reading": "isogashii", "meaning": "sibuk", "role": "adjective"}], "translation": "Walau namanya hari libur, tetap saja ada pekerjaan rumah dan sibuk."}, {"tokens": [{"jp": "きかい", "reading": "kikai", "meaning": "mesin", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "べんりに", "reading": "benri ni", "meaning": "praktis", "role": "adjective"}, {"jp": "なった", "reading": "natta", "meaning": "telah menjadi", "role": "verb"}, {"jp": "とはいえ", "reading": "to wa ie", "meaning": "meskipun diakui", "role": "connector"}, {"jp": "人間の", "reading": "ningen no", "meaning": "milik manusia", "role": "noun"}, {"jp": "て", "reading": "te", "meaning": "tangan", "role": "subject"}, {"jp": "も", "reading": "mo", "meaning": "tetap juga", "role": "particle"}, {"jp": "ひつようだ", "reading": "hitsuyou da", "meaning": "diperlukan", "role": "adjective"}], "translation": "Meskipun mesin sudah menjadi praktis, tetap saja sentuhan tangan manusia masih diperlukan."}], "forms": [{"label": "Kata Benda", "jp": "こども とはいえ", "reading": "kodomo to wa ie", "id": "meski masih anak-anak sih, tapi..."}, {"label": "Verba", "jp": "ごうかくした とはいえ", "reading": "goukaku shita to wa ie", "id": "memang sudah lulus sih, namun..."}, {"label": "Di Awal Kalimat", "jp": "とはいえ", "reading": "to wa ie", "id": "Namun demikian, ..."}], "mistakes": [{"wrong": "きょうは にちようび な とはいえ", "right": "きょうは にちようび（だ） とはいえ", "why": "Sebelum とはいえ jangan memakai な; pakai Nomina polos langsung atau Nomina + だ."}, {"wrong": "かれは 社長 とはいえ、会社で いちばん えらい", "right": "かれは 社長 とはいえ、しっぱいすることも ある", "why": "Kalimat di belakang とはいえ harus membelokkan/mengimbangi fakta awal, bukan menguatkan searah."}], "quiz": [{"question": "Lengkapi: ''りょうりが じょうず ___、プロのように きれいには 作れない'' (Memang jago masak sih, tapi tetap tidak secantik koki profesional):", "options": ["な とはいえ", "とはいえ", "での とはいえ", "て とはいえ"], "answer": 1, "why": "Sifat-Na (じょうず) langsung ditempeli とはいえ tanpa な."}, {"question": "Apa arti kata penghubung ''とはいえ'' jika diletakkan sendirian di awal paragraf kedua?", "options": ["Dengan kata lain...", "Meskipun begitu / Namun demikian...", "Sebagai kesimpulan akhir...", "Sebaliknya total..."], "answer": 1, "why": "いえ tetap mempertahankan makna ''meski mengakui pernyataan sebelumnya, ada sisi lain yang perlu diingat''."}, {"question": "Manakah contoh yang paling cocok memakai ～とはいえ?", "options": ["N1に うかった とはいえ、まだ かいわは にがてだ", "あさ おきた とはいえ、ねむかった", "コーヒーを のんだ とはいえ、おいしかった", "あした とはいえ、きょうだ"], "answer": 0, "why": "Mengakui prestasi nyata (lulus N1) namun jujur tetap ada kelemahan (percakapan masih susah)."}]}'::jsonb WHERE code = 'GP-JA-N1-003';
UPDATE grammar_points SET learning_guide = '{"analogy": "～をもって punya dua fungsi resmi: (1) ''Pada tanggal/waktu ini (sebagai batas resmi penutupan atau berakhirnya masa berlaku)'', dan (2) ''Melalui sarana resmi ini (surat, penjelasan lisan, hasil tes)''.", "when_to_use": ["Pengumuman tutupnya loket, berakhirnya masa kerja/layanan, atau penutupan acara (''acara berakhir pada jam 5 tepat'')", "Menyampaikan berita resmi ''melalui surat ini kami kabarkan...'' atau ''berterima kasih dengan tindakan nyata''", "Kalimat formal di papan pengumuman stasiun, mal, surat kabar, atau pidato resmi"], "formula_parts": [{"text": "Nomina (Waktu / Sarana Resmi)", "label": "Titik batas atau instrumen", "role": "noun"}, {"text": "をもって", "label": "Pada batas / Dengan sarana", "role": "particle"}, {"text": "Pernyataan Resmi", "label": "Penutupan / Pembuktian", "role": "predicate"}], "steps": ["Untuk makna batas waktu berakhirnya layanan: taruh tanggal/jam akhir di depan をもって (misal: 本日をもって = terhitung hari ini...).", "Untuk makna sarana/alat resmi: taruh kata benda cara/alat (misal: 書面をもって = secara tertulis lewat surat, 態度をもって = dengan perbuatan/sikap).", "Di akhir kalimat biasanya muncul verba resmi seperti 終了します (berakhir), 閉店します (tutup permanen), atau お知らせします (mengumumkan)."], "breakdowns": [{"tokens": [{"jp": "ほんじつ", "reading": "honjitsu", "meaning": "hari ini", "role": "time"}, {"jp": "をもって", "reading": "o motte", "meaning": "terhitung berakhir pada", "role": "particle"}, {"jp": "えいぎょう", "reading": "eigyou", "meaning": "operasional toko", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "しゅうりょうします", "reading": "shuuryou shimasu", "meaning": "kami akhiri", "role": "verb"}], "translation": "Terhitung hari ini, operasional kami resmi berakhir."}, {"tokens": [{"jp": "けっか", "reading": "kekka", "meaning": "hasil", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "しょめん", "reading": "shomen", "meaning": "dokumen tertulis", "role": "noun"}, {"jp": "をもって", "reading": "o motte", "meaning": "melalui / dengan sarana", "role": "particle"}, {"jp": "おしらせします", "reading": "oshirase shimasu", "meaning": "kami kabarkan", "role": "verb"}], "translation": "Hasilnya akan kami sampaikan secara resmi melalui dokumen tertulis."}, {"tokens": [{"jp": "これ", "reading": "kore", "meaning": "hal ini", "role": "noun"}, {"jp": "をもって", "reading": "o motte", "meaning": "dengan ini", "role": "connector"}, {"jp": "へいかい", "reading": "heikai", "meaning": "penutupan acara", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "あいさつ", "reading": "aisatsu", "meaning": "sambutan", "role": "noun"}, {"jp": "とさせていただきます", "reading": "to sasete itadakimasu", "meaning": "kami cukupkan sebagai", "role": "ending"}], "translation": "Dengan ini saya cukupkan sebagai sambutan penutupan acara."}], "forms": [{"label": "Batas Tanggal", "jp": "今月末をもって退職します", "reading": "kongetsumatsu o motte taishoku shimasu", "id": "mengundurkan diri per akhir bulan ini"}, {"label": "Sarana Tertulis", "jp": "メールをもってご返信と代えます", "reading": "meeru o motte", "id": "membalas melalui email"}, {"label": "Penutup Pidato", "jp": "以上をもちまして", "reading": "ijou o mochimashite", "id": "dengan berakhirnya penyampaian di atas"}], "mistakes": [{"wrong": "きょうは ペンをもって 手紙を かきます (tulisan santai)", "right": "きょうは ペンで 手紙を かきます", "why": "Untuk alat sehari-hari seperti pena atau sumpit, selalu gunakan partikel で! をもって hanya untuk sarana/batasan bernuansa seremonial & resmi."}, {"wrong": "３じ をもって はじまります (untuk mulai acara biasa)", "right": "３じ から はじまります / ほんじつをもって しゅうりょうします", "why": "Untuk waktu, をもって paling lazim menandai BATAS AKHIR/penutupan resmi sesuatu."}], "quiz": [{"question": "Manakah pengumuman stasiun yang PALING ALAMI memakai ～をもって?", "options": ["この みせは 来月１０日をもって 閉店（へいてん）いたします", "この ペンをもって なまえを かいて ください", "わたしは でんしゃをもって かいしゃへ いきます", "きのうをもって ケーキを たべました"], "answer": 0, "why": "Menandai tanggal terakhir operasional penutupan toko memakai [tanggal] をもって."}, {"question": "Apa arti kalimat penutup MC ''これをもちまして、本日の 式を 終わります''?", "options": ["Tolong bawa pulang buku acara hari ini", "Dengan ini, acara resmi hari ini kita akhiri", "Acara baru saja dimulai", "Besok acara dilanjutkan lagi"], "answer": 1, "why": "これをもちまして = ''Dengan penyampaian ini (sebagai penutup)...''."}, {"question": "Mengapa partikel を wajib berpasangan dengan もって ( bukan に)?", "options": ["Karena bentuk aslinya berasal dari kata kerja 持つ (motsu = memegang/memakai objek)", "Karena bunyinya lebih cepat", "Karena にもって berarti dilarang", "Karena aturan huruf Katakana"], "answer": 0, "why": "をもって berasal dari ~o motte (memegang/menggunakan sarana ini sebagai patokan resmi)."}]}'::jsonb WHERE code = 'GP-JA-N1-004';
UPDATE grammar_points SET learning_guide = '{"analogy": "～極まりない artinya ''Sangat-sangat keterlaluan / tak terlukiskan lagi saking ekstremnya!'' (biasanya hal negatif, berbahaya, atau tidak sopan sekali — kadang juga untuk rasa syukur/senang yang memuncak di tulisan klasik).", "when_to_use": ["Mengkritik keras sikap sembrono atau bahaya besar (''tindakan yang amat sangat berbahaya'', ''amat tidak sopan!'')", "Berita atau opini tentang kebijakan yang tidak adil atau menyusahkan", "Menekankan sifat positif tertentu secara sangat sastrawi (''merupakan kehormatan yang tiada tara'')"], "formula_parts": [{"text": "Akar Sifat-Na (tanpa な/だ)", "label": "Sifat ekstrem", "role": "adjective"}, {"text": "極まりない（きわまりない）", "label": "Tiada tara / Kebangetan", "role": "ending"}], "steps": ["Ambil akar Kata Sifat-Na yang menyatakan penilaian kuat (contoh: 失礼 = tidak sopan, 危険 = berbahaya, 不愉快 = tidak menyenangkan, 遺憾 = sangat disayangkan).", "JANGAN tambah な atau だ! Langsung tempelkan 極まりない (atau bentuk sopan 極まりないです / bentuk lampau 極まりなかった).", "Untuk penulisan formal di koran, kadang dipakai variasi 極まる (kiwamaru)."], "breakdowns": [{"tokens": [{"jp": "その", "reading": "sono", "meaning": "itu", "role": "noun"}, {"jp": "たいど", "reading": "taido", "meaning": "sikap", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "しつれい", "reading": "shitsurei", "meaning": "kurang ajar/tidak sopan", "role": "adjective"}, {"jp": "極まりない", "reading": "kiwamari nai", "meaning": "amat sangat (keterlaluan)", "role": "ending"}], "translation": "Sikap seperti itu benar-benar tidak sopan tiada tara!"}, {"tokens": [{"jp": "よなか", "reading": "yonaka", "meaning": "tengah malam", "role": "time"}, {"jp": "に", "reading": "ni", "meaning": "di", "role": "particle"}, {"jp": "ひとりで", "reading": "hitori de", "meaning": "sendirian", "role": "noun"}, {"jp": "あるく", "reading": "aruku", "meaning": "berjalan", "role": "verb"}, {"jp": "のは", "reading": "no wa", "meaning": "(hal tersebut)", "role": "particle"}, {"jp": "きけん", "reading": "kiken", "meaning": "berbahaya", "role": "adjective"}, {"jp": "極まりない", "reading": "kiwamari nai", "meaning": "sangat amat ekstrem", "role": "ending"}], "translation": "Berjalan sendirian di tengah malam itu amat sangat berbahaya."}, {"tokens": [{"jp": "めいわく", "reading": "meiwaku", "meaning": "mengganggu/menyusahkan", "role": "adjective"}, {"jp": "極まりない", "reading": "kiwamari nai", "meaning": "sungguh keterlaluan", "role": "ending"}, {"jp": "こうい", "reading": "koui", "meaning": "tindakan", "role": "noun"}, {"jp": "に", "reading": "ni", "meaning": "terhadap", "role": "particle"}, {"jp": "はら", "reading": "hara", "meaning": "perut/emosi", "role": "object"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "たった", "reading": "tatta", "meaning": "naik (marah)", "role": "verb"}], "translation": "Saya sangat marah atas perbuatan yang amat keterlaluan mengganggu tersebut."}], "forms": [{"label": "Kritik Tajam", "jp": "無責任極まりない", "reading": "musekinin kiwamari nai", "id": "amat sangat tidak bertanggung jawab"}, {"label": "Rasa Sesal Resmi", "jp": "残念極まりない", "reading": "zannen kiwamari nai", "id": "sungguh amat disayangkan"}, {"label": "Penekanan Positif Resmi", "jp": "光栄極まりない", "reading": "kouei kiwamari nai", "id": "kehormatan yang tak terhingga"}], "mistakes": [{"wrong": "この ラーメンは おいしい 極まりない！", "right": "とても おいしい！ / さいこうに おいしい！", "why": "～極まりない adalah gaya tulisan/komentar tegas yang umumnya memakai Sifat-Na abstrak (berbahaya, tidak sopan, menyusahkan), bukan sifat-I ringan sehari-hari seperti ''enak''."}, {"wrong": "しつれい な 極まりない", "right": "しつれい 極まりない", "why": "Tidak boleh memakai な di antara Sifat-Na dan 極まりない."}], "quiz": [{"question": "Bagaimana cara menyambungkan 不愉快（ふゆかい = tidak menyenangkan, Sifat-Na）dengan 極まりない?", "options": ["不愉快 な 極まりない", "不愉快 極まりない", "不愉快 だ 極まりない", "不愉快 の 極まりない"], "answer": 1, "why": "Akar Sifat-Na langsung menempel ke 極まりない tanpa な atau だ."}, {"question": "Pilih konteks kalimat yang PALING COCOK memakai ～極まりない:", "options": ["Membahas betapa tidak sopannya orang yang membuang sampah sembarangan di tempat suci (無礼極まりない)", "Memuji kucing tetangga yang imut", "Meminta tambahan gula di kopi", "Bertanya letak stasiun"], "answer": 0, "why": "Ungkapan N1 ini tepat untuk kecaman keras atau penekanan sifat ekstrem."}, {"question": "Walau ada huruf ''ない'' di ujung 極まりない, apakah maknanya negatif (''tidak ekstrem'')?", "options": ["Ya, selalu berarti tidak ada batas", "Tidak, artinya justru ''TERAMAT SANGAT / tiada batasnya''", "Artinya ''kadang-kadang saja''", "Artinya ''hampir tidak terjadi''"], "answer": 1, "why": "きわまりない berarti ''tak berujung / tak tertandingi tingginya'', bukan bentuk penyangkalan."}]}'::jsonb WHERE code = 'GP-JA-N1-005';
UPDATE grammar_points SET learning_guide = '{"analogy": "～なりに artinya ''Dengan caranya sendiri / Sesuai kadar kemampuannya''. Nada bicaranya hangat dan menghargai: mungkin hasilnya belum sempurna seperti ahli, tapi sudah diusahakan sebaik mungkin sesuai kapasitas dirinya!", "when_to_use": ["Menghargai usaha anak kecil, pemula, atau orang yang berusaha semampunya (''meski masih anak-anak, dia berpikir dengan caranya sendiri'')", "Merendah saat membicarakan usaha pribadi (''saya sudah berjuang semampu kapasitas saya'')", "Melihat sisi positif dari sesuatu yang sederhana (''ruangan sempit ini punya kenyamanannya tersendiri sesuai ukurannya'')"], "formula_parts": [{"text": "Nomina / Bentuk Biasa", "label": "Kapasitas / Posisi", "role": "noun"}, {"text": "なりに / なりの", "label": "Sesuai caranya sendiri", "role": "particle"}, {"text": "Usaha / Kualitas Tersendiri", "label": "Hasil sesuai kapasitasnya", "role": "predicate"}], "steps": ["Taruh siapa atau kondisi apa yang dijadikan patokan kapasitasnya di depan (contoh: こども = anak kecil, わたし = saya, 初心者 = pemula).", "Langsung tempelkan なりに kalau diikuti kata kerja/sifat di belakang (''berusaha dengan caranya'').", "Ganti menjadi なりの jika langsung diikuti kata benda (''gaya kebahagiaan tersendiri'', ''pendapat versi dirinya sendiri'')."], "breakdowns": [{"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "わたし", "reading": "watashi", "meaning": "diri saya", "role": "noun"}, {"jp": "なりに", "reading": "nari ni", "meaning": "dengan cara & kemampuan saya", "role": "particle"}, {"jp": "がんばりました", "reading": "ganbarimashita", "meaning": "sudah berjuang keras", "role": "verb"}], "translation": "Saya sudah berjuang keras sesuai batas kemampuan diri saya sendiri."}, {"tokens": [{"jp": "こども", "reading": "kodomo", "meaning": "anak kecil", "role": "topic"}, {"jp": "には", "reading": "ni wa", "meaning": "bagi mereka", "role": "particle"}, {"jp": "こども", "reading": "kodomo", "meaning": "anak-anak", "role": "noun"}, {"jp": "なりの", "reading": "nari no", "meaning": "versi/cara tersendiri", "role": "particle"}, {"jp": "なやみ", "reading": "nayami", "meaning": "kekhawatiran", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "ある", "reading": "aru", "meaning": "ada", "role": "verb"}], "translation": "Anak-anak pun punya beban pikiran versi anak-anaknya sendiri."}, {"tokens": [{"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "まち", "reading": "machi", "meaning": "kota", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "いなか", "reading": "inaka", "meaning": "pedesaan", "role": "noun"}, {"jp": "なりに", "reading": "nari ni", "meaning": "sebagai daerah desa pun tetap", "role": "particle"}, {"jp": "みりょく", "reading": "miryoku", "meaning": "daya tarik", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "たくさんある", "reading": "takusan aru", "meaning": "banyak sekali ada", "role": "verb"}], "translation": "Meski daerah pedesaan, kota ini punya banyak daya tariknya tersendiri."}], "forms": [{"label": "Diikuti Verba/Sifat", "jp": "かれはかれなりに考えた", "reading": "kare wa kare nari ni kangaeta", "id": "dia berpikir dengan caranya sendiri"}, {"label": "Diikuti Benda (+の)", "jp": "初心者なりの工夫", "reading": "shoshinsha nari no kufuu", "id": "kreativitas khas pemula"}, {"label": "Pengulangan Subjek", "jp": "それなりにいい", "reading": "sore nari ni ii", "id": "lumayan bagus sesuai kadarnya"}], "mistakes": [{"wrong": "しゃちょう、しゃちょう なりの けいかくは じょうずですね", "right": "すばらしい ごけいかくですね", "why": "Jangan pakai なりに untuk memuji atasan atau ahli senior! Nuansa なりに menyiratkan ''walau levelnya masih terbatas, tapi sudah oke'' sehingga kurang sopan untuk yang lebih tinggi."}, {"wrong": "わたし の なりに がんばる", "right": "わたし なりに がんばる", "why": "Tidak boleh menyisipkan の di depan なりに (langsung nomina + なりに)."}], "quiz": [{"question": "Lengkapi: ''年をとれば、年をとった ___ たのしみ方が ある'' (Kalau sudah tua pun ada cara menikmati versi tuanya; たのしみ方 = nomina):", "options": ["なりに", "なりの", "なりのに", "なりを"], "answer": 1, "why": "Di depan kata benda (たのしみ方), wajib memakai なりの."}, {"question": "Mengapa frase ''それなりに'' populer sekali di percakapan sehari-hari Jepang?", "options": ["Artinya ''lumayan oke / punya nilai baik sesuai keadaannya''", "Artinya ''sangat gagal total''", "Artinya ''paling mahal di dunia''", "Artinya ''hanya untuk diri saya''"], "answer": 0, "why": "それなりに berarti ''ya cukuplah bagus/berfungsi sesuai porsinya''."}, {"question": "Pola ～なりに paling tepat dipakai kepada:", "options": ["Memuji direktur utama", "Membicarakan usaha tulus anak, pemula, atau diri sendiri dengan rendah hati", "Mengeluarkan larangan polisi", "Menetapkan denda pajak"], "answer": 1, "why": "Nuansanya menghargai usaha maksimal meski level/skalanya belum seberapa."}]}'::jsonb WHERE code = 'GP-JA-N1-006';
UPDATE grammar_points SET learning_guide = '{"analogy": "～ずにはおかない artinya ''Pasti tanpa ampun akan memicu reaksi/perasaan tertentu bagi siapa pun yang mengalaminya''. Seperti bilang: ''Film itu dijamin bakal bikin siapa saja yang nonton nangis!''.", "when_to_use": ["Menggambarkan kekuatan karya seni, pidato, atau musik yang pasti menggugah hati (''lagu ini pasti membuat pendengarnya terharu'')", "Tekad kuat atau hukuman pasti (''kejahatan ini pasti akan mengundang kemarahan publik / pasti kubalas'')", "Ulasan buku, pameran, drama, dan opini sastra"], "formula_parts": [{"text": "Bentuk-NAI (tanpa ない)", "label": "Reaksi yg pasti muncul", "role": "verb"}, {"text": "ずにはおかない", "label": "Pasti bikin / takkan berhenti tanpa...", "role": "ending"}], "steps": ["Ambil kata kerja emosi atau akibat yang ditimbulkan pada orang lain (contoh: かんどうさせる = bikin terharu, わらわせる = bikin tertawa, おこらせる = bikin marah).", "Ubah ke Bentuk-NAI lalu buang ない (misal: かんどうさせない → かんどうさせ). Khusus する wajib menjadi せず!", "Tambahkan ずにはおかない (''tidak akan membiarkannya berlalu tanpa membuat...''). Jangan bingung dengan ～ずにはいられない (''diri sendiri nggak tahan ingin...'')."], "breakdowns": [{"tokens": [{"jp": "その", "reading": "sono", "meaning": "itu", "role": "noun"}, {"jp": "えいが", "reading": "eiga", "meaning": "film", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "みるひと", "reading": "miru hito", "meaning": "penontonnya", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "なかせ", "reading": "nakase", "meaning": "membuat menangis", "role": "verb"}, {"jp": "ずにはおかない", "reading": "zu ni wa okanai", "meaning": "pasti akan", "role": "ending"}], "translation": "Film itu pasti akan membuat penontonnya menangis."}, {"tokens": [{"jp": "かれ", "reading": "kare", "meaning": "dia", "role": "topic"}, {"jp": "の", "reading": "no", "meaning": "(milik)", "role": "particle"}, {"jp": "スピーチ", "reading": "supiichi", "meaning": "pidato", "role": "subject"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "みんな", "reading": "minna", "meaning": "semua orang", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "かんどうさせ", "reading": "kandou sase", "meaning": "menggugah haru", "role": "verb"}, {"jp": "ずにはおかない", "reading": "zu ni wa okanai", "meaning": "pasti takkan gagal", "role": "ending"}], "translation": "Pidatonya pasti akan menggugah rasa haru semua orang."}, {"tokens": [{"jp": "しんじん", "reading": "shinjin", "meaning": "pendatang baru", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "かつやく", "reading": "katsuyaku", "meaning": "aksi gemilang", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "ちゅうもく", "reading": "chuumoku", "meaning": "sorotan/perhatian", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "あつめ", "reading": "atsume", "meaning": "menarik", "role": "verb"}, {"jp": "ずにはおかない", "reading": "zu ni wa okanai", "meaning": "pasti akan", "role": "ending"}], "translation": "Aksi gemilang sang pendatang baru itu pasti akan menarik sorotan publik."}], "forms": [{"label": "Verba Umum (-NAI + ずに)", "jp": "わらわせずにはおかない", "reading": "warawasezu ni wa okanai", "id": "pasti bikin tertawa"}, {"label": "Khusus する (せず)", "jp": "はんせいせずにはおかない", "reading": "hansei sezu ni wa okanai", "id": "pasti membuatnya merenung"}, {"label": "Bandingkan: ～ずにはいられない", "jp": "わらわずにはいられない", "reading": "warawazu ni wa irarenai", "id": "saya tak tahan ingin tertawa (perasaan diri)"}], "mistakes": [{"wrong": "おいしい においに、たべずにはおかない", "right": "おいしい においに、たべずにはいられない", "why": "Kalau subjeknya dirimu sendiri yang ''nggak tahan pengen ngelakuin'', pakai ～ずにはいられない! ～ずにはおかない subjeknya adalah pemicu luar yang ''pasti bikin orang lain...''."}, {"wrong": "しずにはおかない", "right": "せずにはおかない", "why": "Sama seperti pola kuno ～ず lainnya, する selalu berubah menjadi せず, bukan しず."}], "quiz": [{"question": "Bedakan dua pola mirip N1 ini! ''あの コンサートは、きくひとを ___ ずにはおかない'' (membuat haru; かんどうさせる = membuat terharu):", "options": ["かんどうさせ", "かんどうし", "かんどうする", "かんどうさせて"], "answer": 0, "why": "Subjek luar (konser) memicu reaksi pada penonton, sehingga memakai bentuk kausatif (かんどうさせ) + ずにはおかない."}, {"question": "Kalau yang tidak tahan menahan tawa adalah DIRIMU SENDIRI, mana yang tepat?", "options": ["おもしろくて わらわずには おかない", "おもしろくて わらわずには いられない", "おもしろくて わらうずには おかない", "おもしろくて わらわせずには いられない"], "answer": 1, "why": "Dorongan spontan dari dalam diri yang sulit ditahan memakai ～ずにはいられない."}, {"question": "Bentuk yang benar untuk kata kerja する sebelum ずにはおかない adalah:", "options": ["しずにはおかない", "せずにはおかない", "すずにはおかない", "さずにはおかない"], "answer": 1, "why": "Kata kerja する wajib menjadi せず di depan ず."}]}'::jsonb WHERE code = 'GP-JA-N1-007';
UPDATE grammar_points SET learning_guide = '{"analogy": "～ともなると artinya ''Kalau sudah sampai di level / jabatan / musim setinggi itu, wajar dong kalau...'' (beda jauh dari pemula/biasa!).", "when_to_use": ["Membahas tanggung jawab jabatan tinggi (''kalau sudah jadi manajer, tanggung jawabnya ikut besar'')", "Menggambarkan kehebatan level ahli atau negara maju (''sekelas atlet olimpiade latihannya tentu luar biasa'')", "Menggambarkan suasana khas di puncak musim (''kalau sudah masuk bulan Desember, kota pun ramai lampu'')"], "formula_parts": [{"text": "Nomina / Kamus Verba", "label": "Level tinggi / Puncak waktu", "role": "noun"}, {"text": "ともなると / ともなれば", "label": "Kalau sudah sampai level...", "role": "connector"}, {"text": "Konsekuensi Selevel", "label": "Kondisi khusus yg ikut berubah", "role": "predicate"}], "steps": ["Pilih status atau waktu yang levelnya di atas rata-rata atau istimewa (contoh: しゃちょう = direktur, N1 = level tertinggi, １２がつ = Desember akhir tahun).", "Tambahkan ともなると (fakta umum di level itu) atau ともなれば (''seandainya sampai level itu...'').", "Jelaskan standar baru, tekanan, atau ciri khas yang muncul sebanding dengan level tersebut."], "breakdowns": [{"tokens": [{"jp": "プロ", "reading": "puro", "meaning": "profesional", "role": "noun"}, {"jp": "ともなると", "reading": "to mo naru to", "meaning": "kalau sudah sekelas", "role": "connector"}, {"jp": "れんしゅう", "reading": "renshuu", "meaning": "latihan", "role": "subject"}, {"jp": "も", "reading": "mo", "meaning": "juga", "role": "particle"}, {"jp": "きびしい", "reading": "kibishii", "meaning": "keras / ketat", "role": "adjective"}], "translation": "Kalau sudah sampai level profesional, latihannya pun tentu sangat ketat."}, {"tokens": [{"jp": "１２がつ", "reading": "juunigatsu", "meaning": "bulan Desember", "role": "time"}, {"jp": "ともなると", "reading": "to mo naru to", "meaning": "kalau sudah masuk", "role": "connector"}, {"jp": "あさばん", "reading": "asaban", "meaning": "pagi & malam", "role": "time"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "ぐっと", "reading": "gutto", "meaning": "drastis terasa", "role": "adjective"}, {"jp": "さむくなります", "reading": "samuku narimasu", "meaning": "menjadi dingin", "role": "adjective"}], "translation": "Kalau sudah memasuki bulan Desember, pagi dan malam terasa makin dingin drastis."}, {"tokens": [{"jp": "会社の", "reading": "kaisha no", "meaning": "milik perusahaan", "role": "noun"}, {"jp": "しゃちょう", "reading": "shachou", "meaning": "direktur utama", "role": "noun"}, {"jp": "ともなれば", "reading": "to mo nareba", "meaning": "kalau sudah menjadi", "role": "connector"}, {"jp": "じぶん", "reading": "jibun", "meaning": "diri sendiri", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(milik)", "role": "particle"}, {"jp": "じかん", "reading": "jikan", "meaning": "waktu luang", "role": "subject"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "ほとんどない", "reading": "hotondo nai", "meaning": "hampir tidak ada", "role": "adjective"}], "translation": "Jika sudah menjadi seorang direktur perusahaan, hampir tak ada waktu pribadi."}], "forms": [{"label": "Jabatan / Status", "jp": "りーだーともなると", "reading": "riidaa to mo naru to", "id": "kalau sudah jadi pemimpin"}, {"label": "Musim / Waktu", "jp": "なつやすみともなれば", "reading": "natsuyasumi to mo nareba", "id": "begitu tiba musim libur panjang"}, {"label": "Verba Peningkatan", "jp": "にほんに１０ねんすむともなると", "reading": "Nihon ni 10-nen sumu to mo naru to", "id": "kalau sudah 10 tahun tinggal di Jepang"}], "mistakes": [{"wrong": "学生に ともなると、まいにち 学校へ いく", "right": "高校生（こうこうせい）にも なると / 大人に なると", "why": "Bila tidak mencerminkan level spesial/puncak atau hanya fakta biasa, kurang cocok memakai ともなると. Juga jangan sisipkan partikel に sebelum と!"}, {"wrong": "しっぱいした ともなると", "right": "しっぱいする ともなると / こまったことに なる", "why": "Bila memakai kata kerja, gunakan Bentuk Kamus yang bermakna mencapai suatu tahap (misal: はたらく, もつ)."}], "quiz": [{"question": "Lengkapi: ''JLPT N1 ___、新聞の 記事も かなり 読めるように なる'' (Kalau sudah sampai level N1...):", "options": ["ともなると", "を余儀なくされて", "といえども", "なりに"], "answer": 0, "why": "Menyoroti dampak kemampuan ketika mencapai tingkatan tinggi (N1) memakai ～ともなると."}, {"question": "Apa perbedaan bentuk ともなると dan ともなれば?", "options": ["Sama persis penggunaannya; ともなれば sedikit lebih hipotesis (''andaikan/kalau sudah...'')", "ともなれば hanya untuk lampau", "ともなると hanya untuk benda mati", "Beda makna 180 derajat"], "answer": 0, "why": "Keduanya hampir sinonim; ともなると lebih umum menggambarkan kenyataan pada level itu, ともなれば bernada syarat."}, {"question": "Manakah kalimat yang logis untuk ～ともなると?", "options": ["１ねんせい ともなると、あいうえおが かけない", "ゆうめいじん ともなると、どこへ いっても しゃしんを とられる", "きょう ともなると、あさごはんを たべた", "コーヒー ともなると、あつい"], "answer": 1, "why": "Menjadi figur terkenal membawa konsekuensi wajar selalu difoto orang ke mana pun pergi."}]}'::jsonb WHERE code = 'GP-JA-N1-008';
UPDATE grammar_points SET learning_guide = '{"analogy": "～いかんによらず artinya ''Tanpa memandang apakah alasannya begini atau begitu (apapun kondisinya), aturannya TETAP berlaku sama!'' — mirip kata tegas Indonesia ''Terlepas dari apapun... tetap wajib/berlaku''.", "when_to_use": ["Aturan perusahaan, ujian, atau kontrak hukum yang tak ada toleransi pengecualian (''tidak peduli alasannya apa, keterlambatan tetap didenda'')", "Pernyataan hak yang setara (''tanpa memandang usia atau jenis kelamin, semua berhak mendaftar'')", "Konteks resmi pemerintahan, kebijakan kampus, dan syarat ketentuan lomba"], "formula_parts": [{"text": "Nomina (+ の)", "label": "Kondisi / Faktor yg diabaikan", "role": "noun"}, {"text": "いかんによらず / にかかわらず", "label": "Tanpa memandang apa pun", "role": "connector"}, {"text": "Ketentuan Tetap", "label": "Aturan tidak berubah", "role": "predicate"}], "steps": ["Pilih kata benda yang hasilnya belum pasti atau punya banyak variasi (contoh: 理由 = alasan, 結果 = hasil, 国籍 = kewarganegaraan, 天候 = cuaca).", "Tambahkan いかんによらず atau いかんにかかわらず (dengan atau tanpa の boleh, misal: 理由のいかんによらず / 理由いかんにかかわらず).", "Di bagian belakang, tegaskan aturan yang mutlak tetap sama rata bagi semuanya."], "breakdowns": [{"tokens": [{"jp": "りゆう", "reading": "riyuu", "meaning": "alasan", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "いかんによらず", "reading": "ikan ni yorazu", "meaning": "apa pun itu tanpa memandang", "role": "connector"}, {"jp": "ちこく", "reading": "chikoku", "meaning": "keterlambatan", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "みとめられません", "reading": "mitomeraremasen", "meaning": "tidak dapat ditoleransi", "role": "verb"}], "translation": "Terlepas dari apa pun alasannya, keterlambatan tidak dapat ditoleransi."}, {"tokens": [{"jp": "せいせき", "reading": "seiseki", "meaning": "nilai / hasil", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "いかんにかかわらず", "reading": "ikan ni kakawarazu", "meaning": "bagaimanapun hasilnya", "role": "connector"}, {"jp": "全員", "reading": "zen''in", "meaning": "semua peserta", "role": "subject"}, {"jp": "に", "reading": "ni", "meaning": "kepada", "role": "particle"}, {"jp": "さんかしょう", "reading": "sankashou", "meaning": "sertifikat partisipasi", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "だします", "reading": "dashimasu", "meaning": "diberikan", "role": "verb"}], "translation": "Tanpa memandang bagaimanapun nilainya, semua peserta akan mendapat sertifikat."}, {"tokens": [{"jp": "ねんれい", "reading": "nenrei", "meaning": "usia", "role": "noun"}, {"jp": "・", "reading": "", "meaning": "dan", "role": "connector"}, {"jp": "せいべつ", "reading": "seibetsu", "meaning": "jenis kelamin", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "いかんを問わず", "reading": "ikan o towazu", "meaning": "tanpa mempersoalkan", "role": "connector"}, {"jp": "おうぼできます", "reading": "oubo dekimasu", "meaning": "dapat melamar", "role": "verb"}], "translation": "Siapa pun dapat melamar tanpa memandang usia maupun jenis kelamin."}], "forms": [{"label": "Tanpa Memandang Alasan", "jp": "理由のいかんによらず", "reading": "riyuu no ikan ni yorazu", "id": "apa pun alasannya"}, {"label": "Variasi Umum", "jp": "結果のいかんにかかわらず", "reading": "kekka no ikan ni kakawarazu", "id": "apa pun hasilnya nanti"}, {"label": "Kontras: ～いかんだ", "jp": "きみのどりょくいかんだ", "reading": "kimi no doryoku ikan da", "id": "tergantung pada usahamu"}], "mistakes": [{"wrong": "大きい 小さい の いかんによらず", "right": "サイズの いかんによらず", "why": "Kata いかん selalu mengikuti KATA BENDA abstrak (seperti ''alasan'', ''hasil'', ''ukuran'', ''kadar''), tidak menempel ke kata sifat langsung."}, {"wrong": "いく いかんによらず", "right": "さんかの うむ にかかわらず", "why": "Tidak boleh langsung menempel ke kata kerja! Gunakan kata benda abstrak atau gunakan ～にかかわらず saja untuk pasangan verba (いく・いかないにかかわらず)."}], "quiz": [{"question": "Aturan kontrak berbunyi: ''天災（てんさい = bencana）以外の いかなる 理由 ___、解約料が 発生します'':", "options": ["の いかんによらず", "を 余儀なくされ", "に 至って", "ともなると"], "answer": 0, "why": "Menyatakan aturan berlaku mutlak tanpa memandang alasan apa pun menggunakan [Nomina] の いかんによらず."}, {"question": "Jika Anda melihat pola saudaranya yang tanpa ''よらず'', yakni ''すべては あなたの 努力 ___ です'' (ikan da / shidai da), artinya berubah menjadi:", "options": ["Sudah pasti gagal", "Tergantung bagaimana usahamu nanti", "Tidak usah berusaha", "Sudah selesai kemarin"], "answer": 1, "why": "いかん sendiri berarti ''bagaimana kondisinya''; dengan よらず artinya ''tak peduli kondisinya'', sedangkan いかんだ berarti ''tergantung pada kondisinya''."}, {"question": "Kata manakah yang TIDAK BISA dipasang tepat di depan のいかんによらず?", "options": ["経験（けいけん = pengalaman）", "事情（じじょう = keadaan）", "きれいな（cantik - Sifat-Na）", "結果（けっか = hasil）"], "answer": 2, "why": "いかん wajib didahului Kata Benda abstrak, bukan kata sifat."}]}'::jsonb WHERE code = 'GP-JA-N1-009';
UPDATE grammar_points SET learning_guide = '{"analogy": "～に足る (dibaca ni taru / ni tariru) artinya ''Cukup layak untuk...'', ''Pantas untuk...'', atau ''Bernilai untuk...''. Mirip ungkapan formal ''layak dipercaya'', ''pantas dipuji'', atau ''layak dibahas''.", "when_to_use": ["Menilai kredibilitas seseorang atau sumber informasi (''orang yang layak dipercaya'', ''data yang valid/pantas diandalkan'')", "Memberikan apresiasi tinggi atas karya atau pencapaian (''karya yang layak diapresiasi tinggi'')", "Bentuk negatifnya ～に足りない / ～に足らない artinya ''hal remeh yang tidak layak dipusingkan / tidak pantas diperhitungkan''"], "formula_parts": [{"text": "Nomina (Aksi) / Kamus Verba", "label": "Tindakan penilaian (percaya/puji)", "role": "verb"}, {"text": "に足る（にたる） / に足りない", "label": "Layak untuk / Tak pantas (remeh)", "role": "ending"}], "steps": ["Gunakan kata kerja evaluasi intelektual/etika (contoh: 信頼する = percaya, 尊敬する = hormat, 評価する = menilai positif, 驚く = kaget).", "Sambungkan dengan に足る (atau bentuk kamus lengkapnya に足りる). Kalau memakai kata benda aksi, boleh langsung Nomina + に足る (contoh: 信頼に足る = layak dipercaya).", "Bila menyebut masalah sepele yang tak perlu dirisaukan, pakai idiom terkenal: 心配する に足りない / 取るに足りない (''hal remeh / tak seberapa'')."], "breakdowns": [{"tokens": [{"jp": "かれ", "reading": "kare", "meaning": "dia", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "しんらい", "reading": "shinrai", "meaning": "kepercayaan", "role": "noun"}, {"jp": "に足る", "reading": "ni taru", "meaning": "yang layak (dipercaya)", "role": "verb"}, {"jp": "じんぶつ", "reading": "jinbutsu", "meaning": "sosok pribadi", "role": "predicate"}, {"jp": "だ", "reading": "da", "meaning": "(adalah)", "role": "ending"}], "translation": "Dia adalah sosok pribadi yang benar-benar layak dipercaya."}, {"tokens": [{"jp": "それは", "reading": "sore wa", "meaning": "hal itu", "role": "topic"}, {"jp": "とる", "reading": "toru", "meaning": "mengambil/hitung", "role": "verb"}, {"jp": "に足りない", "reading": "ni tarinai", "meaning": "tidak layak (remeh)", "role": "ending"}, {"jp": "ちいさな", "reading": "chiisana", "meaning": "kecil", "role": "adjective"}, {"jp": "ミス", "reading": "misu", "meaning": "kesalahan", "role": "predicate"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Itu hanyalah kesalahan kecil yang sepele (tak perlu dirisaukan)."}, {"tokens": [{"jp": "きみ", "reading": "kimi", "meaning": "kamu", "role": "topic"}, {"jp": "の", "reading": "no", "meaning": "(milik)", "role": "particle"}, {"jp": "けっか", "reading": "kekka", "meaning": "hasil kerja", "role": "subject"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "じゅうぶん", "reading": "juubun", "meaning": "sepenuhnya", "role": "adjective"}, {"jp": "しょうさん", "reading": "shousan", "meaning": "pujian", "role": "noun"}, {"jp": "に足りる", "reading": "ni tariru", "meaning": "layak mendapat", "role": "verb"}, {"jp": "もの", "reading": "mono", "meaning": "hal/capaian", "role": "predicate"}, {"jp": "だ", "reading": "da", "meaning": "(adalah)", "role": "ending"}], "translation": "Hasil kerjamu adalah capaian yang sepenuhnya layak mendapat pujian."}], "forms": [{"label": "Menerangkan Benda", "jp": "信頼に足るデータ", "reading": "shinrai ni taru deeta", "id": "data yang layak dipercaya"}, {"label": "Dengan Verba", "jp": "ほめるに足る行動", "reading": "homeru ni taru koudou", "id": "tindakan yang pantas dipuji"}, {"label": "Idiom Negatif (Remeh)", "jp": "取るに足りない問題", "reading": "toru ni tarinai mondai", "id": "masalah kecil yang tak perlu dipusingkan"}], "mistakes": [{"wrong": "おなかが すいたから、たべる に足る ケーキ", "right": "たべる かちが ある ケーキ", "why": "～に足る khusus untuk penilaian nilai moral, kepercayaan, kehormatan, atau analisis akademis — bukan sekadar layak makan atau layak dibeli di toko."}, {"wrong": "かれを しんらいした に足る", "right": "かれは しんらいする に足る / しんらいに足る", "why": "Bila memakai kata kerja, hanya boleh Bentuk Kamus (する), tidak boleh Bentuk-TA."}], "quiz": [{"question": "Apa arti idiom klasik JLPT N1 ''そんな 噂（うわさ = rumor）は 気にする に足りない''?", "options": ["Rumor itu sangat berbahaya dan harus dipercaya", "Rumor itu sama sekali tidak pantas dipusingkan / dihiraukan", "Kita wajib menyebarkan rumor tersebut", "Rumor itu layak diteliti lebih jauh"], "answer": 1, "why": "気にするに足りない artinya ''tidak cukup bernilai untuk dikhawatirkan / biarkan saja''."}, {"question": "Lengkapi: ''これは 専門家の 注目 ___ すぐれた 研究だ'' (Ini riset unggul yang layak mendapat perhatian para ahli; 注目 = perhatian/sorotan):", "options": ["に足る", "ともなると", "を余儀なくされる", "にかぎらず"], "answer": 0, "why": "注目 (kata benda perhatian) + に足る = ''layak untuk menjadi pusat perhatian''."}, {"question": "Manakah kalimat yang pemakaian ～に足る-nya PALING TEPAT?", "options": ["かれは 私たちの 代表として 尊敬（そんけい）に足る 人だ", "あしたの てんきは あめに 足る", "この カバンは ５千円に 足る", "きのう ともだちに あうに 足る"], "answer": 0, "why": "尊敬に足る (layak dihormati) adalah kolokasi standar N1 yang elegan."}]}'::jsonb WHERE code = 'GP-JA-N1-010';
UPDATE grammar_points SET learning_guide = '{"analogy": "～にあたって artinya ''Menjelang...'' atau ''Dalam rangka memulai...'' suatu acara besar, upacara, atau proyek penting. Nuansanya resmi dan penuh persiapan, jarang dipakai untuk kegiatan remeh harian.", "when_to_use": ["Memberi sambutan saat pembukaan proyek baru, rapat tahunan, atau acara resmi", "Menjelaskan persiapan penting sebelum pindah kota, masuk kuliah, atau menikah", "Pengumuman resmi perusahaan di email atau papan informasi"], "formula_parts": [{"text": "Nomina / Kamus Verba", "label": "Momen penting yg akan mulai", "role": "time"}, {"text": "にあたって / にあたり", "label": "Menjelang / Dalam rangka", "role": "connector"}, {"text": "Sambutan / Persiapan", "label": "Hal yang dilakukan", "role": "predicate"}], "steps": ["Pilih kata benda momen penting (contoh: しゅっぱつ = keberangkatan, けっこん = pernikahan) atau kata kerja bentuk kamus.", "Tambahkan にあたって (lisan resmi) atau にあたり (lebih sering di teks tertulis/pidato).", "Di bagian akhir kalimat, nyatakan persiapan, pesan khusus, atau ucapan terima kasih menyambut momen tersebut."], "breakdowns": [{"tokens": [{"jp": "しゅっぱつ", "reading": "shuppatsu", "meaning": "keberangkatan", "role": "time"}, {"jp": "にあたって", "reading": "ni atatte", "meaning": "menjelang", "role": "connector"}, {"jp": "みなさん", "reading": "minasan", "meaning": "semuanya", "role": "noun"}, {"jp": "に", "reading": "ni", "meaning": "kepada", "role": "particle"}, {"jp": "ごあいさつします", "reading": "goaisatsu shimasu", "meaning": "menyampaikan salam", "role": "verb"}], "translation": "Menjelang keberangkatan, saya menyampaikan salam perpisahan kepada semua."}, {"tokens": [{"jp": "あたらしい", "reading": "atarashii", "meaning": "baru", "role": "adjective"}, {"jp": "みせ", "reading": "mise", "meaning": "toko", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "ひらく", "reading": "hiraku", "meaning": "membuka (kamus)", "role": "verb"}, {"jp": "にあたって", "reading": "ni atatte", "meaning": "dalam rangka", "role": "connector"}, {"jp": "いろいろ", "reading": "iroiro", "meaning": "berbagai hal", "role": "object"}, {"jp": "じゅんびしました", "reading": "junbi shimashita", "meaning": "mempersiapkan", "role": "verb"}], "translation": "Menjelang membuka toko baru, saya sudah mempersiapkan berbagai hal."}, {"tokens": [{"jp": "しんせいひん", "reading": "shinseihin", "meaning": "produk baru", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(tentang)", "role": "particle"}, {"jp": "はつばい", "reading": "hatsubai", "meaning": "peluncuran/penjualan", "role": "noun"}, {"jp": "にあたり", "reading": "ni atari", "meaning": "dalam rangka", "role": "connector"}, {"jp": "イベント", "reading": "ibento", "meaning": "acara promo", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "おこないます", "reading": "okonaimasu", "meaning": "mengadakan", "role": "verb"}], "translation": "Dalam rangka peluncuran produk baru, kami akan mengadakan acara spesial."}], "forms": [{"label": "Resmi Lisan", "jp": "かいぎをはじめるにあたって", "reading": "kaigi o hajimeru ni atatte", "id": "menjelang memulai rapat"}, {"label": "Teks Pidato", "jp": "そつぎょうにあたり", "reading": "sotsugyou ni atari", "id": "dalam rangka kelulusan"}, {"label": "Menerangkan Benda", "jp": "あんぜんにあたってのルール", "reading": "ni atatte no ruuru", "id": "aturan menyambut acara tersebut"}], "mistakes": [{"wrong": "まいあさ ごはんを たべるにあたって、てを あらいます", "right": "ごはんを たべる まえに、てを あらいます", "why": "Jangan pakai にあたって untuk rutinitas sepele setiap hari; pola ini khusus tonggak acara atau kejadian besar."}, {"wrong": "しんねん が おわった にあたって", "right": "しんねん を むかえる にあたって", "why": "にあたって artinya ''menjelang/saat memulai sesuatu yang baru'', bukan setelah selesai lama lalu menyesal."}], "quiz": [{"question": "Situasi manakah yang PALING WAJAR memakai ～にあたって?", "options": ["Menjelang tidur malam seperti biasa", "Saat memberikan pidato pembukaan proyek besar di kantor", "Saat lupa membawa payung di tengah hujan", "Saat menyapa tetangga di lift"], "answer": 1, "why": "Pola ini berkesan formal dan cocok untuk pembukaan acara, proyek, atau babak hidup baru."}, {"question": "Lengkapi: ''にほん へ りゅうがく ___ にあたって、いろいろな ほけんに はいった'' (Menjelang berangkat studi ke Jepang, ikut asuransi):", "options": ["する", "した", "して", "しよう"], "answer": 0, "why": "Kata kerja yang menempel sebelum にあたって selalu memakai Bentuk Kamus (する)."}, {"question": "Apa perbedaan にあたり dibanding にあたって?", "options": ["にあたり lebih formal / khas bahasa tulisan & pidato resmi", "にあたり artinya ''setelah''", "あたり dipakai hanya untuk bentuk negatif", "Keduanya berbeda arti sepenuhnya"], "answer": 0, "why": "にあたり adalah bentuk yang sedikit lebih ringkas dan sering ditemukan di pidato, surat resmi, atau artikel berita."}]}'::jsonb WHERE code = 'GP-JA-N2-001';
UPDATE grammar_points SET learning_guide = '{"analogy": "～に伴って artinya ''Seiring dengan berubahnya A, maka B pun ikut berubah''. Bayangkan dua hal bergerak bareng dalam satu arah (misalnya: seiring bertambahnya usia, tenaga berkurang).", "when_to_use": ["Berita ekonomi atau sosial (''seiring tumbuhnya AI, cara kerja ikut berubah'')", "Perubahan alam atau jumlah penduduk (''seiring naiknya suhu, pemakaian AC meningkat'')", "Menceritakan konsekuensi dari perluasan perusahaan atau bertambahnya jumlah siswa"], "formula_parts": [{"text": "Nomina / Kamus Verba", "label": "Perubahan pertama", "role": "noun"}, {"text": "に伴って（ともなって）", "label": "Seiring dengan", "role": "connector"}, {"text": "Perubahan Kedua", "label": "Efek yang ikut bergerak", "role": "predicate"}], "steps": ["Pastikan bagian depan mengandung makna PERUBAHAN atau PERGERAKAN (seperti ''bertambah'', ''meningkat'', ''pembangunan'', ''menurun'').", "Tambahkan に伴って di tengah kalimat (bisa juga ditulis dengan Hiragana にともなって).", "Jika diletakkan langsung di depan Kata Benda (''masalah yang menyertai perkembangan kota''), ubah menjadi に伴う + Nomina."], "breakdowns": [{"tokens": [{"jp": "じんこう", "reading": "jinkou", "meaning": "jumlah penduduk", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "ふえる", "reading": "fueru", "meaning": "bertambah", "role": "verb"}, {"jp": "に伴って", "reading": "ni tomonatte", "meaning": "seiring dengan", "role": "connector"}, {"jp": "ゴミ", "reading": "gomi", "meaning": "sampah", "role": "subject"}, {"jp": "も", "reading": "mo", "meaning": "juga", "role": "particle"}, {"jp": "ふえました", "reading": "fuemashita", "meaning": "bertambah", "role": "verb"}], "translation": "Seiring bertambahnya penduduk, sampah pun ikut meningkat."}, {"tokens": [{"jp": "ぎじゅつ", "reading": "gijutsu", "meaning": "teknologi", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "しんぽ", "reading": "shinpo", "meaning": "kemajuan", "role": "noun"}, {"jp": "に伴って", "reading": "ni tomonatte", "meaning": "seiring dengan", "role": "connector"}, {"jp": "せいかつ", "reading": "seikatsu", "meaning": "gaya hidup", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "べんりに", "reading": "benri ni", "meaning": "menjadi praktis", "role": "adjective"}, {"jp": "なりました", "reading": "narimashita", "meaning": "telah menjadi", "role": "verb"}], "translation": "Seiring kemajuan teknologi, hidup pun menjadi semakin praktis."}, {"tokens": [{"jp": "たいふう", "reading": "taifuu", "meaning": "topan", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "せっきん", "reading": "sekkin", "meaning": "kedatangan mendekat", "role": "noun"}, {"jp": "に伴い", "reading": "ni tomonai", "meaning": "seiring", "role": "connector"}, {"jp": "かぜ", "reading": "kaze", "meaning": "angin", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "つよくなってきました", "reading": "tsuyoku natte kimashita", "meaning": "semakin kencang", "role": "adjective"}], "translation": "Seiring semakin dekatnya topan, angin mulai bertiup semakin kencang."}], "forms": [{"label": "Dengan Verba", "jp": "としをとるに伴って", "reading": "toshi o toru ni tomonatte", "id": "seiring bertambahnya umur"}, {"label": "Dengan Nomina", "jp": "かいかくに伴って", "reading": "kaikaku ni tomonatte", "id": "seiring dengan reformasi"}, {"label": "Menerangkan Benda", "jp": "引っ越しに伴う費用", "reading": "hikkoshi ni tomonau hiyou", "id": "biaya yang menyertai pindahan"}], "mistakes": [{"wrong": "この みせは やすくて、おいしい に伴って にんきです", "right": "やすくて おいしい ので、にんきです", "why": "Tidak boleh dipakai untuk kata sifat statis tanpa unsur perubahan/perkembangan."}, {"wrong": "きゅうりょうが さがるにともなって の せいかつ", "right": "きゅうりょう げんしょう にともなう せいかつ", "why": "Bila memodifikasi kata benda langsung, ganti menjadi ～に伴う (ni tomonau)."}], "quiz": [{"question": "Kalimat mana yang pemakaian ～に伴って-nya PALING ALAMI?", "options": ["ケーキが おいしいのに ともなって、もう ひとつ たべました", "オンラインじゅぎょうが ふえるに ともなって、パソコンの じゅようも たかまった", "きのう ともだちに あうに ともなって、えいがを みた", "へやが しずかに ともなって、ねむりやすい"], "answer": 1, "why": "Pertambahan kelas online beriringan dengan naiknya permintaan laptop mencerminkan dua tren yang bergerak bersama."}, {"question": "Pilih bentuk yang tepat sebelum kata benda: ''引っ越し ___ いろいろな てつづき (berbagai prosedur terkait pindahan)'':", "options": ["に伴って", "に伴う", "に伴いの", "に伴っての"], "answer": 1, "why": "Jika menerangkan nomina tepat di belakangnya, pakailah bentuk kamus ～に伴う."}, {"question": "Mengapa kata kerja ''ふえる'' (bertambah) cocok sekali dipasangkan dengan ～に伴って?", "options": ["Karena singkat hurufnya", "Karena mengandung proses perubahan jumlah/skala yang memicu dampak ikutannya", "Karena khusus untuk anak-anak", "Karena bermakna larangan"], "answer": 1, "why": "に伴う/に伴って menekankan perubahan A berjalan seiring dan menyebabkan perubahan B."}]}'::jsonb WHERE code = 'GP-JA-N2-002';
UPDATE grammar_points SET learning_guide = '{"analogy": "～に限らず artinya ''Tidak terbatas pada A saja, tapi juga B, C, dan lainnya!''. Sama persis seperti ungkapan Indonesia ''Bukan cuma [X] doang, tapi semua orang/bidang juga ikut...''.", "when_to_use": ["Menunjukkan popularitas sesuatu melebar luas (''film ini tidak cuma disukai anak-anak, tapi juga orang dewasa'')", "Aturan berlaku umum bagi siapa pun tanpa terkecuali (''tidak hanya pegawai tetap, pekerja paruh waktu pun ikut rapat'')", "Menyoroti fenomena di berbagai kota atau negara (''bukan cuma di Tokyo, di daerah pun harga naik'')"], "formula_parts": [{"text": "Nomina (Contoh Sempit)", "label": "Kategori awal", "role": "noun"}, {"text": "に限らず（にかぎらず）", "label": "Tidak terbatas pada", "role": "connector"}, {"text": "Cakupan Lebih Luas (...も)", "label": "Yang lainnya juga", "role": "predicate"}], "steps": ["Sebutkan kategori sempit yang biasanya paling menonjol di depan (contoh: わかもの = anak muda, ニホン = Jepang).", "Tempelkan に限らず (atau versi agak lebih kaku にかぎらず).", "Di bagian belakang, sebutkan bahwa cakupannya meluas memakai partikel も atau ungkapan universal (おとなも = orang dewasa juga, せかいじゅうで = di seluruh dunia)."], "breakdowns": [{"tokens": [{"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "アニメ", "reading": "anime", "meaning": "anime", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "こども", "reading": "kodomo", "meaning": "anak-anak", "role": "noun"}, {"jp": "に限らず", "reading": "ni kagirazu", "meaning": "tidak terbatas pada", "role": "connector"}, {"jp": "おとな", "reading": "otona", "meaning": "orang dewasa", "role": "noun"}, {"jp": "にも", "reading": "ni mo", "meaning": "juga bagi", "role": "particle"}, {"jp": "にんきがある", "reading": "ninki ga aru", "meaning": "populer", "role": "adjective"}], "translation": "Anime ini tidak hanya digemari anak-anak, tetapi populer juga di kalangan orang dewasa."}, {"tokens": [{"jp": "しゅうまつ", "reading": "shuumatsu", "meaning": "akhir pekan", "role": "time"}, {"jp": "に限らず", "reading": "ni kagirazu", "meaning": "tidak terbatas pada", "role": "connector"}, {"jp": "へいじつ", "reading": "heijitsu", "meaning": "hari kerja biasa", "role": "time"}, {"jp": "も", "reading": "mo", "meaning": "pun", "role": "particle"}, {"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "カフェ", "reading": "kafe", "meaning": "kafe", "role": "subject"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "こんでいます", "reading": "konde imasu", "meaning": "selalu ramai", "role": "verb"}], "translation": "Tidak hanya akhir pekan, di hari biasa pun kafe ini selalu ramai."}, {"tokens": [{"jp": "しんじん", "reading": "shinjin", "meaning": "karyawan baru", "role": "noun"}, {"jp": "に限らず", "reading": "ni kagirazu", "meaning": "tak terkecuali", "role": "connector"}, {"jp": "だれでも", "reading": "dare demo", "meaning": "siapa saja", "role": "subject"}, {"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "けんしゅう", "reading": "kenshuu", "meaning": "pelatihan", "role": "noun"}, {"jp": "に", "reading": "ni", "meaning": "pada", "role": "particle"}, {"jp": "さんかできます", "reading": "sanka dekimasu", "meaning": "bisa ikut", "role": "verb"}], "translation": "Tidak terbatas pada karyawan baru saja, siapa pun dapat mengikuti pelatihan ini."}], "forms": [{"label": "Kelompok Orang", "jp": "がくせいに限らず", "reading": "gakusei ni kagirazu", "id": "bukan cuma mahasiswa"}, {"label": "Waktu", "jp": "なつに限らず一年中", "reading": "natsu ni kagirazu ichinenjuu", "id": "bukan cuma musim panas, sepanjang tahun"}, {"label": "Modifikasi Benda", "jp": "日本に限らず多くの国", "reading": "Nihon ni kagirazu ooku no kuni", "id": "bukan cuma Jepang, tapi banyak negara"}], "mistakes": [{"wrong": "わたしは すし に限らず たべたいです", "right": "すし に限らず、日本りょうりは なんでも すきです", "why": "Di bagian belakang wajib ada makna cakupan yang LEBIH LUAS (''apa saja / semuanya juga''), tidak bisa hanya menyebut satu kejadian sempit."}, {"wrong": "たべる に限らず", "right": "たべもの に限らず", "why": "Pola ini langsung menempel pada KATA BENDA (tidak menempel langsung ke kata kerja tanpa pembendaan)."}], "quiz": [{"question": "Lengkapi: ''りょうり ___、なんでも 自分で 作るのが 趣味です'' (Bukan cuma soal masakan saja, bikin apa pun sendiri adalah hobinya):", "options": ["に限らず", "にあたり", "に伴い", "に限って"], "answer": 0, "why": "に限らず memperluas topik dari contoh awal (masakan) ke cakupan menyeluruh (apa pun)."}, {"question": "Bedakan ～に限らず vs ～に限って. Manakah yang artinya ''Tidak terbatas pada...''?", "options": ["～に限って", "～に限らず", "Keduanya persis sama", "Tidak ada yang benar"], "answer": 1, "why": "～に限らず berasal dari bentuk negatif ''tanpa membatasi'', sedangkan に限って artinya ''justru di saat itu...'' / ''khusus...''."}, {"question": "Kalimat mana yang menggunakan ～に限らず dengan benar?", "options": ["日本語に限らず、英語や 中国語も はなせます", "はしるに限らず、およぐのも すき", "きのうに限らず、とても さむかった", "あなたに限らず、わたしも いきたくない"], "answer": 0, "why": "Dari bahasa Jepang melebar ke bahasa Inggris dan Mandarin juga, memakai kata benda 日本語 di depan に限らず."}]}'::jsonb WHERE code = 'GP-JA-N2-003';
UPDATE grammar_points SET learning_guide = '{"analogy": "～わけにはいかない artinya ''Mana mungkin bisa...'' atau ''Tidak mungkin tega / etis berbuat begitu'' karena terikat janji, etika sosial, tanggung jawab kerja, atau perasaan hati — walau fisikmu sebenarnya masih mampu!", "when_to_use": ["Menolak halus tawaran karena terikat tanggung jawab (''walau capek, nggak bisa seenaknya bolos kerja'')", "Menjaga rahasia atau janji pribadi (''sudah berjanji, jadi nggak mungkin saya bocorkan'')", "Merasa segan menolak pemberian atau bantuan karena keadaan sosial (''nggak enak hati kalau tidak datang ke pesta teman'')"], "formula_parts": [{"text": "Kamus Verba / Bentuk-NAI", "label": "Hal yg dilarang moral/janji", "role": "verb"}, {"text": "わけにはいかない", "label": "Tidak mungkin bisa dilakukan", "role": "ending"}], "steps": ["Pakai Bentuk Kamus kalau maksudnya ''nggak bisa/nggak etis berbuat itu'' (contoh: やめるわけにはいかない = nggak bisa berhenti tengah jalan).", "Pakai Bentuk-NAI kalau maksudnya ''MAU TIDAK MAU harus...'' (contoh: いかないわけにはいかない = nggak mungkin nggak pergi → mau tak mau harus datang).", "Jangan tertukar dengan できない (nggak bisa secara fisik/kemampuan)! Pola ini khusus hambatan moral, janji, atau aturan sosial."], "breakdowns": [{"tokens": [{"jp": "たいせつな", "reading": "taisetsu na", "meaning": "penting", "role": "adjective"}, {"jp": "やくそく", "reading": "yakusoku", "meaning": "janji", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "やぶる", "reading": "yaburu", "meaning": "melanggar", "role": "verb"}, {"jp": "わけにはいかない", "reading": "wake ni wa ikanai", "meaning": "tidak mungkin boleh", "role": "ending"}], "translation": "Saya tidak mungkin melanggar janji yang penting itu."}, {"tokens": [{"jp": "あした", "reading": "ashita", "meaning": "besok", "role": "time"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "しけん", "reading": "shiken", "meaning": "ujian", "role": "noun"}, {"jp": "なので", "reading": "na node", "meaning": "karena", "role": "connector"}, {"jp": "きょう", "reading": "kyou", "meaning": "hari ini", "role": "time"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "あそぶ", "reading": "asobu", "meaning": "main-main", "role": "verb"}, {"jp": "わけにはいきません", "reading": "wake ni wa ikimasen", "meaning": "tidak etis / mana bisa", "role": "ending"}], "translation": "Karena besok ada ujian, mana mungkin hari ini saya bersantai main-main."}, {"tokens": [{"jp": "ぶちょう", "reading": "buchou", "meaning": "kepala divisi", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(milik)", "role": "particle"}, {"jp": "けっこんしき", "reading": "kekkonshiki", "meaning": "pesta nikah", "role": "noun"}, {"jp": "だから", "reading": "dakara", "meaning": "karena", "role": "connector"}, {"jp": "しゅっせきしない", "reading": "shusseki shinai", "meaning": "tidak hadir (NAI)", "role": "verb"}, {"jp": "わけにはいきません", "reading": "wake ni wa ikimasen", "meaning": "tidak mungkin tidak hadir", "role": "ending"}], "translation": "Karena ini pesta nikah kepala divisi, mau tidak mau saya harus hadir."}], "forms": [{"label": "Tidak Etis Dilakukan", "jp": "ひみつをはなすわけにはいかない", "reading": "himitsu o hanasu wake ni wa ikanai", "id": "tidak boleh membocorkan rahasia"}, {"label": "Terpaksa Harus Hadir", "jp": "いかないわけにはいかない", "reading": "ikanai wake ni wa ikanai", "id": "mau tidak mau harus pergi"}, {"label": "Versi Sopan", "jp": "おことわりするわけにはまいりません", "reading": "okotowari suru wake ni wa mairimasen", "id": "tidak mungkin dapat kami tolak (sgt resmi)"}], "mistakes": [{"wrong": "およぎかたを しらないから、およぐ わけにはいかない", "right": "およぎかたを しらないから、およぐ ことが できない", "why": "Bila tidak bisa karena kemampuan teknis/fisik (tidak bisa berenang), pakailah ことができない / わけにはいかない salah konteks karena itu bukan masalah etika/janji."}, {"wrong": "くるまを うんてんしない わけにはいかない (mau nyetir padahal ngantuk)", "right": "ねむいから、うんてんする わけにはいかない", "why": "Hati-hati logika negatif ganda! [tidak menyetir] + wake ni wa ikanai artinya ''mau tak mau HARUS menyetir''."}], "quiz": [{"question": "Sudah berjanji tidak memberi tahu siapa pun. Kalimat yang tepat: ''かれとの やくそくだから、だれにも ___ わけにはいかない'':", "options": ["いう", "いわない", "いえない", "いった"], "answer": 0, "why": "Secara etika menjaga janji tidak mungkin bisa membocorkannya (いう = mengatakan)."}, {"question": "Apa makna kalimat \"ぶちょうの けっこんしきだから、いかない わけにはいかない\"?", "options": ["Tidak usah datang", "Mau tidak mau harus datang (tidak enak kalau absen)", "Dilarang keras datang", "Tidak bisa datang karena sakit"], "answer": 1, "why": "Negatif ganda (tidak pergi + tidak mungkin bisa) bermakna mau tidak mau harus hadir."}, {"question": "Situasi manakah yang BENAR memakai ～わけにはいかない?", "options": ["Tangan patah sehingga tak kuat menulis -> かく わけにはいかない", "Belum belajar kanji sehingga tidak bisa baca -> よむ わけにはいかない", "Teman baik mengundang ke nikahannya, jadi nggak enak kalau absen -> いかない わけにはいかない", "Harga mobil mahal sekali -> かう わけにはいかない"], "answer": 2, "why": "Undangan teman baik mengikat secara etika dan perasaan sosial, bukan ketidakmampuan fisik."}]}'::jsonb WHERE code = 'GP-JA-N2-004';
UPDATE grammar_points SET learning_guide = '{"analogy": "～ざるを得ない artinya ''Terpaksa mau tidak mau harus...'' meski di lubuk hati sebenarnya keberatan atau berat hati sekali. Lebih formal dan serius dibanding ～なければならない.", "when_to_use": ["Mengambil keputusan berat demi keadaan (harus menutup cabang toko yang merugi, menunda acara karena badai)", "Terpaksa mengakui kesalahan atau menerima konsekuensi logis meski enggan", "Bahasa laporan bisnis, artikel hukum, atau pengumuman resmi krisis"], "formula_parts": [{"text": "Bentuk-NAI (tanpa ない)", "label": "Akar verba (-a)", "role": "verb"}, {"text": "ざるを得ない（ざるをえない）", "label": "Terpaksa harus", "role": "ending"}], "steps": ["Ubah kata kerja ke Bentuk-NAI lalu buang kata ない (misal: やめる → やめ, いく → いか, あきらめる → あきらめ).", "INGAT 1 PENGECUALIAN WAJIB: Kata kerja する TIDAK menjadi しざるを得ない, melainkan WAJIB menjadi せざるを得ない!", "Tambahkan ざるを得ない (atau bentuk sopannya ざるを得ません) di paling akhir."], "breakdowns": [{"tokens": [{"jp": "たいふう", "reading": "taifuu", "meaning": "topan", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "ため", "reading": "tame", "meaning": "karena", "role": "connector"}, {"jp": "りょこう", "reading": "ryokou", "meaning": "wisata", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "ちゅうしせざるを得ない", "reading": "chuushi sezaru o enai", "meaning": "terpaksa harus membatalkan", "role": "verb"}], "translation": "Karena ada topan, kami terpaksa harus membatalkan wisata."}, {"tokens": [{"jp": "あんな", "reading": "anna", "meaning": "begitu kuat", "role": "noun"}, {"jp": "しょうこ", "reading": "shouko", "meaning": "bukti", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "みせられたら", "reading": "miseraretara", "meaning": "kalau diperlihatkan", "role": "verb"}, {"jp": "じぶん", "reading": "jibun", "meaning": "diri sendiri", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(milik)", "role": "particle"}, {"jp": "ミス", "reading": "misu", "meaning": "kesalahan", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "みとめざるを得ない", "reading": "mitomezaru o enai", "meaning": "terpaksa harus mengakui", "role": "verb"}], "translation": "Kalau sudah ditunjukkan bukti begitu, mau tidak mau harus mengakui kesalahan sendiri."}, {"tokens": [{"jp": "おかね", "reading": "okane", "meaning": "uang", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "たりない", "reading": "tarinai", "meaning": "tidak cukup", "role": "verb"}, {"jp": "ので", "reading": "node", "meaning": "karena", "role": "connector"}, {"jp": "けいかく", "reading": "keikaku", "meaning": "rencana", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "へんこうせざるを得ません", "reading": "henkou sezaru o emasen", "meaning": "terpaksa harus mengubah", "role": "verb"}], "translation": "Karena dananya kurang, kami terpaksa harus mengubah rencana."}], "forms": [{"label": "Verba Biasa", "jp": "あきらめざるを得ない", "reading": "akiramezaru o enai", "id": "terpaksa menyerah"}, {"label": "Verba する (Pengecualian!)", "jp": "ちゅうしせざるを得ない", "reading": "chuushi sezaru o enai", "id": "terpaksa membatalkan"}, {"label": "Bentuk Sopan", "jp": "ちゅうしせざるを得ません", "reading": "chuushi sezaru o emasen", "id": "terpaksa harus dibatalkan (sopan)"}], "mistakes": [{"wrong": "しごとを やめるしざるを得ない / しざるを得ない", "right": "しごとを やめざるを得ない / せざるを得ない", "why": "Khusus kata kerja する wajib berubah menjadi せざるを得ない (bukan しざる)."}, {"wrong": "たのしい ので、わらう ざるを得ない", "right": "おもしろくて わらわざるを得ない", "why": "Bentuk yang ditempeli ざるを得ない adalah akar Bentuk-NAI (warawanai → warawa + zaru o enai), bukan bentuk kamus."}], "quiz": [{"question": "Bagaimana menyambungkan kata kerja する (melakukan, misal 延期する = menunda) ke ～ざるを得ない?", "options": ["延期しざるを得ない", "延期するざるを得ない", "延期せざるを得ない", "延期さざるを得ない"], "answer": 2, "why": "Pengecualian tunggal penting di JLPT: する selalu menjadi せざるを得ない."}, {"question": "Bagaimana mengubah いいます (mengatakan -> いわない) menjadi ''terpaksa harus mengatakan''?", "options": ["いわずを得ない", "いわざるを得ない", "いうざるを得ない", "いわないざるを得ない"], "answer": 1, "why": "Ambil Bentuk-NAI (いわない), hilangkan ない (いわ), lalu tambah ざるを得ない."}, {"question": "Apa kesan yang ditangkap pendengar saat kamu memakai ～ざるを得ない?", "options": ["Pembicara melakukannya dengan penuh sukacita", "Pembicara sebenarnya tidak ingin, tapi kondisi memaksanya harus melakukannya", "Pembicara masih ragu-ragu mau atau tidak", "Pembicara melarang orang lain"], "answer": 1, "why": "Pola ini menunjukkan keputusan terpaksa di luar keinginan karena desakan situasi."}]}'::jsonb WHERE code = 'GP-JA-N2-005';
UPDATE grammar_points SET learning_guide = '{"analogy": "～にもかかわらず artinya persis ''Meskipun / Walaupun begitu tetap saja...'' dalam gaya bahasa yang tegas, rapi, dan cukup formal (lebih kuat dan berwibawa daripada ～のに atau ～ても).", "when_to_use": ["Menulis berita atau laporan analitis (''meskipun harga sudah diturunkan, penjualannya tetap sepi'')", "Menghargai usaha seseorang di luar dugaan (''walaupun sangat sibuk, beliau meluangkan waktu datang'')", "Mengungkapkan rasa kecewa atau heran secara formal"], "formula_parts": [{"text": "Nomina / Bentuk Biasa (tanpa だ)", "label": "Fakta kondisi awal", "role": "noun"}, {"text": "にもかかわらず", "label": "Meskipun demikian", "role": "connector"}, {"text": "Hasil Berlawanan", "label": "Kenapa tetap bertolak belakang", "role": "predicate"}], "steps": ["Tulis fakta awalnya terlebih dahulu (misal: あめ = hujan, いそがしい = sibuk, どりょくした = sudah berusaha keras).", "PENTING: Untuk Kata Benda dan Sifat-Na, TIDAK memakai だ atau な! Langsung saja tempelkan にもかかわらず (contoh: びょうき にもかかわらず, しずか にもかかわらず).", "Untuk Verba atau Sifat-I, memakai Bentuk Biasa langsung + にもかかわらず."], "breakdowns": [{"tokens": [{"jp": "おおあめ", "reading": "ooame", "meaning": "hujan lebat", "role": "noun"}, {"jp": "にもかかわらず", "reading": "ni mo kakawarazu", "meaning": "meskipun", "role": "connector"}, {"jp": "おおぜい", "reading": "oozei", "meaning": "banyak orang", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "あつまりました", "reading": "atsumarimashita", "meaning": "berkumpul hadir", "role": "verb"}], "translation": "Meskipun hujan lebat, banyak sekali orang tetap hadir berkumpul."}, {"tokens": [{"jp": "かれ", "reading": "kare", "meaning": "dia", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "なんども", "reading": "nando mo", "meaning": "berkali-kali", "role": "time"}, {"jp": "ちゅういされた", "reading": "chuui sareta", "meaning": "sudah diperingatkan", "role": "verb"}, {"jp": "にもかかわらず", "reading": "ni mo kakawarazu", "meaning": "padahal / walaupun", "role": "connector"}, {"jp": "また", "reading": "mata", "meaning": "lagi-lagi", "role": "time"}, {"jp": "おなじ", "reading": "onaji", "meaning": "sama", "role": "adjective"}, {"jp": "ミス", "reading": "misu", "meaning": "kesalahan", "role": "object"}, {"jp": "をした", "reading": "o shita", "meaning": "melakukan", "role": "verb"}], "translation": "Meskipun sudah berkali-kali diperingatkan, dia tetap mengulangi kesalahan yang sama."}, {"tokens": [{"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "みせ", "reading": "mise", "meaning": "toko", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "ねだん", "reading": "nedan", "meaning": "harga", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "たかい", "reading": "takai", "meaning": "mahal", "role": "adjective"}, {"jp": "にもかかわらず", "reading": "ni mo kakawarazu", "meaning": "meskipun", "role": "connector"}, {"jp": "いつも", "reading": "itsumo", "meaning": "selalu", "role": "time"}, {"jp": "まんせき", "reading": "manseki", "meaning": "penuh sesak", "role": "predicate"}, {"jp": "だ", "reading": "da", "meaning": "(adalah)", "role": "ending"}], "translation": "Toko ini meskipun harganya mahal, selalu penuh sesak."}], "forms": [{"label": "Kata Benda", "jp": "きゅうじつ にもかかわらず", "reading": "kyuujitsu ni mo kakawarazu", "id": "meskipun hari libur"}, {"label": "Sifat-Na", "jp": "ふべんにもかかわらず", "reading": "fuben ni mo kakawarazu", "id": "meskipun tidak praktis"}, {"label": "Awal Kalimat Baru", "jp": "それにもかかわらず", "reading": "sore ni mo kakawarazu", "id": "meskipun demikian, ..."}], "mistakes": [{"wrong": "やすみ な にもかかわらず / やすみ だ にもかかわらず", "right": "やすみ にもかかわらず", "why": "Bila didahului Kata Benda (やすみ) atau Sifat-Na (ふべん), buang だ/な seluruhnya sebelum にもかかわらず! (untuk bentuk lampau, boleh memakai ～だった にもかかわらず)."}, {"wrong": "ねむい にもかかわらず、すぐ ねました", "right": "ねむい にもかかわらず、べんきょうを つづけました", "why": "Kalimat di belakang harus bertolak belakang (lawan logika) dengan kalimat di depan."}], "quiz": [{"question": "Lengkapi: ''かれは まだ わか___ にもかかわらず、会社の リーダーを まかされている'' (Meski masih muda...):", "options": ["わかい だ", "わかい な", "わかい", "わかく"], "answer": 2, "why": "わかい adalah kata sifat-i, sehingga langsung menempel apa adanya sebelum にもかかわらず."}, {"question": "Bagaimana memakai Kata Benda びょうき (penyakit) di depan にもかかわらず?", "options": ["びょうき にもかかわらず", "びょうき な にもかかわらず", "びょうき だ にもかかわらず", "びょうき の にもかかわらず"], "answer": 0, "why": "Kata Benda & Sifat-Na langsung ditempelkan tanpa partikel な maupun だ."}, {"question": "Apa arti penghubung antarkalimat ''それにもかかわらず''?", "options": ["Oleh karena itu", "Meskipun demikian / Kendati begitu", "Selain itu", "Dengan kata lain"], "answer": 1, "why": "それにもかかわらず berdiri di awal kalimat kedua untuk membalik fakta kalimat pertama."}]}'::jsonb WHERE code = 'GP-JA-N2-006';
UPDATE grammar_points SET learning_guide = '{"analogy": "～上で (dibaca ~ue de) artinya ''Setelah mempertimbangkan / menyelesaikan tahap A lebih dulu, barulah melangkah ke tahap B'' atau ''Dalam hal / Untuk keperluan...''.", "when_to_use": ["Prosedur resmi (''setelah berdiskusi dengan keluarga, baru memutuskan''; ''setelah baca ketentuan kontrak, baru tanda tangan'')", "Menyebutkan aspek pertimbangan tertentu (''sangat penting dari segi kesehatan / belajar'')", "Konteks bisnis, aturan, dan keputusan yang butuh pertimbangan matang"], "formula_parts": [{"text": "Bentuk-TA / Nomina + の", "label": "Tahap persiapan / Bidang", "role": "verb"}, {"text": "上で（うえで）", "label": "Setelah ... baru / Dalam hal", "role": "connector"}, {"text": "Keputusan / Penilaian", "label": "Langkah utama", "role": "predicate"}], "steps": ["Jika bermakna tahapan berurutan (''setelah melakukan A, baru kerjakan B''): taruh Verba Bentuk-TA atau Nomina + の di depan 上で.", "Jika bermakna ''dalam hal melakukan X'' / ''dari sudut pandang X'' (seperti ''penting dalam hidup di Jepang''): pakai Kamus Verba + 上で atau Nomina + 上(で).", "Bentuk negatifnya diletakkan di bagian belakang kalimat atau memakai kata benda pertimbangan."], "breakdowns": [{"tokens": [{"jp": "よく", "reading": "yoku", "meaning": "dengan matang", "role": "adjective"}, {"jp": "かんがえた", "reading": "kangaeta", "meaning": "sudah memikirkan (TA)", "role": "verb"}, {"jp": "上で", "reading": "ue de", "meaning": "setelah mempertimbangkan baru", "role": "connector"}, {"jp": "へんじ", "reading": "henji", "meaning": "jawaban", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "します", "reading": "shimasu", "meaning": "saya beri", "role": "verb"}], "translation": "Setelah memikirkannya matang-matang, baru saya akan memberi jawaban."}, {"tokens": [{"jp": "かぞく", "reading": "kazoku", "meaning": "keluarga", "role": "noun"}, {"jp": "と", "reading": "to", "meaning": "bersama", "role": "particle"}, {"jp": "そうだん", "reading": "soudan", "meaning": "diskusi", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "上で", "reading": "ue de", "meaning": "setelah selesai", "role": "connector"}, {"jp": "きめました", "reading": "kimemashita", "meaning": "kami memutuskan", "role": "verb"}], "translation": "Kami memutuskannya setelah berdiskusi dengan keluarga."}, {"tokens": [{"jp": "日本", "reading": "Nihon", "meaning": "Jepang", "role": "place"}, {"jp": "で", "reading": "de", "meaning": "di", "role": "particle"}, {"jp": "はたらく", "reading": "hataraku", "meaning": "bekerja (kamus)", "role": "verb"}, {"jp": "上で", "reading": "ue de", "meaning": "dalam hal / untuk", "role": "connector"}, {"jp": "けいご", "reading": "keigo", "meaning": "bahasa hormat", "role": "subject"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "とても", "reading": "totemo", "meaning": "sangat", "role": "adjective"}, {"jp": "たいせつです", "reading": "taisetsu desu", "meaning": "penting", "role": "adjective"}], "translation": "Dalam hal bekerja di Jepang, keigo sangatlah penting."}], "forms": [{"label": "Urutan Matang (Bentuk-TA)", "jp": "じょうけんをかくにんした上で", "reading": "jouken o kakunin shita ue de", "id": "setelah memastikan syaratnya"}, {"label": "Nomina (+の)", "jp": "じゅうぶんちゅういのうえで", "reading": "juubun chuui no ue de", "id": "dengan kehati-hatian penuh"}, {"label": "Aspek / Bidang (Kamus)", "jp": "べんきょうする上で", "reading": "benkyou suru ue de", "id": "dalam hal belajar"}], "mistakes": [{"wrong": "あさ ごはんを たべた 上で、はを みがきます", "right": "あさ ごはんを たべてから、はを みがきます", "why": "Untuk rutinitas sepele sehari-hari tanpa unsur persiapan keputusan/prosedur serius, gunakan ～てから. ～た上で bernuansa tindakan bermakna."}, {"wrong": "そうだん 上で きめます", "right": "そうだん の 上で きめます", "why": "Kata Benda wajib menyisipkan の sebelum 上で (atau memakai Bentuk-TA そうだんした 上で)."}], "quiz": [{"question": "Lengkapi kontrak: ''内容（ないよう）を よく ___ 上で、サインしてください'' (Setelah memahami isinya dengan baik, baru tanda tangan; りかいする = memahami):", "options": ["りかいする", "りかいした", "りかいして", "りかい"], "answer": 1, "why": "Untuk urutan tahap (''setelah melakukan A, baru B''), wajib memakai Bentuk-TA (りかいした)."}, {"question": "Apa perbedaan makna kalimat ''日本に住む 上で、ルールを知ることが大切だ'' (pakai bentuk kamus)?", "options": ["Setelah tinggal di Jepang selesai", "Dalam hal / Untuk keperluan tinggal di Jepang...", "Meskipun tinggal di Jepang", "Seiring tinggal di Jepang"], "answer": 1, "why": "Bila didahului Bentuk Kamus (住む), 上で berarti ''dalam hal / ketika melakukan hal tersebut''."}, {"question": "Mana yang memakai partikel penyambung yang benar untuk kata benda けんとう (pertimbangan)?", "options": ["けんとう の 上で", "けんとう な 上で", "けんとう で 上で", "けんとう を 上で"], "answer": 0, "why": "Kata Benda memakai partikel の sebelum 上で."}]}'::jsonb WHERE code = 'GP-JA-N2-007';
UPDATE grammar_points SET learning_guide = '{"analogy": "～つつある adalah versi formal dari ''sedang terus berlangsung / perlahan berubah menuju...''. Mirip versi berita atau jurnal dari ～てきている / ～ている.", "when_to_use": ["Membaca atau menulis laporan berita (''ekonomi sedang berangsur membaik'', ''jumlah warga desa mulai menyusut'')", "Menggambarkan tren perubahan yang sedang berproses saat ini", "Menjelaskan kemajuan bertahap sebuah proyek (''pembangunan jembatan sedang terus berjalan'')"], "formula_parts": [{"text": "Stem Verba (Akar ます)", "label": "Perubahan bertahap", "role": "verb"}, {"text": "つつある", "label": "Sedang perlahan berlangsung", "role": "ending"}], "steps": ["Ambil kata kerja bermakna proses perubahan (seperti かわり-ます = berubah, へり-ます = berkurang, ふえ-ます = bertambah, かいふくし-ます = pulih).", "Buang akhiran ます (dapat akarnya: かわり, へり, かいふくし).", "Tempelkan つつある (atau bentuk sopan つつあります) tepat di belakangnya."], "breakdowns": [{"tokens": [{"jp": "けいざい", "reading": "keizai", "meaning": "ekonomi", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "かいふくし", "reading": "kaifuku shi", "meaning": "pulih (stem)", "role": "verb"}, {"jp": "つつあります", "reading": "tsutsu arimasu", "meaning": "sedang berangsur", "role": "ending"}], "translation": "Perekonomian sedang berangsur pulih."}, {"tokens": [{"jp": "まち", "reading": "machi", "meaning": "kota", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(milik)", "role": "particle"}, {"jp": "けしき", "reading": "keshiki", "meaning": "pemandangan", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "すこしずつ", "reading": "sukoshi zutsu", "meaning": "sedikit demi sedikit", "role": "adjective"}, {"jp": "かわり", "reading": "kawari", "meaning": "berubah (stem)", "role": "verb"}, {"jp": "つつある", "reading": "tsutsu aru", "meaning": "sedang terus berlangsung", "role": "ending"}], "translation": "Pemandangan kota perlahan sedang berubah sedikit demi sedikit."}, {"tokens": [{"jp": "かつて", "reading": "katsute", "meaning": "dahulu", "role": "time"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "ふるい", "reading": "furui", "meaning": "kuno", "role": "adjective"}, {"jp": "でんとう", "reading": "dentou", "meaning": "tradisi", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "うしなわれ", "reading": "ushinaware", "meaning": "hilang (pasif stem)", "role": "verb"}, {"jp": "つつある", "reading": "tsutsu aru", "meaning": "kian terkikis / menghilang", "role": "ending"}], "translation": "Tradisi lama dari masa lalu kini perlahan mulai menghilang."}], "forms": [{"label": "Pernyataan Tren", "jp": "ふえつつある", "reading": "fue tsutsu aru", "id": "sedang meningkat perlahan"}, {"label": "Bahasa Laporan Sopan", "jp": "ふえつつあります", "reading": "fue tsutsu arimasu", "id": "sedang terus bertambah"}, {"label": "Menerangkan Benda", "jp": "かわりつつある社会", "reading": "kawari tsutsu aru shakai", "id": "masyarakat yang terus berubah"}], "mistakes": [{"wrong": "いま テレビを みつつあります", "right": "いま テレビを みています", "why": "つつある hanya cocok untuk perubahan tren bertahap jangka agak panjang & bernada formal, bukan kegiatan harian singkat seperti nonton TV atau makan."}, {"wrong": "ふえる つつある", "right": "ふえ つつある", "why": "Yang dipakai sebelum つつある wajib Stem Verba (bentuk ます tanpa ます), bukan bentuk kamus."}], "quiz": [{"question": "Pilih bentuk akar verba yang benar untuk ''Populasi beruang mulai berkurang (へります = berkurang)'':", "options": ["へる つつある", "へり つつある", "へった つつある", "へって つつある"], "answer": 1, "why": "へります dibuang ます menjadi stem へり, lalu disambung dengan つつある."}, {"question": "Mengapa kalimat ''あした つつある'' atau ''ごはんを たべつつあります'' terdengar aneh?", "options": ["Karena makanan tidak boleh dijelaskan dengan formal", "Karena ～つつある khusus menyatakan proses perubahan/tren berangsur, bukan aktivitas seketika sehari-hari", "Karena kata kerja grup 2 tidak punya stem", "Karena つつある hanya untuk bentuk lampau"], "answer": 1, "why": "Makan nasi bukan tren progresif yang sedang berubah perlahan; gunakan たべています."}, {"question": "Jika diletakkan sebelum kata benda ''環境（かんきょう = lingkungan）が ___ もんだい'', bentuk yang tepat adalah:", "options": ["悪化し つつある", "悪化する つつある", "悪化した つつある", "悪化し つつあって"], "answer": 0, "why": "Stem (悪化し) + つつある langsung bisa memodifikasi kata benda (もんだい)."}]}'::jsonb WHERE code = 'GP-JA-N2-008';
UPDATE grammar_points SET learning_guide = '{"analogy": "～かねない artinya ''Jangan-jangan bisa berakibat...'' atau ''Bisa saja ujung-ujungnya malah memicu hal buruk!''. Selalu bernada KEKHAWATIRAN bahwa kelalaian sekarang berisiko menimbulkan akibat negatif.", "when_to_use": ["Mengingatkan bahaya atau risiko kerja (''kalau dibiarkan begini terus, perusahaan bisa bangkrut!'')", "Memperingatkan dampak kesehatan/kecelakaan (''jangan ngebut, nanti bisa menimbulkan kecelakaan!'')", "Komentar kritis di berita soal risiko kebijakan atau kebiasaan"], "formula_parts": [{"text": "Stem Verba (Akar ます)", "label": "Peristiwa buruk yg ditakutkan", "role": "verb"}, {"text": "かねない", "label": "Berisiko memicu / Bisa saja", "role": "ending"}], "steps": ["Pastikan akibatnya adalah hal NEGATIF atau mengkhawatirkan (jangan pakai untuk hal bagus seperti menang hadiah!).", "Ambil stem verba (misal: おこします → おこし, まちがえます → まちがえ, こわします → こわし).", "Tambahkan かねない (hati-hati: walau diakhiri ない, artinya BUKAN negatif, melainkan POSITIF ''bisa saja terjadi''!)."], "breakdowns": [{"tokens": [{"jp": "そんな", "reading": "sonna", "meaning": "seperti itu", "role": "noun"}, {"jp": "スピード", "reading": "supiido", "meaning": "kecepatan", "role": "noun"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "だすと", "reading": "dasu to", "meaning": "kalau memacu", "role": "verb"}, {"jp": "じこ", "reading": "jiko", "meaning": "kecelakaan", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "おこし", "reading": "okoshi", "meaning": "menimbulkan (stem)", "role": "verb"}, {"jp": "かねない", "reading": "kanenai", "meaning": "bisa-bisa memicu", "role": "ending"}], "translation": "Kalau mengebut segitu cepat, bisa-bisa memicu kecelakaan!"}, {"tokens": [{"jp": "むり", "reading": "muri", "meaning": "memaksakan diri", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "つづけると", "reading": "tsuzukeru to", "meaning": "kalau terus", "role": "verb"}, {"jp": "からだ", "reading": "karada", "meaning": "tubuh/kesehatan", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "こわし", "reading": "kowashi", "meaning": "merusak (stem)", "role": "verb"}, {"jp": "かねません", "reading": "kanemasen", "meaning": "berisiko (sopan)", "role": "ending"}], "translation": "Kalau terus memforsir diri, bisa-bisa merusak kesehatanmu!"}, {"tokens": [{"jp": "誤解", "reading": "gokai", "meaning": "kesalahpahaman", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "まねき", "reading": "maneki", "meaning": "mengundang (stem)", "role": "verb"}, {"jp": "かねない", "reading": "kanenai", "meaning": "berisiko mengundang", "role": "ending"}, {"jp": "いいかた", "reading": "iikata", "meaning": "cara bicara", "role": "noun"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "さけたほうがいい", "reading": "saketa hou ga ii", "meaning": "sebaiknya dihindari", "role": "verb"}], "translation": "Cara bicara yang berisiko mengundang kesalahpahaman sebaiknya dihindari."}], "forms": [{"label": "Kasual Peringatan", "jp": "おくれかねない", "reading": "okure kanenai", "id": "bisa-bisa nanti terlambat"}, {"label": "Sopan", "jp": "じこをおこしかねません", "reading": "jiko o okoshi kanemasen", "id": "berisiko memicu kecelakaan (sopan)"}, {"label": "Beda Arti: ～かねる", "jp": "おこたえしかねます", "reading": "okotae shikanemasu", "id": "mohon maaf sulit/tidak bisa menjawab"}], "mistakes": [{"wrong": "まいにち べんきょうすれば、１００てんを とりかねない！", "right": "１００てんを とれる かもしれない", "why": "～かねない hanya untuk kekhawatiran akibat BURUK; untuk hasil baik gunakan かもしれない atau そうだ."}, {"wrong": "おこす かねない", "right": "おこし かねない", "why": "Selalu wajib memakai Stem Verba (tanpa ます), bukan bentuk kamus."}], "quiz": [{"question": "Apa arti kalimat peringatan ''そんな いそぎかたでは、ミスを し かねませんよ''?", "options": ["Kalau terburu-buru seperti itu, tidak akan pernah salah", "Kalau terburu-buru begitu, bisa-bisa nanti malah membuat kesalahan lho", "Kita harus melakukan kesalahan", "Sudah pasti gagal total"], "answer": 1, "why": "Meski ada akhiran ない/ません, かねない/かねません artinya kekhawatiran hal buruk ''bisa saja terjadi''."}, {"question": "Hati-hati pasangan jebakan di JLPT! Bedakan ～かねる vs ～かねない pada kalimat ''その しつもんには おこたえ し___'':", "options": ["かねない (bisa saja menjawab - bahaya)", "かねます (mohon maaf tidak sanggup/tidak bisa menjawab)", "かねた (lupa menjawab)", "かねるな (jangan jawab)"], "answer": 1, "why": "～かねる bermakna halus ''keberatan / tidak mampu melakukan'', sedangkan ～かねない bermakna ''berisiko berakibat buruk''."}, {"question": "Kalimat mana yang benar secara tata bahasa dan rasa?", "options": ["テストに ごうかく し かねない", "かのじょを きずつけて しまい かねない", "きょねん １０万円 ひろい かねなかった", "おいしい ので、また かい かねない"], "answer": 1, "why": "Khawatir ucapan dapat melukai hati seseorang (きずつけて しまい) adalah hal negatif yang sangat pas dengan かねない."}]}'::jsonb WHERE code = 'GP-JA-N2-009';
UPDATE grammar_points SET learning_guide = '{"analogy": "Sonkeigo adalah bahasa meninggikan lawan bicara — ibarat berkata ''Beliau berkenan melakukan...''. Kalau di N4 kita pakai Kenjougo untuk MERENDAHKAN diri sendiri, Sonkeigo khusus untuk MENGHORMATI tindakan atasan, klien, atau tamu!", "when_to_use": ["Menanyakan kabar atau rencana atasan/klien (''apakah Bapak sudah makan?'', ''jam berapa Ibu tiba?'')", "Memberi petunjuk atau mempersilakan tamu secara sangat sopan (''silakan tunggu sebentar'', ''silakan melihat-lihat'')", "Melaporkan tindakan atasan ke rekan atau tamu luar"], "formula_parts": [{"text": "お / ご", "label": "Awalan hormat", "role": "particle"}, {"text": "Stem Verba", "label": "Tindakan lawan bicara", "role": "verb"}, {"text": "になる / Verba Khusus", "label": "Bentuk meninggikan (Sonkeigo)", "role": "ending"}], "steps": ["Pastikan pelakunya adalah ATASAN, KLIEN, atau TAMU — jangan pernah memakai pola ini untuk tindakan diri sendiri!", "Rumus baku: お + [Stem Verba] + になる (contoh: かきます → おかきになる, みます → *tidak cocok! Pakai kata khusus*).", "WAJIB hafal 6 kata kerja khusus Sonkeigo karena tidak memakai rumus お～になる: pergi/datang/ada → いらっしゃる, makan/minum → めしあがる, melihat → ごらんになる, berkata → おっしゃる, melakukan → なさる, tahu → ごぞんじだ."], "breakdowns": [{"tokens": [{"jp": "しゃちょう", "reading": "shachou", "meaning": "Direktur", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "もう", "reading": "mou", "meaning": "sudah", "role": "time"}, {"jp": "おかえりに", "reading": "okaeri ni", "meaning": "pulang", "role": "verb"}, {"jp": "なりましたか", "reading": "narimashita ka", "meaning": "apakah (hormat)?", "role": "ending"}], "translation": "Apakah Bapak Direktur sudah pulang?"}, {"tokens": [{"jp": "こちら", "reading": "kochira", "meaning": "sebelah sini", "role": "place"}, {"jp": "で", "reading": "de", "meaning": "di", "role": "particle"}, {"jp": "どうぞ", "reading": "douzo", "meaning": "silakan", "role": "connector"}, {"jp": "おかけに", "reading": "okake ni", "meaning": "duduk", "role": "verb"}, {"jp": "なって", "reading": "natte", "meaning": "silakan (TE hormat)", "role": "ending"}, {"jp": "ください", "reading": "kudasai", "meaning": "tolong", "role": "ending"}], "translation": "Silakan berkenan duduk di sebelah sini."}, {"tokens": [{"jp": "せんせい", "reading": "sensei", "meaning": "Guru/Profesor", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "ほん", "reading": "hon", "meaning": "buku", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "ごらんに", "reading": "goran ni", "meaning": "membaca/melihat (khusus)", "role": "verb"}, {"jp": "なりました", "reading": "narimashita", "meaning": "(sangat hormat)", "role": "ending"}], "translation": "Profesor sudah berkenan membaca/melihat buku ini."}], "forms": [{"label": "Rumus Baku (お～になる)", "jp": "およみになります", "reading": "oyomi ni narimasu", "id": "beliau membaca"}, {"label": "Khusus: Pergi/Ada", "jp": "いらっしゃいます", "reading": "irasshaimasu", "id": "beliau ada / pergi / datang"}, {"label": "Khusus: Makan/Minum", "jp": "めしあがります", "reading": "meshiagarimasu", "id": "beliau makan / minum"}, {"label": "Khusus: Berkata", "jp": "おっしゃいます", "reading": "osshaimasu", "id": "beliau mengatakan"}], "mistakes": [{"wrong": "わたしは あした おかえりになります", "right": "わたしは あした かえります (atau まいります)", "why": "Sonkeigo adalah penghormatan peninggi! Memakainya untuk DIRI SENDIRI adalah kesalahan fatal etiket Jepang."}, {"wrong": "おみに なりました (untuk melihat)", "right": "ごらんに なりました", "why": "Kata kerja みます dan beberapa kata 1 suku kata lain tidak memakai お～になる, melainkan punya bentuk khusus ごらんになる."}], "quiz": [{"question": "Klien bertanya kapan Bos datang ke kantor. Kalimat hormat untuk ''Apakah Direktur sudah datang?'' adalah:", "options": ["しゃちょうは もう まいりましたか", "しゃちょうは もう いらっしゃいましたか", "しゃちょうは もう おきますか", "しゃちょうは もう おりましたか"], "answer": 1, "why": "まいります (Kenjougo untuk saya/tim sendiri); いらっしゃいましたか (Sonkeigo menghormati tindakan direktur)."}, {"question": "Bagaimana menanyakan secara sangat sopan apakah guru sudah makan kue tersebut (たべます -> Sonkeigo)?", "options": ["おたべに なりましたか", "めしあがりましたか", "いただきましたか", "おめしあがり しましたか"], "answer": 1, "why": "Sonkeigo baku untuk makan/minum adalah kata kerja khusus めしあがります."}, {"question": "Mengapa bentuk ''先生、おやすみに なってください'' kadang dihindari dan diganti ''ごゆっくり おやすみ ください''?", "options": ["Karena お～になる untuk aksi lawan bicara, dan bila mempersilakan langsung jauh lebih luwes pakai お[stem]ください!", "Karena kata やすむ tidak punya stem", "Karena ください lebih rendah", "Karena 先生 tidak boleh istirahat"], "answer": 0, "why": "Untuk mempersilakan tamu/atasan melakukan sesuatu secara langsung, rumus manisnya adalah お + [Stem] + ください."}]}'::jsonb WHERE code = 'GP-JA-N2-010';
UPDATE grammar_points SET learning_guide = '{"analogy": "～ようにする artinya ''berusaha membiasakan diri untuk...'' atau ''usahakan supaya jangan...''. Beda dari sekadar janji sekali jadi, pola ini menekankan ikhtiar sadar yang diulang pelan-pelan tiap hari.", "when_to_use": ["Menetapkan resolusi hidup sehat atau belajar rutin (''usahakan tidur cukup tiap hari'')", "Berusaha meninggalkan kebiasaan buruk (''berusaha untuk tidak telat'')", "Memberi imbauan atau aturan ke orang lain agar menjaga suatu kebiasaan"], "formula_parts": [{"text": "Kamus Verba / Bentuk-NAI", "label": "Kebiasaan yang dituju", "role": "verb"}, {"text": "ようにする", "label": "Berusaha membiasakan", "role": "ending"}], "steps": ["Ambil kata kerja bentuk dasar kamus (misal: のむ, ねる) atau Bentuk-NAI kalau tujuannya menghindari (おくれない, たべすぎない).", "Tambahkan ようにします di belakangnya untuk menyatakan niat membiasakan.", "Kalau mau bilang sudah mulai membiasakan sejak lama, ubah akhirnya ke ようにしています (''saya terbiasa berusaha...'')."], "breakdowns": [{"tokens": [{"jp": "まいにち", "reading": "mainichi", "meaning": "setiap hari", "role": "time"}, {"jp": "やさい", "reading": "yasai", "meaning": "sayur-sayuran", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "たべる", "reading": "taberu", "meaning": "makan (kamus)", "role": "verb"}, {"jp": "ようにしています", "reading": "you ni shite imasu", "meaning": "berusaha membiasakan", "role": "ending"}], "translation": "Saya membiasakan diri makan sayur setiap hari."}, {"tokens": [{"jp": "かいぎ", "reading": "kaigi", "meaning": "rapat", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "pada", "role": "particle"}, {"jp": "おくれない", "reading": "okurenai", "meaning": "tidak terlambat (NAI)", "role": "verb"}, {"jp": "ようにします", "reading": "you ni shimasu", "meaning": "berusaha agar tidak", "role": "ending"}], "translation": "Saya berusaha supaya tidak terlambat rapat."}, {"tokens": [{"jp": "ねる", "reading": "neru", "meaning": "tidur", "role": "verb"}, {"jp": "まえに", "reading": "mae ni", "meaning": "sebelum", "role": "time"}, {"jp": "スマホ", "reading": "sumaho", "meaning": "ponsel", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "みない", "reading": "minai", "meaning": "tidak melihat (NAI)", "role": "verb"}, {"jp": "ようにしてください", "reading": "you ni shite kudasai", "meaning": "usahakan untuk", "role": "ending"}], "translation": "Usahakan jangan main ponsel sebelum tidur ya."}], "forms": [{"label": "Membiasakan (+)", "jp": "うんどうするようにしています", "reading": "undou suru you ni shite imasu", "id": "berusaha rutin olahraga"}, {"label": "Menghindari (-)", "jp": "わすれないようにします", "reading": "wasurenai you ni shimasu", "id": "berusaha tidak lupa"}, {"label": "Imbauan", "jp": "きをつけるようにしてください", "reading": "ki o tsukeru you ni shite kudasai", "id": "usahakan selalu berhati-hati"}], "mistakes": [{"wrong": "まいにち うんどう ようにします", "right": "まいにち うんどう する ようにします", "why": "Kata kerja bentuk kamus (suru) atau Bentuk-NAI wajib ada sebelum ようにする, bukan kata benda telanjang."}, {"wrong": "あした ５じに おきられる ようにします", "right": "あした ５じに おきる ようにします", "why": "～ようにする dipakai bersama aksi yang bisa dikendalikan oleh niat/usaha sendiri (okiru = bangun), bukan hasil di luar kendali."}], "quiz": [{"question": "Bagaimana mengatakan ''Saya berusaha rutin minum air putih setiap pagi''?", "options": ["まいあさ おみずを のんだ ようにしています", "まいあさ おみずを のむ ようにしています", "まいあさ おみずを のみ ようにしています", "まいあさ おみずを のんで ようにしています"], "answer": 1, "why": "Sebelum ようにする / ようにしている memakai bentuk kamus (のむ)."}, {"question": "Bedanya ～ようにしています dibanding ～ようにします dalam aktivitas sehari-hari adalah:", "options": ["～ようにしています menyatakan kebiasaan usaha yang terus dijalankan rutin sekarang", "～ようにしています artinya sudah berhenti berusaha", "～ようにしています hanya untuk orang ketiga", "Keduanya terlarang dipakai di masa sekarang"], "answer": 0, "why": "ようにしています menggambarkan kebiasaan yang memang sedang rutin diupayakan dalam hidup sehari-hari."}, {"question": "Cara berkata ''Saya usahakan tidak begadang (ねおそくならない / よふかししない)'' adalah:", "options": ["よふかし しない ようにします", "よふかし する ようにしません", "よふかし なかった ようにします", "よふかし しなかった ようにします"], "answer": 0, "why": "Bentuk-NAI diletakkan sebelum ようにします: しない ようにします."}]}'::jsonb WHERE code = 'GP-JA-N3-001';
UPDATE grammar_points SET learning_guide = '{"analogy": "～ことになる artinya ''sudah diputuskan bahwa...'' atau ''jadinya diputuskan begini...'' oleh kantor, sekolah, atau aturan bersama — jadi kesannya keputusan itu bukan semata-mata maumu sendiri.", "when_to_use": ["Mengumumkan penugasan kerja, mutasi cabang, atau jadwal perjalanan dinas", "Menyampaikan keputusan rapat atau aturan baru perusahaan/kampus", "Bercerita sopan mengenai perubahan rencana hidup (seperti jadi menikah atau pindah ke Jepang)"], "formula_parts": [{"text": "Kamus Verba / Bentuk-NAI", "label": "Isi keputusan", "role": "verb"}, {"text": "ことになる / ことになった", "label": "Sudah diputuskan", "role": "ending"}], "steps": ["Tentukan aksi yang diputuskan dalam bentuk kamus (atau Bentuk-NAI jika diputuskan untuk TIDAK dilakukan).", "Tambahkan ことになりました / ことになっています bila sudah menjadi aturan tetap atau jadwal resmi.", "Bandingkan: kalau dirimu sendiri yang memutuskan secara pribadi, pakailah ～ことにする; kalau dari rapat/pihak luar, pakai ～ことになる."], "breakdowns": [{"tokens": [{"jp": "らいげつ", "reading": "raigetsu", "meaning": "bulan depan", "role": "time"}, {"jp": "東京", "reading": "Toukyou", "meaning": "Tokyo", "role": "place"}, {"jp": "へ", "reading": "e", "meaning": "ke", "role": "particle"}, {"jp": "しゅっちょうする", "reading": "shucchou suru", "meaning": "dinas luar (kamus)", "role": "verb"}, {"jp": "ことになりました", "reading": "koto ni narimashita", "meaning": "sudah diputuskan", "role": "ending"}], "translation": "Diputuskan bahwa bulan depan saya dinas ke Tokyo."}, {"tokens": [{"jp": "かいぎ", "reading": "kaigi", "meaning": "rapat", "role": "subject"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "ちゅうしに", "reading": "chuushi ni", "meaning": "batal / dibatalkan", "role": "noun"}, {"jp": "なる", "reading": "naru", "meaning": "menjadi", "role": "verb"}, {"jp": "ことになりました", "reading": "koto ni narimashita", "meaning": "akhirnya diputuskan", "role": "ending"}], "translation": "Rapatnya diputuskan untuk dibatalkan."}, {"tokens": [{"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "ビル", "reading": "biru", "meaning": "gedung", "role": "place"}, {"jp": "の", "reading": "no", "meaning": "(di)", "role": "particle"}, {"jp": "なか", "reading": "naka", "meaning": "dalam", "role": "place"}, {"jp": "では", "reading": "de wa", "meaning": "di area", "role": "particle"}, {"jp": "たばこ", "reading": "tabako", "meaning": "rokok", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "すわない", "reading": "suwanai", "meaning": "tidak merokok", "role": "verb"}, {"jp": "ことになっています", "reading": "koto ni natte imasu", "meaning": "sudah menjadi aturan", "role": "ending"}], "translation": "Aturannya di dalam gedung ini dilarang merokok."}], "forms": [{"label": "Keputusan Baru", "jp": "いくことになりました", "reading": "iku koto ni narimashita", "id": "diputuskan akan pergi"}, {"label": "Batal / Tidak Jadi", "jp": "いかないことになりました", "reading": "ikanai koto ni narimashita", "id": "diputuskan tidak jadi pergi"}, {"label": "Aturan Resmi Tetap", "jp": "あさ９じにはじまることになっています", "reading": "asa kuji ni hajimaru koto ni natte imasu", "id": "aturannya mulai jam 9 pagi"}], "mistakes": [{"wrong": "まいにち １じかん はしる ことになりました (tekad pribadi)", "right": "まいにち １じかん はしる ことにしました", "why": "Kalau itu keputusan/tekad dirimu sendiri, gunakan ことにしました. ことになりました menunjukkan pihak lain/aturan yang memutuskan."}, {"wrong": "しゅっちょう した ことになりました", "right": "しゅっちょう する ことになりました", "why": "Sebelum ことになる umumnya pakai bentuk non-lampau (bentuk kamus / Bentuk-NAI), walau keputusannya di masa lalu (narimashita)."}], "quiz": [{"question": "Kantor menugaskanmu pindah ke cabang Osaka bulan depan. Kalimat yang paling pas disampaikan ke teman adalah:", "options": ["おおさかで はたらく ことになりました", "おおさかで はたらく ようにしました", "おおさかで はたらいた ことにしました", "おおさかで はたらく つもりになりました"], "answer": 0, "why": "Keputusan dari atasan atau perusahaan disampaikan dengan ～ことになりました."}, {"question": "Apa makna pola ～ことになっています pada pengumuman sekolah atau jadwal kantor?", "options": ["Baru rencana pribadi", "Sudah ditetapkan sebagai aturan atau jadwal resmi berlaku", "Kemungkinan batal", "Harapan di masa depan"], "answer": 1, "why": "～ことになっています menekankan status aturan/sistem yang saat ini berlaku resmi."}, {"question": "Bandingkan ことにしました vs ことになりました. Mana yang keputusan pribadi?", "options": ["ことになりました", "ことにしました", "Keduanya mutlak aturan luar", "Keduanya keputusan pribadi"], "answer": 1, "why": "ことにする = memutuskan sendiri; ことになる = diputuskan oleh situasi/organisasi."}]}'::jsonb WHERE code = 'GP-JA-N3-002';
UPDATE grammar_points SET learning_guide = '{"analogy": "～おかげで persis kata ''Berkat...'' dalam bahasa Indonesia! Wajib dipakai HANYA kalau hasilnya POSITIF dan kamu mau berterima kasih atas penyebabnya.", "when_to_use": ["Berterima kasih karena bantuan teman, guru, atau mentor (''berkat bantuanmu saya lulus'')", "Bersyukur atas cuaca cerah atau alat yang memudahkan pekerjaan", "Melaporkan kesuksesan hasil positif ke atasan secara sopan"], "formula_parts": [{"text": "Nomina の / Bentuk Biasa (+ な u/ Sifat-Na)", "label": "Penyebab baik", "role": "noun"}, {"text": "おかげで", "label": "Berkat", "role": "connector"}, {"text": "Hasil Positif", "label": "Kesuksesan / lega", "role": "predicate"}], "steps": ["Cek apakah hasilnya baik/positif! Jika hasilnya rugi atau buruk, pakai せいで (''gara-gara''), bukan おかげで.", "Kalau penyebabnya Kata Benda, tambahkan の (contoh: せんせい の おかげで).", "Kalau penyebabnya Kata Sifat-Na, tambahkan な (contoh: べんりな おかげで); kalau verba/sifat-i langsung Bentuk Biasa."], "breakdowns": [{"tokens": [{"jp": "せんせい", "reading": "sensei", "meaning": "guru", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(penghubung)", "role": "particle"}, {"jp": "おかげで", "reading": "okage de", "meaning": "berkat", "role": "connector"}, {"jp": "ごうかくしました", "reading": "goukaku shimashita", "meaning": "lulus ujian", "role": "verb"}], "translation": "Berkat guru, saya lulus ujian."}, {"tokens": [{"jp": "はやめに", "reading": "hayame ni", "meaning": "lebih awal", "role": "time"}, {"jp": "しゅっぱつした", "reading": "shuppatsu shita", "meaning": "berangkat (lampau)", "role": "verb"}, {"jp": "おかげで", "reading": "okage de", "meaning": "berkat", "role": "connector"}, {"jp": "ひこうき", "reading": "hikouki", "meaning": "pesawat", "role": "noun"}, {"jp": "に", "reading": "ni", "meaning": "pada", "role": "particle"}, {"jp": "まにあいました", "reading": "maniaimashita", "meaning": "sempat terkejar", "role": "verb"}], "translation": "Berkat berangkat lebih awal, saya sempat naik pesawat."}, {"tokens": [{"jp": "インターネット", "reading": "intaanetto", "meaning": "internet", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(penghubung)", "role": "particle"}, {"jp": "おかげで", "reading": "okage de", "meaning": "berkat", "role": "connector"}, {"jp": "どこにいても", "reading": "doko ni ite mo", "meaning": "di mana pun", "role": "place"}, {"jp": "日本語", "reading": "nihongo", "meaning": "bahasa Jepang", "role": "object"}, {"jp": "が", "reading": "ga", "meaning": "(objek)", "role": "particle"}, {"jp": "べんきょうできます", "reading": "benkyou dekimasu", "meaning": "bisa belajar", "role": "verb"}], "translation": "Berkat internet, di mana pun berada kita bisa belajar bahasa Jepang."}], "forms": [{"label": "Kata Benda (+の)", "jp": "みなさんのおかげです", "reading": "minasan no okage desu", "id": "ini semua berkat kalian"}, {"label": "Verba Lampau", "jp": "くすりをのんだおかげで", "reading": "kusuri o nonda okage de", "id": "berkat sudah minum obat"}, {"label": "Sifat-Na (+な)", "jp": "げんきなおかげで", "reading": "genki na okage de", "id": "berkat kondisi yang sehat"}], "mistakes": [{"wrong": "たいふうの おかげで、しあいが ちゅうしに なりました", "right": "たいふうの せいで、しあいが ちゅうしに なりました", "why": "Pertandingan batal akibat topan adalah kejadian buruk, jadi jangan pakai おかげで (kecuali bermaksud sarkas/mengejek!)."}, {"wrong": "ともだち おかげで、たすかりました", "right": "ともだち の おかげで、たすかりました", "why": "Setelah kata benda (ともだち) wajib disisipkan partikel の sebelum おかげで."}], "quiz": [{"question": "Lengkapi: ''みんな ___、たのしい りょこうに なりました'' (Berkat semuanya, jadi wisata yang menyenangkan):", "options": ["の おかげで", "な おかげで", "の せいで", "から おかげで"], "answer": 0, "why": "みんな adalah kata benda/pronomina sehingga memakai の, dan hasilnya positif memakai おかげで."}, {"question": "Kalimat mana yang pemakaian おかげで-nya PALING TEPAT?", "options": ["かぜの おかげで ねつが でました", "しごとの おかげで とても つかれました", "ちちの おかげで だいじょうぶ でした", "ねぼうの おかげで ちこく しました"], "answer": 2, "why": "Hanya pilihan ke-3 yang menunjukkan situasi selamat/baik berkat ayah."}, {"question": "Bagaimana menyambungkan Kata Sifat-Na seperti べんり (praktis) dengan おかげで?", "options": ["べんりの おかげで", "べんりだ おかげで", "べんりな おかげで", "べんりで おかげで"], "answer": 2, "why": "Sifat-Na memakai な di depan おかげで (べんりな おかげで)."}]}'::jsonb WHERE code = 'GP-JA-N3-003';
UPDATE grammar_points SET learning_guide = '{"analogy": "～せいで adalah kebalikan persis dari おかげで — artinya ''Gara-gara...'' atau ''Akibat...''. Selalu dipakai ketika hasilnya BURUK, merugikan, atau menyebalkan.", "when_to_use": ["Menjelaskan kenapa sesuatu gagal, rusak, terlambat, atau sakit (''gara-gara begadang, ketiduran'')", "Mengeluh soal cuaca buruk atau macet yang bikin rencana berantakan", "Membela diri menjelaskan kesalahan (catatan: hati-hati jangan terlalu menyalahkan orang lain langsung di kantor!)"], "formula_parts": [{"text": "Nomina の / Bentuk Biasa (+ な u/ Sifat-Na)", "label": "Penyebab buruk", "role": "noun"}, {"text": "せいで", "label": "Gara-gara / Akibat", "role": "connector"}, {"text": "Akibat Buruk", "label": "Kerugian / Kesalahan", "role": "predicate"}], "steps": ["Pastikan akibat di belakang kalimat bernada negatif atau tidak diharapkan.", "Sambungkan penyusun kalimatnya sama persis seperti aturan おかげで: Kata Benda + の, Sifat-Na + な, Verba/Sifat-I Bentuk Biasa.", "Akhiri kalimat dengan hasil buruk yang terjadi (atau tutup di akhir dengan ～のせいです = ''ini gara-gara...'')."], "breakdowns": [{"tokens": [{"jp": "じゅうたい", "reading": "juutai", "meaning": "macet", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(penghubung)", "role": "particle"}, {"jp": "せいで", "reading": "sei de", "meaning": "gara-gara", "role": "connector"}, {"jp": "おくれました", "reading": "okuremashita", "meaning": "terlambat", "role": "verb"}], "translation": "Gara-gara macet, saya terlambat."}, {"tokens": [{"jp": "エアコン", "reading": "eakon", "meaning": "AC", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "つけっぱなしにした", "reading": "tsukeppanashi ni shita", "meaning": "membiarkan menyala", "role": "verb"}, {"jp": "せいで", "reading": "sei de", "meaning": "gara-gara", "role": "connector"}, {"jp": "かぜ", "reading": "kaze", "meaning": "masuk angin", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "ひきました", "reading": "hikimashita", "meaning": "terkena", "role": "verb"}], "translation": "Gara-gara membiarkan AC menyala semalaman, saya masuk angin."}, {"tokens": [{"jp": "きょねん", "reading": "kyonen", "meaning": "tahun lalu", "role": "time"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "あめ", "reading": "ame", "meaning": "hujan", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "ふらなかった", "reading": "furanakatta", "meaning": "tidak turun", "role": "verb"}, {"jp": "せいで", "reading": "sei de", "meaning": "akibat", "role": "connector"}, {"jp": "やさい", "reading": "yasai", "meaning": "sayuran", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "たかくなりました", "reading": "takaku narimashita", "meaning": "menjadi mahal", "role": "adjective"}], "translation": "Akibat tahun lalu tidak turun hujan, harga sayur jadi mahal."}], "forms": [{"label": "Kata Benda (+の)", "jp": "あめのせいで", "reading": "ame no sei de", "id": "gara-gara hujan"}, {"label": "Verba Lampau", "jp": "ねぼうしたせいで", "reading": "nebou shita sei de", "id": "gara-gara ketiduran"}, {"label": "Akhir Kalimat", "jp": "わたしのせいです", "reading": "watashi no sei desu", "id": "ini salah saya"}], "mistakes": [{"wrong": "がんばった せいで、JLPTに うかりました", "right": "がんばった おかげで、JLPTに うかりました", "why": "Lulus ujian itu hal menggembirakan! Selalu gunakan おかげで untuk hasil positif."}, {"wrong": "たいへん だ せいで", "right": "たいへん な せいで", "why": "Sifat-Na di depan せいで tidak pakai だ, melainkan berubah ke な."}], "quiz": [{"question": "Lengkapi: ''きのうの よる コーヒーを ___ せいで、ねむれませんでした'' (Gara-gara minum kopi tadi malam, tidak bisa tidur):", "options": ["のむ", "のんだ", "のみ", "のんで"], "answer": 1, "why": "Kejadian minum kopinya sudah terjadi (lampau), sehingga memakai Bentuk-TA (のんだ)."}, {"question": "Apa arti kalimat ''ぜんぶ わたしの せいです。すみません''?", "options": ["Semua ini berkat usaha saya", "Semua ini kesalahan/gara-gara saya, maaf", "Saya tidak tahu salah siapa", "Mari kita selesaikan bersama"], "answer": 1, "why": "[Orang] の せいです dipakai untuk mengakui tanggung jawab kesalahan."}, {"question": "Pilih kalimat yang cocok memakai ～せいで:", "options": ["あつい せいで アイスクリームが おいしい", "きゅうに さむくなった せいで のどが いたい", "おかあさんの せいで げんきに なりました", "バスが はやい せいで たすかりました"], "answer": 1, "why": "Sakit tenggorokan akibat mendadak dingin adalah akibat negatif, sangat pas dengan せいで."}]}'::jsonb WHERE code = 'GP-JA-N3-004';
UPDATE grammar_points SET learning_guide = '{"analogy": "～に対して artinya bisa ''terhadap / kepada (sikap kita ke orang/topik)'' ATAU ''sedangkan / berbanding terbalik dengan... (membandingkan dua kubu yang kontras)''.", "when_to_use": ["Menjelaskan sikap seseorang kepada pelanggan, bawahan, atau hewan (''ramah terhadap tamu'')", "Menyatakan respons/tindakan atas suatu pertanyaan atau kritik (''menjawab pertanyaan tersebut'')", "Membandingkan dua hal yang bertolak belakang (''kakak pendiam, sebaliknya adiknya ceria'')"], "formula_parts": [{"text": "Nomina (Sasaran / Hal 1)", "label": "Pihak yang dituju / dibanding", "role": "noun"}, {"text": "に対して / に対する", "label": "Terhadap / Sebaliknya", "role": "particle"}, {"text": "Sikap / Klausa Kontras", "label": "Tindakan atau pembanding", "role": "predicate"}], "steps": ["Taruh pihak sasaran atau topik yang dituju di depan pola (seperti おきゃくさん, しつもん).", "Tambahkan に対して jika setelahnya berupa kalimat lengkap / sifat / kata kerja.", "Kalau mau menerangkan kata benda di belakangnya (seperti ''sikap terhadap pelanggan''), ubah ekornya menjadi に対する + Kata Benda!"], "breakdowns": [{"tokens": [{"jp": "おきゃくさん", "reading": "okyakusan", "meaning": "pelanggan", "role": "noun"}, {"jp": "に対して", "reading": "ni taishite", "meaning": "terhadap", "role": "particle"}, {"jp": "ていねいに", "reading": "teinei ni", "meaning": "dengan sopan", "role": "adjective"}, {"jp": "はなします", "reading": "hanashimasu", "meaning": "berbicara", "role": "verb"}], "translation": "Berbicara dengan sopan kepada/terhadap pelanggan."}, {"tokens": [{"jp": "かれ", "reading": "kare", "meaning": "dia (lk)", "role": "topic"}, {"jp": "の", "reading": "no", "meaning": "(milik)", "role": "particle"}, {"jp": "しつもん", "reading": "shitsumon", "meaning": "pertanyaan", "role": "noun"}, {"jp": "に対して", "reading": "ni taishite", "meaning": "atas / terhadap", "role": "particle"}, {"jp": "すぐ", "reading": "sugu", "meaning": "langsung", "role": "time"}, {"jp": "こたえました", "reading": "kotaemashita", "meaning": "menjawab", "role": "verb"}], "translation": "Langsung menjawab terhadap pertanyaannya."}, {"tokens": [{"jp": "あに", "reading": "ani", "meaning": "kakak laki-laki", "role": "topic"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "しずか", "reading": "shizuka", "meaning": "pendiam", "role": "adjective"}, {"jp": "なのに対して", "reading": "na no ni taishite", "meaning": "sedangkan sebaliknya", "role": "connector"}, {"jp": "おとうと", "reading": "otouto", "meaning": "adik laki-laki", "role": "subject"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "にぎやか", "reading": "nigiyaka", "meaning": "ramai / ceria", "role": "adjective"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Kakaknya pendiam, sedangkan sebaliknya adiknya sangat ceria."}], "forms": [{"label": "Sikap kepada Sasaran", "jp": "みんなに対してやさしい", "reading": "minna ni taishite yasashii", "id": "ramah terhadap semua orang"}, {"label": "Menerangkan Benda", "jp": "せいふに対するふまん", "reading": "seifu ni taisuru fuman", "id": "keluhan terhadap pemerintah"}, {"label": "Perbandingan Kontras", "jp": "Aなのに対してBは", "reading": "A na no ni taishite B wa", "id": "sementara A..., sebaliknya B..."}], "mistakes": [{"wrong": "けいかく に対して の いけん", "right": "けいかく に たいする いけん", "why": "Bila langsung disambung ke kata benda (いけん = pendapat), gunakan ～に対する [Kata Benda], bukan ～に対しての."}, {"wrong": "しつもん を たいして こたえる", "right": "しつもん に たいして こたえる", "why": "Partikel depannya selalu に (ni taishite), bukan を."}], "quiz": [{"question": "Pilih bentuk penyambung ke kata benda untuk ''kebijakan terhadap masalah ini (この もんだい ___ たいさく)'':", "options": ["に対して", "に対する", "に対しての", "を対して"], "answer": 1, "why": "Untuk memodifikasi kata benda (たいさく) di belakangnya, pakailah bentuk kamus に対する."}, {"question": "Dalam kalimat ''とうきょうは あついのにたいして、ほっかいどうは すずしいです'', fungsi のに対して adalah:", "options": ["Menunjukkan perasaan sayang ke Hokkaido", "Membandingkan dua situasi yang kontras (panas vs sejuk)", "Menyatakan sebab akibat", "Memberi perintah"], "answer": 1, "why": "Saat menghubungkan dua fakta yang berlawanan sifatnya, に対して berarti ''berbanding terbalik / sedangkan''."}, {"question": "Manakah kalimat yang tepat mengenai etika kerja?", "options": ["ぶかに たいして きびしい じょうし", "ぶかを たいして きびしい じょうし", "ぶかで たいして きびしい じょうし", "ぶかへ たいして きびしい じょうし"], "answer": 0, "why": "Pola bakunya selalu memakai partikel に sebelum たいして."}]}'::jsonb WHERE code = 'GP-JA-N3-005';
UPDATE grammar_points SET learning_guide = '{"analogy": "～うちに artinya persis kata ''Mumpung...'' atau ''Selagi...''. Maksudnya: lakukanlah sesuatu SEKARANG mumpung situasinya masih mendukung, sebelum terlambat atau keburu berubah!", "when_to_use": ["Mengajak makan selagi panas atau belajar mumpung masih muda", "Memesan tempat atau membereskan pekerjaan mumpung belum lupa / sebelum gelap", "Bercerita bahwa tanpa sadar suatu perubahan terjadi selagi melakukan kegiatan lain (seperti ''ketiduran selagi membaca'')"], "formula_parts": [{"text": "Keadaan Berlangsung (Biasa / NAI / の)", "label": "Kondisi sementara", "role": "time"}, {"text": "うちに", "label": "Mumpung / Selagi", "role": "connector"}, {"text": "Tindakan Segera", "label": "Sebelum berubah", "role": "verb"}], "steps": ["Pasangkan di depan うちに: Verba ～ている / ～ない (''selagi belum...''), Sifat-I tetap, Sifat-Na + な, Kata Benda + の.", "Kombinasi favorit yang sering keluar di ujian: Bentuk-NAI + うちに = ''selagi belum / mumpung belum'' (contoh: わすれない うちに = mumpung belum lupa).", "Di bagian belakangnya, taruh ajakan, tekad, atau perubahan yang berlangsung selagi kondisi awal masih aktif."], "breakdowns": [{"tokens": [{"jp": "あたたかい", "reading": "atatakai", "meaning": "hangat", "role": "adjective"}, {"jp": "うちに", "reading": "uchi ni", "meaning": "mumpung masih", "role": "connector"}, {"jp": "どうぞ", "reading": "douzo", "meaning": "silakan", "role": "connector"}, {"jp": "たべてください", "reading": "tabete kudasai", "meaning": "makanlah", "role": "verb"}], "translation": "Silakan dimakan selagi masih hangat!"}, {"tokens": [{"jp": "わすれない", "reading": "wasurenai", "meaning": "belum lupa (NAI)", "role": "verb"}, {"jp": "うちに", "reading": "uchi ni", "meaning": "mumpung", "role": "connector"}, {"jp": "メモ", "reading": "memo", "meaning": "catatan", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "とっておきます", "reading": "totte okimasu", "meaning": "saya catat dulu", "role": "verb"}], "translation": "Mumpung belum lupa, saya catat dulu ya."}, {"tokens": [{"jp": "にほん", "reading": "Nihon", "meaning": "Jepang", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "di", "role": "particle"}, {"jp": "いる", "reading": "iru", "meaning": "berada", "role": "verb"}, {"jp": "うちに", "reading": "uchi ni", "meaning": "selagi masih", "role": "connector"}, {"jp": "いろいろ", "reading": "iroiro", "meaning": "bermacam-macam", "role": "adjective"}, {"jp": "りょこうしたいです", "reading": "ryokou shitai desu", "meaning": "ingin jalan-jalan", "role": "verb"}], "translation": "Mumpung masih di Jepang, saya ingin berwisata ke mana-mana."}], "forms": [{"label": "Sifat-I", "jp": "わかい うちに", "reading": "wakai uchi ni", "id": "mumpung masih muda"}, {"label": "Belum (NAI)", "jp": "くらくならない うちに", "reading": "kuraku naranai uchi ni", "id": "mumpung hari belum gelap"}, {"label": "Kata Benda (+の)", "jp": "ひるやすみ の うちに", "reading": "hiruyasumi no uchi ni", "id": "selagi masih jam istirahat siang"}], "mistakes": [{"wrong": "５じに なる うちに、かえりましょう", "right": "５じに ならない うちに、かえりましょう", "why": "うちに membutuhkan kondisi yang SEDANG berlangsung atau BELUM berubah; ''sebelum jam 5'' berarti kondisinya masih ''belum menjadi jam 5'' (naranai uchi ni)."}, {"wrong": "げんき うちに、あそぼう", "right": "げんき な うちに、あそぼう", "why": "Sifat-Na wajib menyisipkan な sebelum うちに (genki na uchi ni)."}], "quiz": [{"question": "Lengkapi: ''あめが ___ うちに、はやく うちへ かえりましょう'' (Mumpung belum turun hujan, ayo cepat pulang):", "options": ["ふる", "ふった", "ふらない", "ふって"], "answer": 2, "why": "''Mumpung belum terjadi'' memakai Bentuk-NAI (ふらない) + うちに."}, {"question": "Bagaimana menghubungkan 独身 (どくしん = masih lajang, Kata Benda) dengan うちに?", "options": ["どくしん な うちに", "どくしん の うちに", "どくしん で うちに", "どくしん だ うちに"], "answer": 1, "why": "Kata Benda selalu membutuhkan の di depan うちに (どくしん の うちに)."}, {"question": "Dalam kalimat ''おんがくを きいている うちに、ねむってしまいました'', apa maknanya?", "options": ["Saya sengaja mendengarkan musik supaya bangun", "Tanpa sadar ketiduran di tengah-tengah mendengarkan musik", "Setelah tidur baru mendengarkan musik", "Saya dilarang tidur saat dengar musik"], "answer": 1, "why": "Ketika dipakai dengan Bentuk ～ている + うちに, bisa menggambarkan kejadian tak terduga yang timbul selama kondisi itu berlangsung."}]}'::jsonb WHERE code = 'GP-JA-N3-006';
UPDATE grammar_points SET learning_guide = '{"analogy": "～はずです artinya ''Harusnya sih...'' atau ''Logikanya pasti...''. Bukan nebak asal-asalan, melainkan yakin karena punya bukti, jadwal, atau perhitungan yang jelas!", "when_to_use": ["Menyimpulkan jadwal kereta/acara (''keretanya berangkat jam 9, harusnya sebentar lagi sampai'')", "Meyakini kemampuan teman berdasarkan usaha (''dia belajar keras tiap hari, harusnya lulus!'')", "Versi negatif ～はずがない: ''Mustahil / Mana mungkin...'' berdasarkan logika"], "formula_parts": [{"text": "Bentuk Biasa (+ な u/ Sifat-Na, + の u/ Nomina)", "label": "Dugaan berdasar bukti", "role": "predicate"}, {"text": "はずだ / はずです", "label": "Harusnya menurut logika", "role": "ending"}], "steps": ["Pastikan kamu punya alasan atau bukti kuat di balik keyakinanmu (jadwal, foto, kebiasaan orang itu).", "Sambungkan dengan aturan biasa: Verba/Sifat-I biasa, Sifat-Na + な, Kata Benda + の (misal: やすみ の はずです = harusnya hari ini libur).", "Tambahkan はずです di ujung; kalau terkejut ternyata meleset dari dugaan, pakai はずだったのに (''padahal harusnya...'')."], "breakdowns": [{"tokens": [{"jp": "かれ", "reading": "kare", "meaning": "dia", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "きょう", "reading": "kyou", "meaning": "hari ini", "role": "time"}, {"jp": "くる", "reading": "kuru", "meaning": "datang", "role": "verb"}, {"jp": "はずです", "reading": "hazu desu", "meaning": "harusnya (sesuai jadwal)", "role": "ending"}], "translation": "Menurut jadwal, dia harusnya datang hari ini."}, {"tokens": [{"jp": "さっき", "reading": "sakki", "meaning": "tadi", "role": "time"}, {"jp": "メール", "reading": "meeru", "meaning": "email", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "おくった", "reading": "okutta", "meaning": "sudah kirim", "role": "verb"}, {"jp": "ので", "reading": "node", "meaning": "karena", "role": "connector"}, {"jp": "もう", "reading": "mou", "meaning": "sekarang sudah", "role": "time"}, {"jp": "とどいている", "reading": "todoite iru", "meaning": "sampai/masuk", "role": "verb"}, {"jp": "はずです", "reading": "hazu desu", "meaning": "harusnya sih", "role": "ending"}], "translation": "Karena barusan sudah saya kirim emailnya, harusnya sekarang sudah masuk."}, {"tokens": [{"jp": "きょう", "reading": "kyou", "meaning": "hari ini", "role": "time"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "にちようび", "reading": "nichiyoubi", "meaning": "hari Minggu", "role": "noun"}, {"jp": "だから", "reading": "dakara", "meaning": "karena", "role": "connector"}, {"jp": "ぎんこう", "reading": "ginkou", "meaning": "bank", "role": "subject"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "あいている", "reading": "aite iru", "meaning": "buka", "role": "verb"}, {"jp": "はずがありません", "reading": "hazu ga arimasen", "meaning": "mustahil", "role": "ending"}], "translation": "Karena hari ini hari Minggu, bank tidak mungkin sedang buka."}], "forms": [{"label": "Keyakinan Logis", "jp": "わかるはずです", "reading": "wakaru hazu desu", "id": "harusnya mengerti"}, {"label": "Mustahil (Negatif Kuat)", "jp": "そんなはずがない", "reading": "sonna hazu ga nai", "id": "mana mungkin begitu!"}, {"label": "Ternyata Meleset", "jp": "とどくはずだったのに", "reading": "todoku hazu datta noni", "id": "padahal harusnya sudah sampai"}], "mistakes": [{"wrong": "しゃちょう、きょうは いらっしゃる はずですよ", "right": "きょうは いらっしゃると おもいます", "why": "Memakai ～はずだ ke keputusan pribadi atasan atau menebak kemauan orang bisa terasa sedikit lancang jika tidak berdasar fakta resmi."}, {"wrong": "きょうは やすみ だ はずです", "right": "きょうは やすみ の はずです", "why": "Sebelum はず, Kata Benda memakai の (yasumi no hazu desu), jangan だ."}], "quiz": [{"question": "Kamu mengecek peta dan melihat jaraknya dekat. Kalimat yang pas: ''あと 5ふんで つく ___'' (Harusnya 5 menit lagi sampai):", "options": ["つもりです", "はずです", "ようです", "そうです"], "answer": 1, "why": "Keyakinan berdasarkan perhitungan/bukti jadwal memakai ～はずです."}, {"question": "Apa arti teriakan kaget ''かれが うそを つく はずがない!''?", "options": ["Dia memang sering berbohong", "Mana mungkin dia berbohong! (mustahil menurut sifatnya)", "Sebaiknya dia tidak berbohong", "Saya dengar dia berbohong"], "answer": 1, "why": "～はずがない menyatakan mustahil menurut akal sehat / fakta yang diketahui tentang orang itu."}, {"question": "Cara yang benar menggabungkan sifat-Na かんたん (mudah) dengan はず adalah:", "options": ["かんたん はずです", "かんたんの はずです", "かんたんな はずです", "かんたんだ はずです"], "answer": 2, "why": "Sifat-Na tetap membutuhkan な di depan kata nomina はず."}]}'::jsonb WHERE code = 'GP-JA-N3-007';
UPDATE grammar_points SET learning_guide = '{"analogy": "Bentuk Pasif (~られる) itu seperti awalan ''di-'' di bahasa Indonesia (''dimarahi bos'', ''dibangun tahun 1990'', ''dompetku dicuri orang''). Hati-hati, di Jepang bentuk pasif juga sering dipakai saat pembicara MERASA DIRUGIKAN atau terganggu oleh suatu kejadian (misal: kehujanan di jalan)!", "when_to_use": ["Menceritakan kejadian yang menimpa dirimu (''dipuji guru'', ''dompet dicopet'', ''diundang ke pesta'')", "Menceritakan kejadian alam/sosial yang merugikan tanpa sengaja (''kehujanan di tengah jalan'')", "Menulis fakta netral benda bersejarah atau produk (''kuil ini dibangun 300 tahun lalu'')"], "formula_parts": [{"text": "Korban / Subjek", "label": "Yang dikenai aksi", "role": "topic"}, {"text": "は + Pelaku に", "label": "Oleh siapa", "role": "particle"}, {"text": "Verba Pasif", "label": "Berakhiran -areru / -rareru", "role": "verb"}], "steps": ["Ubah verba ke bentuk pasif: Grup 1 ganti vokal akhir ke baris ''a'' + れる (shikarimasu → shikarareru = dimarahi, iimasu → iwareru); Grup 2 ganti ます jadi られる (homemasu → homerareru = dipuji); Grup 3: shimasu → sareru, kimasu → korareru.", "Tandai pelakunya dengan partikel に (misal: せんせいに ほめられました = dipuji oleh guru).", "Kalau subjeknya barang mati sejarah (''dibuat di Jepang''), pelakunya bisa memakai によって."], "breakdowns": [{"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "せんせい", "reading": "sensei", "meaning": "guru", "role": "noun"}, {"jp": "に", "reading": "ni", "meaning": "oleh", "role": "particle"}, {"jp": "ほめられました", "reading": "homeraremashita", "meaning": "dipuji (pasif)", "role": "verb"}], "translation": "Saya dipuji oleh guru."}, {"tokens": [{"jp": "かえり", "reading": "kaeri", "meaning": "waktu pulang", "role": "time"}, {"jp": "に", "reading": "ni", "meaning": "saat", "role": "particle"}, {"jp": "あめ", "reading": "ame", "meaning": "hujan", "role": "noun"}, {"jp": "に", "reading": "ni", "meaning": "(dikenai)", "role": "particle"}, {"jp": "ふられました", "reading": "furaremashita", "meaning": "kehujanan (pasif rugi)", "role": "verb"}], "translation": "Saat pulang tadi saya kehujanan."}, {"tokens": [{"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "おてら", "reading": "otera", "meaning": "kuil", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "300ねんまえ", "reading": "sanbyakunen mae", "meaning": "300 tahun lalu", "role": "time"}, {"jp": "に", "reading": "ni", "meaning": "pada", "role": "particle"}, {"jp": "たてられました", "reading": "tateraremashita", "meaning": "dibangun", "role": "verb"}], "translation": "Kuil ini dibangun 300 tahun yang lalu."}], "forms": [{"label": "Grup 1 (-a + れる)", "jp": "しかられました", "reading": "shikararemashita", "id": "dimarahi (dari shikaru)"}, {"label": "Grup 2 (+られる)", "jp": "みられました", "reading": "miraremashita", "id": "dilihat (dari miru)"}, {"label": "Grup 3 (する→される)", "jp": "しょうたいされました", "reading": "shoutai saremashita", "id": "diundang"}], "mistakes": [{"wrong": "でんしゃで 足を ともだちに ふみました", "right": "でんしゃで となりのひとに 足を ふまれました", "why": "Bila kaki kita yang diinjak orang, pakai bentuk pasif ふまれました + objek kaki tetap memakai を."}, {"wrong": "いいます → いあれます", "right": "いわれます", "why": "Kata kerja Grup 1 berakhiran -う / -います tidak menjadi ''a'', melainkan ''wa'' + reru (iu → iwareru, kau → kawareru)!"}], "quiz": [{"question": "Bagaimana mengubah かきます (menulis, Grup 1) ke bentuk pasif (''ditulis'')?", "options": ["かかれる", "かけられる", "かきられる", "かされる"], "answer": 0, "why": "き berubah ke vokal ''a'' (か = ka) + れる → かかれる (ditulis)."}, {"question": "Mengapa kalimat ''あめに ふられました'' sering dipakai padahal hujan adalah benda tak bernyawa?", "options": ["Salah tata bahasa tapi populer", "Untuk mengekspresikan ''kehujanan'' yang bikin pembicara terganggu/kerepotan", "Artinya ''saya menurunkan hujan''", "Hanya dipakai dalam puisi kuno"], "answer": 1, "why": "Bahasa Jepang punya ''pasif penderitaan'' (meiwaku no ukemi) saat kejadian alam/orang lain bikin pembicara kerepotan."}, {"question": "Lengkapi: ''かいぎは 日本語で おこな___'' (Rapat diadakan dalam bahasa Jepang; おこなう = mengadakan):", "options": ["おこなあれます", "おこなわれます", "おこなられます", "おこなさせます"], "answer": 1, "why": "Verba berakhiran -u/-います (おこなう) berubah menjadi -わ + れる → おこなわれます."}]}'::jsonb WHERE code = 'GP-JA-N3-008';
UPDATE grammar_points SET learning_guide = '{"analogy": "～たばかり artinya ''Baru saja selesai...'' (menurut PERASAAN si pembicara). Meskipun sudah lewat sebulan atau setahun, kalau rasanya masih hangat/baru banget di benak kita (misal ''baru aja masuk perusahaan ini''), kita pakai ～たばかり!", "when_to_use": ["Menolak ajakan makan karena baru saja makan 10 menit lalu", "Menceritakan hal baru dalam hidup meski kejadiannya beberapa minggu/bulan lalu (''baru aja pindah ke Jepang bulan lalu'')", "Melaporkan produk atau mesin yang baru saja dibeli atau diperbaiki"], "formula_parts": [{"text": "Verba Bentuk-TA", "label": "Sudah terjadi", "role": "verb"}, {"text": "ばかりです", "label": "Baru saja rasanya", "role": "ending"}], "steps": ["Ubah kata kerja ke Bentuk-TA (bentuk lampau kamus, misal: きた, たべた, かった).", "Tambahkan ばかりです di akhir kalimat.", "Kalau mau menerangkan kata benda di belakangnya (''roti yang baru dibeli''), gunakan ～たばかりの + Kata Benda (例: かったばかりの パン)."], "breakdowns": [{"tokens": [{"jp": "さっき", "reading": "sakki", "meaning": "tadi", "role": "time"}, {"jp": "たべた", "reading": "tabeta", "meaning": "makan (TA)", "role": "verb"}, {"jp": "ばかりです", "reading": "bakari desu", "meaning": "baru saja", "role": "ending"}], "translation": "Saya baru saja makan barusan."}, {"tokens": [{"jp": "せんげつ", "reading": "sengetsu", "meaning": "bulan lalu", "role": "time"}, {"jp": "にほん", "reading": "Nihon", "meaning": "Jepang", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "ke", "role": "particle"}, {"jp": "きた", "reading": "kita", "meaning": "datang (TA)", "role": "verb"}, {"jp": "ばかり", "reading": "bakari", "meaning": "baru saja", "role": "connector"}, {"jp": "なので", "reading": "na node", "meaning": "karena", "role": "connector"}, {"jp": "まだ", "reading": "mada", "meaning": "masih belum", "role": "time"}, {"jp": "なれません", "reading": "naremasen", "meaning": "terbiasa", "role": "verb"}], "translation": "Karena baru saja tiba di Jepang bulan lalu, saya belum terbiasa."}, {"tokens": [{"jp": "これ", "reading": "kore", "meaning": "ini", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "きのう", "reading": "kinou", "meaning": "kemarin", "role": "time"}, {"jp": "かった", "reading": "katta", "meaning": "beli (TA)", "role": "verb"}, {"jp": "ばかりの", "reading": "bakari no", "meaning": "yang baru saja", "role": "particle"}, {"jp": "カメラ", "reading": "kamera", "meaning": "kamera", "role": "predicate"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Ini adalah kamera yang baru saja saya beli kemarin."}], "forms": [{"label": "Kalimat Akhir", "jp": "おきたばかりです", "reading": "okita bakari desu", "id": "baru saja bangun"}, {"label": "Sambung Alasan", "jp": "はじめたばかりなので", "reading": "hajimeta bakari na node", "id": "karena baru saja mulai"}, {"label": "Menerangkan Benda", "jp": "うまれたばかりのあかちゃん", "reading": "umareta bakari no akachan", "id": "bayi yang baru saja lahir"}], "mistakes": [{"wrong": "おきたばかりで、でんしゃが しゅっぱつしました", "right": "さっき ついたばかりです / きたところです", "why": "Beda utama dengan ～たところ: ところ murni untuk hitungan detik/menit barusan, sedangkan ばかり bebas menurut perasaan (boleh berbulan-bulan lalu pun asal terasa baru)."}, {"wrong": "さっき かえる ばかりです", "right": "さっき かえった ばかりです", "why": "Selalu wajib memakai Bentuk-TA (sudah selesai), tidak boleh bentuk kamus sebelum ばかり."}], "quiz": [{"question": "Teman mengajak makan siang, tapi kamu baru selesai makan 15 menit lalu. Kamu bilang:", "options": ["さっき たべる ばかりです", "さっき たべた ばかりです", "さっき たべて ばかりです", "さっき たべない ばかりです"], "answer": 1, "why": "Pola ''baru saja selesai'' selalu memakai Bentuk-TA (たべた) + ばかりです."}, {"question": "Mengapa orang bisa berkata ''きょねん けっこんした ばかりです'' (Padahal menikah sudah setahun lalu)?", "options": ["Salah ketik tahun", "~たばかり bergantung pada rasa ''masih baru'' di hati pembicara", "Hanya boleh untuk acara besar", "Artinya akan menikah tahun depan"], "answer": 1, "why": "～たばかり bersifat psikologis; jika dirasa masih pengantin baru, setahun pun bisa memakai ～たばかり."}, {"question": "Bagaimana menerangkan kata benda dengan ～たばかり (''sepatu yang baru dibeli'')?", "options": ["かったばかり くつ", "かったばかりな くつ", "かったばかりの くつ", "かったばかりで くつ"], "answer": 2, "why": "ばかり berlaku seperti nomina di depan kata benda lain, sehingga memakai partikel の."}]}'::jsonb WHERE code = 'GP-JA-N3-009';
UPDATE grammar_points SET learning_guide = '{"analogy": "～によって punya 3 arti andalan tergantung kalimatnya: (1) ''Oleh / Diciptakan oleh...'', (2) ''Tergantung / Berbeda menurut...'', dan (3) ''Disebabkan oleh / Dengan cara...''.", "when_to_use": ["Menyebut pencipta karya atau arsitek suatu penemuan bersejarah dalam kalimat pasif (''ditemukan oleh...'')", "Menyatakan variasi berbeda tergantung faktor (''tergantung negara, budayanya berbeda'')", "Menjelaskan sarana atau sebab resmi dalam berita (''disebabkan oleh gempa'', ''melalui diskusi'')"], "formula_parts": [{"text": "Nomina (Pencipta / Faktor / Sebab)", "label": "Penentu", "role": "noun"}, {"text": "によって / により / による", "label": "Oleh / Tergantung / Akibat", "role": "particle"}, {"text": "Keterangan / Hasil Berbeda", "label": "Penjelas", "role": "predicate"}], "steps": ["Kenali konteks kalimatnya: jika akhir kalimat ada bentuk pasif penemuan (つくられた, かかれた), maka によって artinya ''oleh''.", "Jika belakangnya berupa kata perbedaan (ちがいます, さまざまです), maka によって artinya ''tergantung pada...''.", "Jika diletakkan persis di depan kata benda, ganti ujungnya menjadi による (contoh: たいふうによる ひがい = kerusakan akibat topan)."], "breakdowns": [{"tokens": [{"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "しょうせつ", "reading": "shousetsu", "meaning": "novel", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "むらかみさん", "reading": "Murakami-san", "meaning": "Murakami", "role": "noun"}, {"jp": "によって", "reading": "ni yotte", "meaning": "oleh", "role": "particle"}, {"jp": "かかれました", "reading": "kakaremashita", "meaning": "ditulis (pasif)", "role": "verb"}], "translation": "Novel ini ditulis oleh Murakami."}, {"tokens": [{"jp": "くに", "reading": "kuni", "meaning": "negara", "role": "noun"}, {"jp": "によって", "reading": "ni yotte", "meaning": "tergantung pada", "role": "particle"}, {"jp": "ぶんか", "reading": "bunka", "meaning": "budaya", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "ちがいます", "reading": "chigaimasu", "meaning": "berbeda-beda", "role": "verb"}], "translation": "Tergantung negaranya, budayanya berbeda-beda."}, {"tokens": [{"jp": "じしん", "reading": "jishin", "meaning": "gempa", "role": "noun"}, {"jp": "によって", "reading": "ni yotte", "meaning": "akibat / disebabkan oleh", "role": "particle"}, {"jp": "でんしゃ", "reading": "densha", "meaning": "kereta", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "とまっています", "reading": "tomatte imasu", "meaning": "terhenti", "role": "verb"}], "translation": "Akibat gempa, kereta sedang terhenti."}], "forms": [{"label": "Pencipta (Pasif)", "jp": "レオナルドによってかかれた絵", "reading": "Reonarudo ni yotte kakareta e", "id": "lukisan yang dilukis oleh Leonardo"}, {"label": "Tergantung Faktor", "jp": "ひとによってかんがえがちがう", "reading": "hito ni yotte kangae ga chigau", "id": "tergantung orangnya, pemikirannya beda"}, {"label": "Modifikasi Benda", "jp": "じこによるじゅうたい", "reading": "jiko ni yoru juutai", "id": "kemacetan akibat kecelakaan"}], "mistakes": [{"wrong": "ははによって しかられました", "right": "ははに しかられました", "why": "Untuk kejadian sehari-hari yang mengenai dirimu secara langsung (seperti dimarahi ibu, digigit nyamuk), gunakan partikel に biasa, jangan によって. によって cocok untuk fakta umum/karya resmi."}, {"wrong": "たいふうによっての ひがい", "right": "たいふうによる ひがい", "why": "Saat berada langsung di depan kata benda, bentuk yang benar adalah による (bukan によっての)."}], "quiz": [{"question": "Apa arti kalimat ''きせつ によって ふくの いろが かわります''?", "options": ["Pakaian dibuat oleh musim", "Tergantung musimnya, warna pakaian berubah", "Musim menyebabkan pakaian kotor", "Berdasarkan pakaian, musim ditentukan"], "answer": 1, "why": "Dengan verba perbedaan/perubahan (かわる/ちがう), によって bermakna ''tergantung pada...''."}, {"question": "Lengkapi frasa berita ''火事 ___ 被害 (かじ ___ ひがい = kerusakan akibat kebakaran)'':", "options": ["によって", "による", "にとって", "について"], "answer": 1, "why": "Karena langsung diikuti kata benda 被害 (kerusakan), wajib memakai bentuk kamus による."}, {"question": "Mana yang memakai によって secara paling tepat?", "options": ["きのう いぬに によって かまれました", "この たてものは ゆうめいな けんちくかに よって つくられました", "ともだちに よって カフェへ いきました", "あしたは てんきに よって にちようびです"], "answer": 1, "why": "Menyebut pencipta atau pembangun karya terkenal dalam kalimat pasif memakai によって."}]}'::jsonb WHERE code = 'GP-JA-N3-010';
UPDATE grammar_points SET learning_guide = '{"analogy": "Bentuk-TE + ください sama seperti ungkapan sopan ''Tolong ... ya''. Di level N4, pemakaiannya melebar dari sekadar instruksi kelas hingga permohonan halus dengan penjelas alasan.", "when_to_use": ["Meminta rekan kerja memeriksa dokumen atau mengirim email", "Meminta bantuan saat tersesat, sakit, atau belanja", "Menyambung dua instruksi berurutan (isi formulir dulu, lalu tandatangan)"], "formula_parts": [{"text": "Verba Bentuk-TE", "label": "Bentuk -て / -で", "role": "verb"}, {"text": "ください", "label": "Tolong lakukan", "role": "ending"}], "steps": ["Konjugasikan kata kerja ke Bentuk-TE (misal: 見せます → 見せて, 待ちます → 待って).", "Tambahkan ください untuk meminta secara sopan.", "Kalau meminta ''tolong jangan...'', gunakan Bentuk-NAI + でください (jangan ~te)."], "breakdowns": [{"tokens": [{"jp": "パスポート", "reading": "pasupooto", "meaning": "paspor", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "みせて", "reading": "misete", "meaning": "tunjukkan (TE)", "role": "verb"}, {"jp": "ください", "reading": "kudasai", "meaning": "tolong", "role": "ending"}], "translation": "Tolong tunjukkan paspor Anda."}, {"tokens": [{"jp": "すこし", "reading": "sukoshi", "meaning": "sebentar", "role": "time"}, {"jp": "まって", "reading": "matte", "meaning": "tunggu (TE)", "role": "verb"}, {"jp": "ください", "reading": "kudasai", "meaning": "tolong", "role": "ending"}], "translation": "Tolong tunggu sebentar ya."}, {"tokens": [{"jp": "あした", "reading": "ashita", "meaning": "besok", "role": "time"}, {"jp": "まで", "reading": "made", "meaning": "sampai", "role": "particle"}, {"jp": "に", "reading": "ni", "meaning": "paling lambat", "role": "particle"}, {"jp": "レポート", "reading": "repooto", "meaning": "laporan", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "だして", "reading": "dashite", "meaning": "kumpulkan (TE)", "role": "verb"}, {"jp": "ください", "reading": "kudasai", "meaning": "tolong", "role": "ending"}], "translation": "Tolong kumpulkan laporannya paling lambat besok."}], "forms": [{"label": "Tolong Lakukan", "jp": "すわってください", "reading": "suwatte kudasai", "id": "tolong duduk"}, {"label": "Tolong Jangan", "jp": "すわらないでください", "reading": "suwaranaide kudasai", "id": "tolong jangan duduk"}, {"label": "Permohonan Lembut", "jp": "てつだってくださいませんか", "reading": "tetsudatte kudasaimasen ka", "id": "maukah membantu saya?"}], "mistakes": [{"wrong": "しゃしんを とらないて ください", "right": "しゃしんを とらないで ください", "why": "Bila meminta ''jangan melakukan'', setelah Bentuk-NAI memakai で (naide), bukan て."}, {"wrong": "おちゃを もち ください", "right": "おちゃを もって ください", "why": "Setelah ください untuk kata kerja wajib Bentuk-TE, tidak bisa akar masu langsung."}], "quiz": [{"question": "Bagaimana mengatakan ''Tolong tutup jendela'' (しめます = grup 2)?", "options": ["しめて ください", "しめって ください", "しまて ください", "しめんで ください"], "answer": 0, "why": "しめます (Grup 2) diubah ke Bentuk-TE dengan mengganti ます menjadi て → しめて."}, {"question": "Cara berkata ''Tolong tunggu di kamar ini'' (まちます = menunggu) adalah:", "options": ["まいて ください", "まちて ください", "まって ください", "まんで ください"], "answer": 2, "why": "ち sebelum ます (machi-masu) pada Grup 1 berubah menjadi って → まって."}, {"question": "Kalau ingin meminta seseorang ''Tolong JANGAN merokok'' (すいます -> すわない), pola yang tepat adalah:", "options": ["すって くださいません", "すわないで ください", "すいまて ください", "すわて ください"], "answer": 1, "why": "Permohonan larangan menggunakan Bentuk-NAI + でください."}]}'::jsonb WHERE code = 'GP-JA-N4-001';
UPDATE grammar_points SET learning_guide = '{"analogy": "～ている bukan cuma ''sedang melakukan sesuatu'', di level N4 pola ini juga menyatakan ''hasil aksi yang bekasnya masih terlihat sampai sekarang'' (misal: jendela sedang terbuka, lampu sedang menyala, sudah menikah).", "when_to_use": ["Menyatakan aktivitas yang tengah berlangsung detik ini", "Menyatakan kondisi hasil sebuah perubahan (pintu terkunci, baju sedang dipakai, mobil terparkir)", "Menjelaskan kebiasaan rutin atau pekerjaan tetap"], "formula_parts": [{"text": "Verba Bentuk-TE", "label": "Aksi / Perubahan", "role": "verb"}, {"text": "います", "label": "Sedang / Kondisinya begitu", "role": "ending"}], "steps": ["Kenali jenis verba: kalau kata kerjanya berupa aksi (makan, baca) → artinya ''sedang melakukan''.", "Kalau kata kerjanya berupa perubahan sekejap (pintu membuka/menutup, lampu menyala, menikah, mati) → artinya ''kondisinya sekarang sudah begitu''.", "Untuk membedakan status tanpa pelaku, gunakan verba intransitif (aku/shimaru) dengan が: まどが あいています (jendela dalam keadaan terbuka)."], "breakdowns": [{"tokens": [{"jp": "まど", "reading": "mado", "meaning": "jendela", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "あいて", "reading": "aite", "meaning": "terbuka (TE)", "role": "verb"}, {"jp": "います", "reading": "imasu", "meaning": "keadaannya sedang", "role": "ending"}], "translation": "Jendelanya dalam keadaan terbuka."}, {"tokens": [{"jp": "きむらさん", "reading": "Kimura-san", "meaning": "Sdr. Kimura", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "あかい", "reading": "akai", "meaning": "merah", "role": "adjective"}, {"jp": "シャツ", "reading": "shatsu", "meaning": "kemeja", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "きて", "reading": "kite", "meaning": "memakai (TE)", "role": "verb"}, {"jp": "います", "reading": "imasu", "meaning": "sedang / mengenakan", "role": "ending"}], "translation": "Kimura sedang mengenakan kemeja merah."}, {"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "ぎんこう", "reading": "ginkou", "meaning": "bank", "role": "place"}, {"jp": "で", "reading": "de", "meaning": "di", "role": "particle"}, {"jp": "はたらいて", "reading": "hataraite", "meaning": "bekerja (TE)", "role": "verb"}, {"jp": "います", "reading": "imasu", "meaning": "(profesi tetap)", "role": "ending"}], "translation": "Saya bekerja di bank."}], "forms": [{"label": "Keadaan Sekarang", "jp": "でんきがついています", "reading": "denki ga tsuite imasu", "id": "lampunya sedang menyala"}, {"label": "Lampau (Tadi Sedang)", "jp": "さっきねていました", "reading": "sakki nete imashita", "id": "tadi dia sedang tidur"}, {"label": "Belum / Tidak", "jp": "まだきていません", "reading": "mada kite imasen", "id": "belum datang"}], "mistakes": [{"wrong": "めがねを かけます (saat menunjuk org berkacamata)", "right": "めがねを かけています", "why": "Menjelaskan pakaian, topi, atau kacamata yang sedang menempel di tubuh seseorang wajib memakai ～ています."}, {"wrong": "まだ たべません (artinya belum makan)", "right": "まだ たべていません", "why": "Untuk menyatakan ''belum selesai / masih belum dilakukan hingga sekarang'', gunakan まだ ～ていません."}], "quiz": [{"question": "Arti paling tepat dari kalimat ''いすが こわれています'' (こわれる = rusak) adalah:", "options": ["Kursi itu akan segera rusak", "Kursi itu sedang rusak (dalam keadaan rusak)", "Tolong perbaiki kursi itu", "Seseorang sedang merusak kursi"], "answer": 1, "why": "こわれる adalah verba perubahan keadaan, sehingga ～ています menyatakan hasilnya masih berlangsung (keadaan rusak)."}, {"question": "Bagaimana mengatakan ''Busnya belum datang'' hingga detik ini?", "options": ["バスは まだ きません", "バスは まだ きませんでした", "バスは まだ きていません", "バスは もう きていません"], "answer": 2, "why": "Konsep ''belum ... hingga saat ini'' selalu menggunakan pola まだ + Bentuk-TE + いません."}, {"question": "Saat menggambarkan teman yang berpenampilan memakai kacamata:", "options": ["めがねを かけています", "めがねを かけます", "めがねが あります", "めがねを きます"], "answer": 0, "why": "Verba mengenakan kacamata adalah かけます, dan kondisi memakainya memakai ～ています."}]}'::jsonb WHERE code = 'GP-JA-N4-002';
UPDATE grammar_points SET learning_guide = '{"analogy": "～なければなりません itu artinya ''mau tidak mau HARUS melakukan''. Di balik rumus panjangnya, makna aslinya lucu: ''kalau tidak [verba], tidak akan beres'' — makanya jadi berarti HARUS!", "when_to_use": ["Menyatakan aturan kantor, sekolah, atau hukum yang wajib dipatuhi", "Menyatakan kewajiban pribadi (harus minum obat, harus belajar untuk ujian besok)", "Sebaliknya, kalau mau bilang ''tidak wajib'', pakai ～なくてもいいです"], "formula_parts": [{"text": "Bentuk-NAI (buang い)", "label": "Akar negasi (-na)", "role": "verb"}, {"text": "ければなりません", "label": "Kalau tidak -> tidak boleh (= Harus)", "role": "ending"}], "steps": ["Ubah kata kerja ke Bentuk-NAI dulu (nomimasu → nomanai, ikimasu → ikanai, shimasu → shinai).", "Buang huruf い di akhir kata -ない, lalu ganti dengan ければなりません.", "Jika situasinya santai dengan teman, orang Jepang sering menyingkat ujungnya menjadi ～なくちゃ atau ～なきゃ."], "breakdowns": [{"tokens": [{"jp": "くすり", "reading": "kusuri", "meaning": "obat", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "のまなければなりません", "reading": "nomanakereba narimasen", "meaning": "harus minum", "role": "verb"}], "translation": "Harus minum obat."}, {"tokens": [{"jp": "きょう", "reading": "kyou", "meaning": "hari ini", "role": "time"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "はやく", "reading": "hayaku", "meaning": "lebih awal", "role": "adjective"}, {"jp": "かえらなければなりません", "reading": "kaeranakereba narimasen", "meaning": "harus pulang", "role": "verb"}], "translation": "Hari ini saya harus pulang lebih awal."}, {"tokens": [{"jp": "ここ", "reading": "koko", "meaning": "di sini", "role": "place"}, {"jp": "では", "reading": "de wa", "meaning": "(konteks)", "role": "particle"}, {"jp": "くつ", "reading": "kutsu", "meaning": "sepatu", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "ぬがなければなりません", "reading": "nuganakereba narimasen", "meaning": "wajib melepas", "role": "verb"}], "translation": "Di sini kita harus melepas sepatu."}], "forms": [{"label": "Wajib Formal", "jp": "いかなければなりません", "reading": "ikanakereba narimasen", "id": "harus pergi"}, {"label": "Lampau Wajib", "jp": "いかなければなりませんでした", "reading": "ikanakereba narimasen deshita", "id": "kemarin harus pergi"}, {"label": "Tidak Perlu (Lawan)", "jp": "いかなくてもいいです", "reading": "ikanakutemo ii desu", "id": "tidak usah pergi"}], "mistakes": [{"wrong": "いくなければなりません", "right": "いかなければなりません", "why": "Jangan tempelkan ke bentuk kamus; wajib ubah ke Bentuk-NAI (ikanai), buang い, lalu tambah ければなりません."}, {"wrong": "あした やすみでも いかなくては いいです", "right": "あしたは いかなくても いいです", "why": "''Tidak perlu'' memakai ～なくてもいいです (bukan なければ)."}], "quiz": [{"question": "Bagaimana mengatakan ''Saya harus menulis laporan'' (かきます -> かかない)?", "options": ["かかなければなりません", "かきなければなりません", "かくなければなりません", "かいてなりません"], "answer": 0, "why": "Ambil akar Bentuk-NAI (かかな-) lalu tempelkan ければなりません."}, {"question": "Apa arti kalimat ''どようびは しゅっきん しなくてもいいです''?", "options": ["Hari Sabtu wajib masuk kerja", "Hari Sabtu dilarang masuk kerja", "Hari Sabtu tidak perlu masuk kerja", "Hari Sabtu ingin masuk kerja"], "answer": 2, "why": "Bentuk-NAI (tanpa い) + くてもいいです artinya tidak wajib / boleh tidak melakukan."}, {"question": "Kalau kewajibannya terjadi KEMARIN (''Kemarin harus lembur''), ujungnya berubah menjadi:", "options": ["～なければなりません", "～なければなりませんでした", "～なかったらなりません", "～ないでした"], "answer": 1, "why": "Bentuk lampau dari なりません adalah なりませんでした."}]}'::jsonb WHERE code = 'GP-JA-N4-003';
UPDATE grammar_points SET learning_guide = '{"analogy": "Bentuk Potensial artinya ''bisa / mampu / memungkinkan'' (seperti imbuhan ''bisa...'' atau ''dapat...'' dalam bahasa Indonesia). Objeknya biasanya berubah memakai partikel が.", "when_to_use": ["Menyatakan keahlian bahasa, olahraga, atau skill (''bisa membaca Kanji'', ''bisa berenang'')", "Menyatakan suatu tempat/situasi memungkinkan suatu hal dilakukan (''di sini bisa pesan kopi'')", "Bentuk negatifnya berarti ''tidak bisa'' (bisa karena tidak mampu atau karena situasi tidak memungkinkan)"], "formula_parts": [{"text": "Hal yang Bisa Dilakukan", "label": "Kemampuan", "role": "subject"}, {"text": "が", "label": "Penanda objek mampu", "role": "particle"}, {"text": "Verba Potensial + ます", "label": "Bisa ... (Grup 1-3)", "role": "verb"}], "steps": ["Grup 1 (bunyi ''i'' sebelum masu): ganti vokal i ke baris ''e'' (kaki-masu → kake-masu = bisa menulis, hanashi-masu → hanase-masu = bisa bicara).", "Grup 2 (seperti tabe-masu, mi-masu): ubah ます menjadi られます (tabe-raremasu = bisa makan, mi-raremasu = bisa melihat).", "Grup 3 (pengecualian): shimasu → dekimasu (bisa), kimasu → koraremasu (bisa datang). Catat: objek kalimat potensial biasanya pakai が."], "breakdowns": [{"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "およげます", "reading": "oyogemasu", "meaning": "bisa berenang", "role": "verb"}], "translation": "Saya bisa berenang."}, {"tokens": [{"jp": "かんじ", "reading": "kanji", "meaning": "huruf Kanji", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(objek mampu)", "role": "particle"}, {"jp": "よめます", "reading": "yomemasu", "meaning": "bisa membaca", "role": "verb"}], "translation": "Saya bisa membaca Kanji."}, {"tokens": [{"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "レストラン", "reading": "resutoran", "meaning": "restoran", "role": "place"}, {"jp": "では", "reading": "de wa", "meaning": "di sini", "role": "particle"}, {"jp": "カード", "reading": "kaado", "meaning": "kartu kredit", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(objek mampu)", "role": "particle"}, {"jp": "つかえません", "reading": "tsukaemasen", "meaning": "tidak bisa dipakai", "role": "verb"}], "translation": "Di restoran ini kartu tidak dapat digunakan."}], "forms": [{"label": "Grup 1 (i→e)", "jp": "かけます", "reading": "kakemasu", "id": "bisa menulis (dari kakimasu)"}, {"label": "Grup 2 (+られ)", "jp": "たべられます", "reading": "taberaremasu", "id": "bisa makan (dari tabemasu)"}, {"label": "Negatif", "jp": "よめません", "reading": "yomemasen", "id": "tidak bisa membaca"}, {"label": "Khusus shimasu", "jp": "うんてんできます", "reading": "unten dekimasu", "id": "bisa menyetir"}], "mistakes": [{"wrong": "きのう えいがが みれます (dalam tulisan resmi)", "right": "きのう えいがが みられました", "why": "Secara lisan sering diucapkan ''miremasu'', tapi bentuk baku tes JLPT untuk Grup 2 tetap memakai ''～られます'' (miraremasu)."}, {"wrong": "くるまを うんてん しまれます", "right": "くるまが うんてん できます", "why": "Kata kerja します tidak diubah menjadi しまれます, melainkan diganti langsung menjadi できます."}], "quiz": [{"question": "Bagaimana bentuk potensial (''bisa berbicara'') dari はなします (Grup 1)?", "options": ["はなせられます", "はなせます", "はなしできます", "はなさます"], "answer": 1, "why": "Grup 1 cukup ubah huruf sebelum ます ke baris vokal E: し (shi) → せ (se) → はなせます."}, {"question": "Lengkapi kalimat ''あした ７じに ___ か'' (Apakah kamu bisa datang jam 7 besok? きます = datang):", "options": ["きます", "きられます", "こられます", "きますできます"], "answer": 2, "why": "きます (Grup 3) bentuk potensial bakunya adalah こられます."}, {"question": "Manakah kalimat yang tepat untuk ''Saya tidak bisa makan makanan pedas (からい たべもの)''?", "options": ["からい たべものが たべられません", "からい たべものが たべません", "からい たべものを たべますか", "からい たべものが たべれません"], "answer": 0, "why": "たべます (Grup 2) diubah menjadi たべられます, lalu negatifnya たべられません."}]}'::jsonb WHERE code = 'GP-JA-N4-004';
UPDATE grammar_points SET learning_guide = '{"analogy": "Di Jepang, kata kerja ''memberi/melakukan sesuatu untuk orang lain'' dibedakan dari arah kebaikannya: kalau SAYA (atau kelompok saya) berbuat baik ke orang lain pakai ～てあげます; kalau ORANG LAIN berbuat baik ke SAYA pakai ～てくれます.", "when_to_use": ["Menawarkan atau bercerita bahwa kamu menolong seseorang (pakai ～てあげます)", "Berterima kasih atau menceritakan seseorang menolong/mengajarkanmu (pakai ～てくれます)", "Meminta izin dengan sangat sopan sambil menyatakan kebaikan kepada orang yang dekat"], "formula_parts": [{"text": "Pemberi は", "label": "Yang menolong", "role": "topic"}, {"text": "Penerima に", "label": "Yang ditolong", "role": "noun"}, {"text": "Verba Bentuk-TE", "label": "Aksi bantuannya", "role": "verb"}, {"text": "あげます / くれます", "label": "Ke org lain / Ke saya", "role": "ending"}], "steps": ["Cek dulu siapa yang menerima manfaat aksinya!", "Kalau orang lain yang menerima kebaikan (bukan dirimu), pakai ～てあげます (hati-hati: jangan pakai ke atasan langsung karena terkesan menggurui!).", "Kalau DIRIMU (atau keluargamu) yang dibantu oleh orang lain, WAJIB pakai ～てくれます."], "breakdowns": [{"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "ともだち", "reading": "tomodachi", "meaning": "teman", "role": "noun"}, {"jp": "に", "reading": "ni", "meaning": "kepada", "role": "particle"}, {"jp": "にほんご", "reading": "nihongo", "meaning": "bahasa Jepang", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "おしえて", "reading": "oshiete", "meaning": "mengajarkan (TE)", "role": "verb"}, {"jp": "あげました", "reading": "agemashita", "meaning": "telah memberi bantuan", "role": "ending"}], "translation": "Saya mengajarkan bahasa Jepang untuk teman saya."}, {"tokens": [{"jp": "やまださん", "reading": "Yamada-san", "meaning": "Sdr. Yamada", "role": "topic"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "noun"}, {"jp": "に", "reading": "ni", "meaning": "untuk", "role": "particle"}, {"jp": "しゃしん", "reading": "shashin", "meaning": "foto", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "とって", "reading": "totte", "meaning": "memotret (TE)", "role": "verb"}, {"jp": "くれました", "reading": "kuremashita", "meaning": "telah berbaik hati", "role": "ending"}], "translation": "Yamada memotretkan foto untuk saya."}, {"tokens": [{"jp": "はは", "reading": "haha", "meaning": "ibu saya", "role": "topic"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "まいにち", "reading": "mainichi", "meaning": "setiap hari", "role": "time"}, {"jp": "おいしい", "reading": "oishii", "meaning": "enak", "role": "adjective"}, {"jp": "りょうり", "reading": "ryouri", "meaning": "masakan", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "つくって", "reading": "tsukutte", "meaning": "membuatkan (TE)", "role": "verb"}, {"jp": "くれます", "reading": "kuremasu", "meaning": "untuk saya", "role": "ending"}], "translation": "Ibu saya membuatkan masakan enak setiap hari (untuk saya)."}], "forms": [{"label": "Membantu Org Lain", "jp": "おしえてあげます", "reading": "oshiete agemasu", "id": "mengajarkan untuknya"}, {"label": "Dibantu Org Lain", "jp": "おしえてくれます", "reading": "oshiete kuremasu", "id": "diajari untuk saya"}, {"label": "Menerima Bantuan", "jp": "おしえてもらいます", "reading": "oshiete moraimasu", "id": "mendapat bantuan diajarkan"}], "mistakes": [{"wrong": "せんせいが わたしに ほんを かして あげました", "right": "せんせいが わたしに ほんを かして くれました", "why": "Bila penerima bantuannya adalah わたし (saya), TIDAK BOLEH memakai あげます, wajib memakai くれます!"}, {"wrong": "ぶちょう、てつだって あげましょうか (ke bos)", "right": "ぶちょう、おてつだい しましょうか", "why": "Ke atasan atau orang asing, memakai ～てあげます terdengar agak angkuh. Gunakan お～しましょうか."}], "quiz": [{"question": "Temanmu mengantar dirimu ke stasiun (おくる = mengantar). Kalimat yang paling tepat untuk bercerita adalah:", "options": ["ともだちが えきまで おくって あげました", "ともだちが えきまで おくって くれました", "わたしが えきまで おくって くれました", "ともだちに えきまで おくって あげました"], "answer": 1, "why": "Yang dibantu adalah kamu (pembicara), sedangkan pelakunya teman. Arah kebaikan ke diri sendiri memakai くれます."}, {"question": "Kalau kamu yang membacakan buku cerita untuk adikmu (いもうと = adik perempuan):", "options": ["わたしは いもうとに ほんを よんで くれました", "わたしは いもうとに ほんを よんで あげました", "いもうとは わたしに ほんを よんで あげました", "わたしは いもうとが ほんを よんで もらいました"], "answer": 1, "why": "Pembicara berbuat baik kepada adik (orang lain), maka memakai ～てあげました."}, {"question": "Mengapa sebaiknya kita menghindari berkata ''せんせい、おしえてあげますよ'' ke guru?", "options": ["Karena salah tata bahasa partikelnya", "Karena ~te agemasu bernuansa sedikit superior (''nih aku bantuin kamu'')", "Karena artinya ''guru membantu saya''", "Karena hanya dipakai di masa lalu"], "answer": 1, "why": "あげます bermakna memberi ke bawah/setara, sehingga terkesan kurang sopan bila ditujukan ke atasan atau guru."}]}'::jsonb WHERE code = 'GP-JA-N4-005';
UPDATE grammar_points SET learning_guide = '{"analogy": "～たほうがいいです artinya mirip nasihat akrab ''Sebaiknya kamu...'' atau ''Lebih bagus kamu...'', sedangkan versi negatifnya ～ないほうがいいです artinya ''Sebaiknya kamu jangan...''.", "when_to_use": ["Memberikan saran kesehatan (''kamu demam, sebaiknya istirahat/pergi ke RS'')", "Memberikan tips belajar, perjalanan, atau persiapan (''sebaiknya bawa payung'')", "Mengingatkan teman agar menghindari sesuatu (''sebaiknya jangan begadang'')"], "formula_parts": [{"text": "Bentuk-TA / Bentuk-NAI", "label": "Sebaiknya / Sebaiknya tidak", "role": "verb"}, {"text": "ほうがいい", "label": "Sisi yang lebih baik", "role": "noun"}, {"text": "です", "label": "(Sopan)", "role": "ending"}], "steps": ["Untuk menyarankan DILAKUKAN: ubah kata kerja ke Bentuk-TA (bentuk lampau kamus, misal: iku → itta, nomu → nonda, miru → mita), lalu tambahkan ほうがいいです.", "Untuk menyarankan JANGAN DILAKUKAN: pakai Bentuk-NAI (misal: nomanai, ikanai) + ほうがいいです.", "Tips: pakai pola ini kepada teman atau junior. Kepada bos, lebih sopan memakai kalimat pertanyaan halus (~tara dou desu ka)."], "breakdowns": [{"tokens": [{"jp": "はやめに", "reading": "hayame ni", "meaning": "lebih cepat", "role": "time"}, {"jp": "ねた", "reading": "neta", "meaning": "tidur (TA)", "role": "verb"}, {"jp": "ほうが", "reading": "hou ga", "meaning": "sebaiknya", "role": "connector"}, {"jp": "いいです", "reading": "ii desu", "meaning": "lebih baik", "role": "ending"}], "translation": "Sebaiknya kamu tidur lebih awal."}, {"tokens": [{"jp": "毎日", "reading": "mainichi", "meaning": "setiap hari", "role": "time"}, {"jp": "すこしずつ", "reading": "sukoshi zutsu", "meaning": "sedikit demi sedikit", "role": "adjective"}, {"jp": "れんしゅうした", "reading": "renshuu shita", "meaning": "berlatih (TA)", "role": "verb"}, {"jp": "ほうがいいです", "reading": "hou ga ii desu", "meaning": "sebaiknya", "role": "ending"}], "translation": "Sebaiknya berlatih sedikit demi sedikit setiap hari."}, {"tokens": [{"jp": "かぜ", "reading": "kaze", "meaning": "masuk angin", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(saat)", "role": "particle"}, {"jp": "とき", "reading": "toki", "meaning": "ketika", "role": "time"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "おさけ", "reading": "osake", "meaning": "alkohol", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "のまない", "reading": "nomanai", "meaning": "tidak minum (NAI)", "role": "verb"}, {"jp": "ほうがいいです", "reading": "hou ga ii desu", "meaning": "sebaiknya jangan", "role": "ending"}], "translation": "Saat sedang flu, sebaiknya jangan minum alkohol."}], "forms": [{"label": "Saran Positif", "jp": "びょういんへいったほうがいいです", "reading": "byouin e itta hou ga ii desu", "id": "sebaiknya pergi ke RS"}, {"label": "Saran Negatif", "jp": "むりをしないほうがいいです", "reading": "muri o shinai hou ga ii desu", "id": "sebaiknya jangan memaksakan diri"}], "mistakes": [{"wrong": "くすりを のむ ほうがいいです (saran satu kali)", "right": "くすりを のんだ ほうがいいです", "why": "Bila memberi saran pada situasi spesifik sekarang, jauh lebih alami dan baku memakai Bentuk-TA (nonda), bukan bentuk kamus."}, {"wrong": "たべなかった ほうがいいです", "right": "たべない ほうがいいです", "why": "Untuk saran larangan (''sebaiknya jangan''), selalu memakai Bentuk-NAI masa kini (tabenai), jangan lampau."}], "quiz": [{"question": "Temanmu tampak pucat. Kamu mau bilang ''Sebaiknya istirahat (やすみます -> やすんだ)'':", "options": ["やすむ ほうがいいです", "やすんだ ほうがいいです", "やすんで ほうがいいです", "やすみ ほうがいいです"], "answer": 1, "why": "Saran positif menggunakan kata kerja Bentuk-TA (やすんだ) + ほうがいいです."}, {"question": "Bagaimana mengatakan ''Sebaiknya tidak keluar malam-malam'' (でかけます -> でかけない)?", "options": ["でかけなかった ほうがいいです", "でかけた ほうがいいです", "でかけない ほうがいいです", "でかけません ほうがいいです"], "answer": 2, "why": "Saran negatif menggunakan Bentuk-NAI sekarang (でかけない) + ほうがいいです."}, {"question": "Nuansa pola ～たほうがいいです bila diucapkan langsung ke atasan di kantor adalah:", "options": ["Terlalu tegas/menggurui, sebaiknya pakai saran lebih halus ke atasan", "Sangat hormat seperti keigo", "Hanya dipakai dalam surat resmi", "Bermakna pujian"], "answer": 0, "why": "～たほうがいい terkesan cukup tegas memberi tahu apa yang seharusnya dilakukan, lebih pas untuk teman atau bawahan."}]}'::jsonb WHERE code = 'GP-JA-N4-006';
UPDATE grammar_points SET learning_guide = '{"analogy": "～ので itu artinya ''karena... (jadi/maka...)''. Kalau di N5 ada から (karakternya lebih subjektif/pribadi), di N4 ～ので jauh lebih sopan, lembut, dan terdengar seperti alasan objektif ketika minta izin atau minta maaf.", "when_to_use": ["Meminta izin pulang cepat atau cuti karena ada urusan mendadak", "Menjelaskan penyebab keterlambatan atau kesalahan dengan sopan", "Mengungkapkan alasan logis situasi alam atau jadwal (karena hujan, pertandingan ditunda)"], "formula_parts": [{"text": "Alasan (Bentuk Biasa)", "label": "Verba/Sifat-i biasa | Nomina/Sifat-na + な", "role": "connector"}, {"text": "ので", "label": "Karena (halus/objektif)", "role": "particle"}, {"text": "Akibat / Permintaan", "label": "Hasilnya", "role": "predicate"}], "steps": ["Letakkan kalimat alasannya di depan kata ので.", "PERHATIAN PENTING: Jika alasannya berakhir dengan KATA BENDA atau KATA SIFAT-NA (dalam bentuk sekarang positif), wajib sisipkan な di antara kata itu dan ので (misal: あめ なので, ひま なので)!", "Untuk kata kerja atau sifat-i, langsung pakai bentuk biasa kasual (atau kadang masu di lisan sangat formal) + ので."], "breakdowns": [{"tokens": [{"jp": "あつい", "reading": "atsui", "meaning": "panas", "role": "adjective"}, {"jp": "ので", "reading": "node", "meaning": "karena", "role": "particle"}, {"jp": "まど", "reading": "mado", "meaning": "jendela", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "あけます", "reading": "akemasu", "meaning": "saya buka", "role": "verb"}], "translation": "Karena panas, saya buka jendelanya ya."}, {"tokens": [{"jp": "にちようび", "reading": "nichiyoubi", "meaning": "hari Minggu", "role": "time"}, {"jp": "な", "reading": "na", "meaning": "(penghubung nomina)", "role": "particle"}, {"jp": "ので", "reading": "node", "meaning": "karena", "role": "particle"}, {"jp": "ぎんこう", "reading": "ginkou", "meaning": "bank", "role": "subject"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "やすみ", "reading": "yasumi", "meaning": "tutup/libur", "role": "predicate"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Karena hari Minggu, bank tutup."}, {"tokens": [{"jp": "バス", "reading": "basu", "meaning": "bus", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "おくれた", "reading": "okureta", "meaning": "terlambat (lampau)", "role": "verb"}, {"jp": "ので", "reading": "node", "meaning": "karena", "role": "particle"}, {"jp": "かいぎ", "reading": "kaigi", "meaning": "rapat", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "pada", "role": "particle"}, {"jp": "まにあいませんでした", "reading": "maniaimasen deshita", "meaning": "tidak sempat tepat waktu", "role": "verb"}], "translation": "Karena busnya terlambat, saya tidak sempat tiba tepat waktu untuk rapat."}], "forms": [{"label": "Kata Kerja", "jp": "ようじがあるのでかえります", "reading": "youji ga aru node kaerimasu", "id": "karena ada urusan, saya pulang"}, {"label": "Kata Benda (+な)", "jp": "びょうきなのでやすみます", "reading": "byouki na node yasumimasu", "id": "karena sakit, saya istirahat"}, {"label": "Sifat-I", "jp": "いそがしいのでいけません", "reading": "isogashii node ikemasen", "id": "karena sibuk, tidak bisa pergi"}], "mistakes": [{"wrong": "あめ だ ので、いきません", "right": "あめ な ので、いきません", "why": "Bila didahului Kata Benda (あめ) atau Sifat-Na (しずか), huruf だ wajib berubah menjadi な sebelum ので!"}, {"wrong": "さむい ので、ドアを しめて！ (perintah keras)", "right": "さむい から、ドアを しめて", "why": "Karena ～ので bernuansa lembut/objektif, hindari memasangkannya dengan kalimat perintah kasar atau ajakan pribadi keras."}], "quiz": [{"question": "Lengkapi: ''あした テスト ___、きょうは はやく かえります'' (Karena besok ujian, hari ini pulang cepat; テスト = kata benda):", "options": ["テスト で ので", "テスト だ ので", "テスト な ので", "テスト の ので"], "answer": 2, "why": "Kata benda (テスト) + な + ので → テストなので."}, {"question": "Apa perbedaan utama antara ～ので dan ～から saat meminta izin ke atasan?", "options": ["Tidak ada perbedaan sama sekali", "~ので terdengar lebih lembut, objektif, dan sopan untuk alasan izin/maaf", "~から jauh lebih formal untuk email bisnis", "~ので hanya boleh untuk peristiwa masa lalu"], "answer": 1, "why": "～ので memberi kesan alasan yang objektif sehingga sangat aman dipakai di kantor atau saat memohon izin."}, {"question": "Pilih kalimat yang benar secara tata bahasa:", "options": ["しずか ので、よく ねられます", "ねむい な ので、ねます", "じかんが ない ので、タクシーで いきます", "あめ ので、うちへ かえります"], "answer": 2, "why": "ない (bentuk biasa negatif) langsung disambung ke ので menjadi じかんがない ので."}]}'::jsonb WHERE code = 'GP-JA-N4-007';
UPDATE grammar_points SET learning_guide = '{"analogy": "～たら artinya bisa dua macam tergantung konteks: ''Kalau (syarat)...'' atau ''Nanti setelah ... selesai''. Uniknya, pembentukannya sangat gampang karena tinggal menambahkan huruf ら di belakang bentuk lampau biasa (-ta / -katta / -datta)!", "when_to_use": ["Mengungkapkan syarat pengandaian (''kalau hujan tidak jadi pergi'', ''kalau punya uang mau beli rumah'')", "Menyusun rencana berdasarkan waktu selesai suatu hal (''nanti kalau sudah sampai stasiun, kabari ya'')", "Berandai-andai tentang kejadian yang belum tentu terjadi (''kalau menang lotre...'')"], "formula_parts": [{"text": "Bentuk Lampau Biasa (-TA / -かった / -だった)", "label": "Syarat / Kondisi", "role": "verb"}, {"text": "ら", "label": "Kalau / Setelah (-ra)", "role": "connector"}, {"text": "Hasil / Tindakan Berikutnya", "label": "Apa yang terjadi", "role": "predicate"}], "steps": ["Ubah kata kerja, kata sifat, atau kata benda menjadi bentuk lampau kasualnya (contoh: たべる → たべた, おいしい → おいしかった, ひま → ひまだった).", "Tinggal tambahkan huruf ら di belakangnya (たべたら, おいしかったら, ひまだったら).", "Tambahkan kalimat utama di belakangnya. Meski memakai bentuk lampau -た, maknanya di sini bukan masa lalu melainkan ''kalau/setelah''!"], "breakdowns": [{"tokens": [{"jp": "やすかった", "reading": "yasukatta", "meaning": "kalau murah (lampau)", "role": "adjective"}, {"jp": "ら", "reading": "ra", "meaning": "apabila", "role": "connector"}, {"jp": "かいます", "reading": "kaimasu", "meaning": "saya beli", "role": "verb"}], "translation": "Kalau murah, saya beli."}, {"tokens": [{"jp": "うち", "reading": "uchi", "meaning": "rumah", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "ke", "role": "particle"}, {"jp": "かえったら", "reading": "kaettara", "meaning": "nanti setelah pulang", "role": "verb"}, {"jp": "すぐ", "reading": "sugu", "meaning": "segera", "role": "time"}, {"jp": "シャワー", "reading": "shawaa", "meaning": "mandi", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "あびます", "reading": "abimasu", "meaning": "mengguyur/mandi", "role": "verb"}], "translation": "Nanti begitu sampai rumah, saya langsung mandi."}, {"tokens": [{"jp": "あした", "reading": "ashita", "meaning": "besok", "role": "time"}, {"jp": "あめ", "reading": "ame", "meaning": "hujan", "role": "noun"}, {"jp": "だったら", "reading": "dattara", "meaning": "kalau", "role": "connector"}, {"jp": "ピクニック", "reading": "pikunikku", "meaning": "piknik", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "ちゅうし", "reading": "chuushi", "meaning": "dibatalkan", "role": "predicate"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Kalau besok hujan, pikniknya dibatalkan."}], "forms": [{"label": "Kata Kerja (+)", "jp": "じかんがあったら", "reading": "jikan ga attara", "id": "kalau ada waktu"}, {"label": "Kata Kerja (-)", "jp": "こなかったら", "reading": "konakattara", "id": "kalau tidak datang"}, {"label": "Sifat-I", "jp": "むずかしかったら", "reading": "muzukashikattara", "id": "kalau sulit"}, {"label": "Nomina / Sifat-Na", "jp": "ひまだったら", "reading": "hima dattara", "id": "kalau senggang"}], "mistakes": [{"wrong": "とうきょうへ いくたら、れんらくします", "right": "とうきょうへ いったら、れんらくします", "why": "Bentuk-TA dari いく adalah いった (bukan いくた). Pastikan hafal perubahan lampau -ta yang benar sebelum menambah ら."}, {"wrong": "あめ な たら、いきません", "right": "あめ だったら、いきません", "why": "Kata benda & sifat-Na memakai bentuk lampau だった sebelum ら, bukan な."}], "quiz": [{"question": "Lengkapi: ''6じに ___、ばんごはんを たべましょう'' (Nanti kalau sudah jam 6 / menjadi jam 6, ayo makan malam; なる = menjadi):", "options": ["なるたら", "なったら", "なってたら", "なりたら"], "answer": 1, "why": "Bentuk-TA dari なる adalah なった, lalu ditambah ら menjadi なったら."}, {"question": "Apa arti kalimat ''おかねが あったら、にほんへ いきたいです''?", "options": ["Kemarin saya punya uang dan pergi ke Jepang", "Kalau saya punya uang, saya ingin pergi ke Jepang", "Karena tidak punya uang, saya tidak pergi", "Sebelum ke Jepang, siapkan uang"], "answer": 1, "why": "あった (lampau ada) + ら = ''kalau ada'' (syarat pengandaian)."}, {"question": "Manakah bentuk pengandaian negatif (''Kalau besok TIDAK turun hujan'') yang benar? (ふる = turun -> ふらない)", "options": ["ふらないら", "ふらなったら", "ふらなかったら", "ふりませんたら"], "answer": 2, "why": "Lampau negatif kasualnya adalah ふらなかった, ditambah ら menjadi ふらなかったら."}]}'::jsonb WHERE code = 'GP-JA-N4-008';
UPDATE grammar_points SET learning_guide = '{"analogy": "～ておきます itu artinya ''melakukan sesuatu LEBIH AWAL sebagai persiapan sebelum kejadian berikutnya'', atau ''membiarkan suatu keadaan tetap begitu apa adanya''. Mirip ungkapan Indonesia ''siapin dulu ya / biarin aja gitu dulu''.", "when_to_use": ["Menyiapkan materi rapat, memesan tiket pesawat, atau membeli bahan sebelum hari-H", "Membereskan alat atau menaruh dokumen di tempat semula seusai dipakai", "Membiarkan jendela terbuka atau AC menyala untuk orang berikutnya"], "formula_parts": [{"text": "Verba Bentuk-TE", "label": "Aksi persiapan (-て / -で)", "role": "verb"}, {"text": "おきます", "label": "Dilakukan siap-siap dulu", "role": "ending"}], "steps": ["Ubah aksi yang ingin dipersiapkan ke Bentuk-TE (contoh: かう → かって, しらべる → しらべて).", "Tambahkan おきます (bisa dikonjugasikan ke bentuk meminta: ～ておいてください = tolong disiapkan dulu).", "Dalam obrolan sehari-hari yang cepat, ～ておく sering melebur menjadi ～とく (しとく, かっとく)!"], "breakdowns": [{"tokens": [{"jp": "ホテル", "reading": "hoteru", "meaning": "hotel", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "よやくして", "reading": "yoyakushite", "meaning": "reservasi (TE)", "role": "verb"}, {"jp": "おきます", "reading": "okimasu", "meaning": "siapkan duluan", "role": "ending"}], "translation": "Saya reservasi hotelnya dulu (sebagai persiapan)."}, {"tokens": [{"jp": "かいぎ", "reading": "kaigi", "meaning": "rapat", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "まえ", "reading": "mae", "meaning": "sebelum", "role": "time"}, {"jp": "に", "reading": "ni", "meaning": "pada", "role": "particle"}, {"jp": "しりょう", "reading": "shiryou", "meaning": "materi dokumen", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "よんで", "reading": "yonde", "meaning": "baca (TE)", "role": "verb"}, {"jp": "おいてください", "reading": "oite kudasai", "meaning": "tolong siapkan dulu", "role": "ending"}], "translation": "Tolong baca dulu materinya sebelum rapat dimulai."}, {"tokens": [{"jp": "つぎ", "reading": "tsugi", "meaning": "berikutnya", "role": "noun"}, {"jp": "も", "reading": "mo", "meaning": "juga", "role": "particle"}, {"jp": "つかう", "reading": "tsukau", "meaning": "dipakai", "role": "verb"}, {"jp": "ので", "reading": "node", "meaning": "karena", "role": "connector"}, {"jp": "まど", "reading": "mado", "meaning": "jendela", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "あけて", "reading": "akete", "meaning": "buka (TE)", "role": "verb"}, {"jp": "おきましょう", "reading": "okimashou", "meaning": "biarkan dulu yuk", "role": "ending"}], "translation": "Karena nanti mau dipakai lagi, biarkan saja jendelanya tetap terbuka."}], "forms": [{"label": "Siap-siap (Formal)", "jp": "かっておきます", "reading": "katte okimasu", "id": "beli siap-siap dulu"}, {"label": "Minta Dikerjakan Dulu", "jp": "しらべておいてください", "reading": "shirabete oite kudasai", "id": "tolong cari tahu dulu"}, {"label": "Obrolan Lisan Singkat", "jp": "やっとくね", "reading": "yattoku ne", "id": "aku kerjain dulu ya! (santai)"}], "mistakes": [{"wrong": "よやくして います (saat berniat persiapan besok)", "right": "よやくして おきます", "why": "～ています artinya sedang melakukan sekarang atau status hasil; kalau maksudnya berjaga-jaga menyiapkan untuk nanti, pakai ～ておきます."}, {"wrong": "たべて あります", "right": "たべて おきます / ならべて あります", "why": "～ておきます dilakukan dengan sengaja sebagai persiapan oleh subjek (Saya menyiapkan), sedangkan ～てあります hanya menggambarkan keadaan benda."}], "quiz": [{"question": "Teman-teman akan datang makan malam di rumahmu nanti. Kalimat yang pas adalah:", "options": ["ビールを ひやして おきます", "ビールを ひやして いません", "ビールを ひやして みます", "ビールを ひやして しまいます"], "answer": 0, "why": "Dinginkan bir lebih dulu untuk persiapan menyambut tamu memakai ～ておきます."}, {"question": "Apa makna ucapan rekan kerja ''机の上は そのままで いいですよ。あとで かたづけておきますから''?", "options": ["Meja jangan disentuh selamanya", "Biarkan saja begitu di meja, nanti saya bereskan sebelum pulang", "Saya sudah membereskan meja kemarin", "Meja ini tidak bisa dibereskan"], "answer": 1, "why": "かたづけておきます menyatakan kesiapan menyelesaikan pemberesan sebelum ditinggal."}, {"question": "Di percakapan kasual antara teman dekat, ''かいて おく'' (menulis siap-siap dulu) sering terdengar disingkat menjadi:", "options": ["かいてく", "かいとく", "かいてる", "かいちゃう"], "answer": 1, "why": "て + おく dalam ucapan cepat sehari-hari sering melebur menjadi とく (kaitoku)."}]}'::jsonb WHERE code = 'GP-JA-N4-009';
UPDATE grammar_points SET learning_guide = '{"analogy": "Kenjougo (bahasa merendah) dipakai untuk ''menurunkan'' tindakan DIRI SENDIRI saat berbicara kepada atasan, klien, atau tamu terhormat — tujuannya meninggikan rasa hormat kepada lawan bicara. Ibaratnya kita berkata ''izinkan saya membantu membawakan...''.", "when_to_use": ["Melayani tamu atau pelanggan di toko/kantor (''mari saya antar'', ''biar saya bawakan tasnya'')", "Berbicara ke atasan atau klien dalam rapat & wawancara kerja", "Memperkenalkan diri atau menghubungi rekan bisnis eksternal"], "formula_parts": [{"text": "お / ご", "label": "Awalan hormat", "role": "particle"}, {"text": "Akar Verba / Kata Benda Aksi", "label": "Tindakan diri sendiri", "role": "verb"}, {"text": "します", "label": "Dengan rendah hati melakukan", "role": "ending"}], "steps": ["Pastikan pelakunya adalah DIRIMU SENDIRI (atau anggota perusahaanmu) yang berbuat sesuatu untuk lawan bicara.", "Untuk kata kerja asli Jepang (1–2 kanji): tempelkan お di depan akar masu, lalu tutup dengan します (misal: もちます → おもちします = biar saya bawakan).", "Untuk kata kerja gabungan kanji + します (seperti 案内します = mengantar, 説明します = menjelaskan): ganti menjadi ご案内します / ご説明します."], "breakdowns": [{"tokens": [{"jp": "おにもつ", "reading": "onimotsu", "meaning": "barang bawaan Anda", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "おもちします", "reading": "omochi shimasu", "meaning": "izinkan saya bawakan", "role": "verb"}], "translation": "Mari saya bawakan barang bawaan Anda."}, {"tokens": [{"jp": "かいぎしつ", "reading": "kaigishitsu", "meaning": "ruang rapat", "role": "place"}, {"jp": "へ", "reading": "e", "meaning": "ke", "role": "particle"}, {"jp": "ごあんないします", "reading": "goannai shimasu", "meaning": "mari saya antar (sopan)", "role": "verb"}], "translation": "Mari saya antarkan ke ruang rapat."}, {"tokens": [{"jp": "あした", "reading": "ashita", "meaning": "besok", "role": "time"}, {"jp": "また", "reading": "mata", "meaning": "lagi", "role": "time"}, {"jp": "おでんわ", "reading": "odenwa", "meaning": "telepon", "role": "object"}, {"jp": "いたします", "reading": "itashimasu", "meaning": "akan saya hubungi (sgt sopan)", "role": "verb"}], "translation": "Besok saya akan menelepon Anda kembali."}], "forms": [{"label": "Membantu Bawa", "jp": "おもちします", "reading": "omochi shimasu", "id": "mari saya bawakan"}, {"label": "Menjelaskan", "jp": "ごせつめいします", "reading": "gosetsumei shimasu", "id": "izinkan saya jelaskan"}, {"label": "Khusus: Pergi/Datang", "jp": "まいります", "reading": "mairimasu", "id": "saya pergi / datang (merendah)"}, {"label": "Khusus: Berkata", "jp": "もうします", "reading": "moushimasu", "id": "nama saya / saya sampaikan"}], "mistakes": [{"wrong": "しゃちょう、コーヒーを おのみしますか (nanya bos minum)", "right": "しゃちょう、コーヒーを めしあがりますか", "why": "Kenjougo (お～します) HANYA untuk tindakan DIRI SENDIRI, jangan dipakai ke tindakan atasan! Untuk atasan gunakan Sonkeigo (peninggi)."}, {"wrong": "おあんない します", "right": "ごあんない します", "why": "Kata serapan kanji berpasangan (案内, 連絡, 説明) memakai awalan ご (go-), bukan お (o-)."}], "quiz": [{"question": "Saat menyambut tamu yang ingin kamu tunjukkan jalan ke kantor, kamu sebagai resepsionis berkata:", "options": ["おまち になりますか", "ごあんない します", "あんないして あげます", "ごあんない なさいますか"], "answer": 1, "why": "Kamu (tuan rumah) merendahkan aksi sendiri mengantar tamu memakai ご + kata kerja します → ごあんないします."}, {"question": "Siapakah pelaku tindakan bila kita memakai pola Kenjougo お[Stem]します?", "options": ["Atasan atau pelanggan kita", "Pembicara (diri sendiri) / pihak internal kita", "Orang asing di jalan", "Benda mati"], "answer": 1, "why": "Kenjougo merendahkan tindakan diri sendiri (pembicara) demi menghormati lawan bicara."}, {"question": "Dalam perkenalan wawancara kerja resmi, cara super sopan mengganti ''わたしは アグスと いいます'' adalah:", "options": ["アグスと もうします", "アグスと おっしゃいます", "アグスに いらっしゃいます", "アグスを いただきます"], "answer": 0, "why": "Kata khusus Kenjougo dari いいます (berkata/bernama) adalah もうします."}]}'::jsonb WHERE code = 'GP-JA-N4-010';
UPDATE grammar_points SET learning_guide = '{"analogy": "は (dibaca wa) itu mirip kata ''kalau soal...'' atau ''adapun...'' di bahasa Indonesia. Tugasnya memberi tanda kepada pendengar tentang siapa atau apa yang sedang dibicarakan.", "when_to_use": ["Saat memperkenalkan nama, asal, atau pekerjaan diri sendiri", "Saat menunjuk benda dan menjelaskan benda apa itu", "Saat mendeskripsikan sifat atau keadaan suatu topik secara sopan"], "formula_parts": [{"text": "Topik / Subjek", "label": "Hal yang dibahas", "role": "topic"}, {"text": "は", "label": "Penanda topik (wa)", "role": "particle"}, {"text": "Predikat", "label": "Info / keterangan", "role": "predicate"}, {"text": "です", "label": "Akhiran sopan", "role": "ending"}], "steps": ["Tentukan siapa atau benda apa yang ingin kamu bahas di paling depan kalimat.", "Tempelkan partikel は (tulis ha, baca wa) tepat di belakang topik tersebut.", "Sebutkan keterangannya (profesi, nama, benda, sifat), lalu tutup dengan です agar terdengar sopan."], "breakdowns": [{"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "アグス", "reading": "Agusu", "meaning": "Agus", "role": "predicate"}, {"jp": "です", "reading": "desu", "meaning": "adalah (sopan)", "role": "ending"}], "translation": "Saya adalah Agus."}, {"tokens": [{"jp": "これ", "reading": "kore", "meaning": "ini", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "にほんご", "reading": "nihongo", "meaning": "bahasa Jepang", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "milik/tentang", "role": "particle"}, {"jp": "ほん", "reading": "hon", "meaning": "buku", "role": "predicate"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Ini adalah buku bahasa Jepang."}, {"tokens": [{"jp": "あした", "reading": "ashita", "meaning": "besok", "role": "time"}, {"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "やすみ", "reading": "yasumi", "meaning": "libur", "role": "predicate"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Besok saya libur."}], "forms": [{"label": "Positif", "jp": "がくせいです", "reading": "gakusei desu", "id": "adalah mahasiswa"}, {"label": "Negatif", "jp": "がくせいではありません", "reading": "gakusei dewa arimasen", "id": "bukan mahasiswa"}, {"label": "Tanya", "jp": "がくせいですか", "reading": "gakusei desu ka", "id": "apakah mahasiswa?"}], "mistakes": [{"wrong": "わたしわ アグスです", "right": "わたしは アグスです", "why": "Sebagai partikel topik, WA wajib ditulis dengan huruf Hiragana は (ha), bukan わ (wa)."}, {"wrong": "アグスは わたしです", "right": "わたしは アグスです", "why": "Hal yang paling jelas sebagai topik pembicaraan (''saya'') ditaruh di depan は, baru penjelasannya di belakang."}], "quiz": [{"question": "Lengkapi kalimat perkenalan: わたし ___ エンジニアです (Saya adalah insinyur).", "options": ["は", "を", "わ", "に"], "answer": 0, "why": "Penanda topik selalu ditulis は (dibaca wa), bukan わ."}, {"question": "Bagaimana cara melafalkan は dalam kalimat それは かぎです?", "options": ["ha", "wa", "wo", "ga"], "answer": 1, "why": "Bila berfungsi sebagai partikel topik, huruf は dibaca ''wa''."}, {"question": "Manakah kalimat sopan yang tepat untuk ''Ini adalah kamus''?", "options": ["これは じしょは です", "じしょは これ", "これは じしょです", "これわ じしょです"], "answer": 2, "why": "Topiknya これ, ditandai は, predikatnya じしょ, dan ditutup akhiran sopan です."}]}'::jsonb WHERE code = 'GP-JA-N5-001';
UPDATE grammar_points SET learning_guide = '{"analogy": "ではありませんでした itu seperti kata ''dulu bukan...'' atau ''kemarin tidak...'' versi sopan. Bagian akhir kalimat diubah untuk menunjukkan waktu yang sudah lewat.", "when_to_use": ["Saat membantah status atau jabatan di masa lalu (dulu bukan murid)", "Saat menjelaskan bahwa kemarin atau minggu lalu libur atau bukan hari kerja", "Saat menjawab pertanyaan masa lampau dengan sopan secara formal"], "formula_parts": [{"text": "Topik は", "label": "Hal yang dibahas", "role": "topic"}, {"text": "Kata Benda / Sifat-Na", "label": "Predikat awal", "role": "predicate"}, {"text": "ではありませんでした", "label": "Bukan (dulu / lampau)", "role": "ending"}], "steps": ["Tulis topik dan kata benda/sifat seperti kalimat biasa.", "Alih-alih です (sekarang) atau でした (lampau positif), pakai ではありませんでした di paling akhir.", "Dalam percakapan santai sehari-hari di kantor, ではありませんでした sering disingkat menjadi じゃありませんでした."], "breakdowns": [{"tokens": [{"jp": "きのう", "reading": "kinou", "meaning": "kemarin", "role": "time"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "やすみ", "reading": "yasumi", "meaning": "libur", "role": "predicate"}, {"jp": "ではありませんでした", "reading": "dewa arimasen deshita", "meaning": "bukan (lampau)", "role": "ending"}], "translation": "Kemarin bukan hari libur."}, {"tokens": [{"jp": "たなかさん", "reading": "Tanaka-san", "meaning": "Tuan Tanaka", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "いしゃ", "reading": "isha", "meaning": "dokter", "role": "predicate"}, {"jp": "じゃありませんでした", "reading": "ja arimasen deshita", "meaning": "dulu bukan", "role": "ending"}], "translation": "Tuan Tanaka dulu bukan dokter."}, {"tokens": [{"jp": "せんしゅう", "reading": "senshuu", "meaning": "minggu lalu", "role": "time"}, {"jp": "の", "reading": "no", "meaning": "(penghubung)", "role": "particle"}, {"jp": "テスト", "reading": "tesuto", "meaning": "ujian", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "かんたん", "reading": "kantan", "meaning": "mudah", "role": "adjective"}, {"jp": "ではありませんでした", "reading": "dewa arimasen deshita", "meaning": "tidak (lampau)", "role": "ending"}], "translation": "Ujian minggu lalu tidak mudah."}], "forms": [{"label": "Sekarang (+)", "jp": "やすみです", "reading": "yasumi desu", "id": "sekarang libur"}, {"label": "Lampau (+)", "jp": "やすみでした", "reading": "yasumi deshita", "id": "kemarin libur"}, {"label": "Sekarang (-)", "jp": "やすみではありません", "reading": "yasumi dewa arimasen", "id": "sekarang bukan libur"}, {"label": "Lampau (-)", "jp": "やすみではありませんでした", "reading": "yasumi dewa arimasen deshita", "id": "kemarin bukan libur"}], "mistakes": [{"wrong": "きのう やすみでした ではありません", "right": "きのうは やすみではありませんでした", "why": "Urutan ekornya harus negasi dulu (ではありません), baru penanda lampau (でした) menempel paling belakang."}, {"wrong": "おいしい ではありませんでした", "right": "おいしくありませんでした", "why": "ではありませんでした dipakai untuk kata benda & sifat-Na. Untuk sifat berakhiran -i (seperti oishii), pakai -ku arimasen deshita / -kunakatta desu."}], "quiz": [{"question": "Pilih bentuk yang tepat untuk ''Kemarin saya bukan guru (dulu bukan)'':", "options": ["せんせい でした", "せんせい ではありませんでした", "せんせい ではない", "せんせい ではありません"], "answer": 1, "why": "Untuk negasi masa lampau yang sopan, pakai ではありませんでした."}, {"question": "Apa versi percakapan lisan yang lebih ringan dari ではありませんでした?", "options": ["じゃありませんでした", "でしたじゃない", "ありませんでした", "じゃないでした"], "answer": 0, "why": "では dapat disingkat menjadi じゃ (ja) dalam percakapan biasa agar lebih luwes."}, {"question": "Kalimat mana yang menyatakan lampau positif (''Kemarin hujan'')?", "options": ["きのうは あめではありませんでした", "きのうは あめです", "きのうは あめでした", "きのうは あめではありません"], "answer": 2, "why": "Lampau positif kata benda cukup mengganti です dengan でした."}]}'::jsonb WHERE code = 'GP-JA-N5-002';
UPDATE grammar_points SET learning_guide = '{"analogy": "の itu mirip kata ''punya'' atau ''dari'', tapi URUTANNYA DIBALIK dibanding bahasa Indonesia! Pemilik atau penjelasnya ditaruh di DEPAN, sedangkan benda utamanya ditaruh di BELAKANG.", "when_to_use": ["Menyatakan kepemilikan barang (buku milik saya, tas milik Budi)", "Menyatakan afiliasi kantor/kampus/negara (mahasiswa Universitas Tokyo)", "Menjelaskan jenis atau isi benda (buku tentang bahasa Jepang, kunci mobil)"], "formula_parts": [{"text": "Kata Benda 1", "label": "Pemilik / Penjelas", "role": "noun"}, {"text": "の", "label": "Penghubung (no)", "role": "particle"}, {"text": "Kata Benda 2", "label": "Benda utama", "role": "noun"}], "steps": ["Siapkan dua kata benda: siapa pemilik/penjelasnya, dan apa benda intinya.", "Balik posisinya ala Jepang: taruh pemilik/penjelas di DEPAN.", "Sisipkan の di tengah, lalu taruh benda intinya di BELAKANG."], "breakdowns": [{"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "milik", "role": "particle"}, {"jp": "かばん", "reading": "kaban", "meaning": "tas", "role": "noun"}], "translation": "Tas saya (tas milik saya)"}, {"tokens": [{"jp": "これ", "reading": "kore", "meaning": "ini", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "さくらだいがく", "reading": "Sakura Daigaku", "meaning": "Univ. Sakura", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "dari", "role": "particle"}, {"jp": "パンフレット", "reading": "panfuretto", "meaning": "brosur", "role": "predicate"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Ini adalah brosur Universitas Sakura."}, {"tokens": [{"jp": "やまださん", "reading": "Yamada-san", "meaning": "Tuan Yamada", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "東京", "reading": "Toukyou", "meaning": "Tokyo", "role": "place"}, {"jp": "の", "reading": "no", "meaning": "asal/dari", "role": "particle"}, {"jp": "かいしゃいん", "reading": "kaishain", "meaning": "karyawan kantor", "role": "predicate"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Tuan Yamada adalah karyawan kantor dari Tokyo."}], "forms": [{"label": "Kepemilikan", "jp": "わたしのペン", "reading": "watashi no pen", "id": "pulpen saya"}, {"label": "Isi/Topik", "jp": "にほんごのほん", "reading": "nihongo no hon", "id": "buku bahasa Jepang"}, {"label": "Tanya Pemilik", "jp": "だれのペンですか", "reading": "dare no pen desu ka", "id": "pulpen milik siapa?"}], "mistakes": [{"wrong": "ほんのわたし", "right": "わたしのほん", "why": "Bukan urutan Indonesia (''buku saya''), dalam bahasa Jepang pemilik (watashi) harus sebelum の."}, {"wrong": "おおきいのくるま", "right": "おおきいくるま", "why": "の hanya menyambungkan dua KATA BENDA. Kata sifat-i (ookii) langsung menempel tanpa の."}], "quiz": [{"question": "Bagaimana cara mengatakan ''Kunci mobil'' dalam bahasa Jepang (くるま = mobil, かぎ = kunci)?", "options": ["かぎのくるま", "くるまのはかぎ", "くるまのかぎ", "かぎをくるま"], "answer": 2, "why": "Penjelas (くるま = mobil) ditaruh di depan, lalu の, lalu benda inti (かぎ = kunci)."}, {"question": "Pilih arti yang tepat untuk kalimat ''あれは わたし の くるま です'':", "options": ["Mobil itu milik dia", "Itu adalah mobil saya", "Saya punya banyak mobil", "Di mana mobil saya?"], "answer": 1, "why": "わたしのくるま berarti mobil milik saya."}, {"question": "Kalimat ''Ini milik siapa?'' dalam bahasa Jepang adalah:", "options": ["これは だれのですか", "だれは これですか", "これの だれですか", "だれを これですか"], "answer": 0, "why": "だれ (siapa) + の (milik) = punya siapa. Benda di belakang の boleh disingkat bila sudah jelas dari konteks."}]}'::jsonb WHERE code = 'GP-JA-N5-003';
UPDATE grammar_points SET learning_guide = '{"analogy": "を (dibaca o) itu seperti penunjuk ''sasaran aksi''. Kalau dalam bahasa Indonesia kita bilang ''makan nasi'', di Jepang objeknya disebut dulu lalu ditempeli を, baru kata kerjanya: ''nasi を makan''.", "when_to_use": ["Saat menyatakan aktivitas yang langsung mengenai benda (makan roti, minum teh)", "Saat membaca, menonton, membeli, atau menulis sesuatu", "Saat kalimat membutuhkan objek yang dikenai tindakan kata kerja"], "formula_parts": [{"text": "Objek", "label": "Benda sasaran aksi", "role": "object"}, {"text": "を", "label": "Penanda objek (o)", "role": "particle"}, {"text": "Kata Kerja", "label": "Aksi transitif", "role": "verb"}], "steps": ["Tentukan benda apa yang dikenai pekerjaan (misal: kopi, majalah, lagu).", "Tempelkan partikel を (huruf khusus wo, dibaca ''o'') tepat setelah benda itu.", "Tutup dengan kata kerjanya di bagian paling belakang kalimat."], "breakdowns": [{"tokens": [{"jp": "みず", "reading": "mizu", "meaning": "air", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "のみます", "reading": "nomimasu", "meaning": "minum", "role": "verb"}], "translation": "Minum air."}, {"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "あさごはん", "reading": "asagohan", "meaning": "sarapan", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "たべます", "reading": "tabemasu", "meaning": "makan", "role": "verb"}], "translation": "Saya makan sarapan."}, {"tokens": [{"jp": "まいばん", "reading": "maiban", "meaning": "setiap malam", "role": "time"}, {"jp": "にほんご", "reading": "nihongo", "meaning": "bahasa Jepang", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "べんきょうします", "reading": "benkyou shimasu", "meaning": "belajar", "role": "verb"}], "translation": "Setiap malam saya belajar bahasa Jepang."}], "forms": [{"label": "Sekarang", "jp": "パンをたべます", "reading": "pan o tabemasu", "id": "makan roti"}, {"label": "Negatif", "jp": "パンをたべません", "reading": "pan o tabemasen", "id": "tidak makan roti"}, {"label": "Lampau", "jp": "パンをたべました", "reading": "pan o tabemashita", "id": "sudah makan roti"}], "mistakes": [{"wrong": "コーヒーお のみます", "right": "コーヒーを のみます", "why": "Walau dibaca ''o'', sebagai partikel objek wajib ditulis pakai huruf を (bukan お)."}, {"wrong": "のみます コーヒーを", "right": "コーヒーを のみます", "why": "Dalam bahasa Jepang, kata kerja selalu berada di akhir kalimat, sesudah objek."}], "quiz": [{"question": "Pilih partikel yang tepat untuk kalimat ''Saya membaca koran'' (しんぶん = koran, よみます = membaca):", "options": ["は", "を", "の", "で"], "answer": 1, "why": "Koran (しんぶん) adalah benda yang langsung dibaca (objek), jadi ditandai dengan を."}, {"question": "Huruf Hiragana manakah yang khusus dipakai hanya sebagai partikel penanda objek?", "options": ["お", "を", "は", "へ"], "answer": 1, "why": "を hanya berfungsi sebagai partikel (dibaca o), berbeda dari お dalam kosakata biasa."}, {"question": "Susunan yang benar untuk ''Minum teh hijau (おちゃ)'' adalah:", "options": ["のみます おちゃを", "おちゃお のみます", "おちゃは のみます", "おちゃを のみます"], "answer": 3, "why": "Objek (おちゃ) + を + kata kerja (のみます)."}]}'::jsonb WHERE code = 'GP-JA-N5-004';
UPDATE grammar_points SET learning_guide = '{"analogy": "Partikel に / へ artinya sama persis dengan kata depan ''ke'' dalam bahasa Indonesia. Dipakai di belakang nama tempat sebelum kata kerja berpindah (pergi, datang, pulang).", "when_to_use": ["Menyatakan tujuan pergi ke kantor, sekolah, toko, atau Jepang", "Menyatakan datang ke rumah teman atau kantor", "Menyatakan pulang ke kampung halaman atau ke rumah"], "formula_parts": [{"text": "Tempat Tujuan", "label": "Lokasi yang dituju", "role": "place"}, {"text": "に / へ", "label": "Penanda arah (ni / e)", "role": "particle"}, {"text": "いきます・きます・かえります", "label": "Verba perpindahan", "role": "verb"}], "steps": ["Tentukan tempat tujuanmu (misal: stasiun, Jepang, rumah).", "Tambahkan に (fokus titik tujuan) atau へ (tulis ''he'', tapi wajib baca ''e'', fokus ke arahnya).", "Akhiri dengan kata kerja berpindah: いきます (pergi), きます (datang), atau かえります (pulang)."], "breakdowns": [{"tokens": [{"jp": "きょうと", "reading": "Kyouto", "meaning": "Kyoto", "role": "place"}, {"jp": "へ", "reading": "e", "meaning": "ke arah", "role": "particle"}, {"jp": "いきます", "reading": "ikimasu", "meaning": "pergi", "role": "verb"}], "translation": "Pergi ke Kyoto."}, {"tokens": [{"jp": "らいげつ", "reading": "raigetsu", "meaning": "bulan depan", "role": "time"}, {"jp": "にほん", "reading": "Nihon", "meaning": "Jepang", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "ke", "role": "particle"}, {"jp": "きます", "reading": "kimasu", "meaning": "datang", "role": "verb"}], "translation": "Bulan depan datang ke Jepang."}, {"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "うち", "reading": "uchi", "meaning": "rumah", "role": "place"}, {"jp": "へ", "reading": "e", "meaning": "ke", "role": "particle"}, {"jp": "かえります", "reading": "kaerimasu", "meaning": "pulang", "role": "verb"}], "translation": "Saya pulang ke rumah."}], "forms": [{"label": "Pergi", "jp": "がっこうへいきます", "reading": "gakkou e ikimasu", "id": "pergi ke sekolah"}, {"label": "Datang", "jp": "ここへきます", "reading": "koko e kimasu", "id": "datang ke sini"}, {"label": "Pulang", "jp": "くにへかえります", "reading": "kuni e kaerimasu", "id": "pulang ke negara asal"}], "mistakes": [{"wrong": "スーパーえ いきます", "right": "スーパーへ いきます", "why": "Partikel arah dibaca ''e'', tetapi penulisan Hiragananya wajib へ (bukan え)."}, {"wrong": "えきで いきます", "right": "えきに / へ いきます", "why": "で dipakai untuk alat transportasi atau tempat aktivitas di dalam lokasi, bukan untuk arah tujuan perpindahan."}], "quiz": [{"question": "Bagaimana bacaan huruf へ saat berada di kalimat にほんへ いきます?", "options": ["he", "e", "ni", "wa"], "answer": 1, "why": "Ketika menjadi partikel penunjuk arah, huruf へ dilafalkan sebagai ''e''."}, {"question": "Kalimat mana yang benar untuk ''Pergi ke perusahaan''?", "options": ["かいしゃを いきます", "かいしゃで いきます", "かいしゃに いきます", "かいしゃは いきます"], "answer": 2, "why": "Untuk tujuan perpindahan tempat dengan verba いきます, gunakan に atau へ."}, {"question": "Kata kerja apa yang cocok untuk kalimat ''うちへ ___'' saat pulang ke rumah?", "options": ["かえります", "のみます", "よみます", "あります"], "answer": 0, "why": "かえります berarti pulang (ke rumah atau negara asal)."}]}'::jsonb WHERE code = 'GP-JA-N5-005';
UPDATE grammar_points SET learning_guide = '{"analogy": "Akhiran ～ます itu seperti tanda kalimat sopan untuk kata kerja (kegiatan rutin atau rencana), sedangkan mengubahnya ke ～ません artinya menambahkan kata ''tidak''.", "when_to_use": ["Menceritakan kebiasaan harian (setiap hari bangun jam 6, makan pagi)", "Menyatakan rencana kegiatan hari ini atau besok secara sopan", "Menolak atau menyatakan tidak melakukan kegiatan tertentu"], "formula_parts": [{"text": "Akar Kata Kerja", "label": "Inti aksi", "role": "verb"}, {"text": "ます / ません", "label": "Positif / Tidak (sopan)", "role": "ending"}], "steps": ["Ambil akar kata kerja bentuk sopan (misal: tabe-, nomi-, yomi-).", "Tambahkan ～ます untuk arti positif (''melakukan / akan melakukan'').", "Ganti menjadi ～ません untuk arti negatif (''tidak melakukan / tidak akan melakukan'')."], "breakdowns": [{"tokens": [{"jp": "あさ", "reading": "asa", "meaning": "pagi", "role": "time"}, {"jp": "おきます", "reading": "okimasu", "meaning": "bangun", "role": "verb"}], "translation": "Bangun di pagi hari."}, {"tokens": [{"jp": "さけ", "reading": "sake", "meaning": "alkohol/sake", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "のみません", "reading": "nomimasen", "meaning": "tidak minum", "role": "verb"}], "translation": "Saya tidak minum alkohol."}, {"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "まいにち", "reading": "mainichi", "meaning": "setiap hari", "role": "time"}, {"jp": "テレビ", "reading": "terebi", "meaning": "TV", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "みます", "reading": "mimasu", "meaning": "menonton", "role": "verb"}], "translation": "Setiap hari saya menonton TV."}], "forms": [{"label": "Positif", "jp": "ねます", "reading": "nemasu", "id": "tidur"}, {"label": "Negatif", "jp": "ねません", "reading": "nemasen", "id": "tidak tidur"}, {"label": "Lampau (+)", "jp": "ねました", "reading": "nemashita", "id": "sudah tidur"}, {"label": "Lampau (-)", "jp": "ねませんでした", "reading": "nemasen deshita", "id": "kemarin tidak tidur"}], "mistakes": [{"wrong": "たべます ありません", "right": "たべません", "why": "Kata kerja tidak dinegasikan dengan ありません, cukup ubah akhiran ます menjadi ません."}, {"wrong": "あした たべます でした", "right": "あした たべます", "why": "Bentuk ます sudah mencakup masa depan (''akan makan''); tidak ada bentuk です atau でした di belakang ます."}], "quiz": [{"question": "Bagaimana bentuk negatif sopan dari よみます (membaca)?", "options": ["よみません", "よみではない", "よむません", "よみました"], "answer": 0, "why": "Akhiran ます langsung diganti menjadi ません untuk bentuk negatif sopan."}, {"question": "Kalimat mana yang menyatakan ''Kemarin tidak menonton TV''?", "options": ["きのう テレビを みません", "きのう テレビを みました", "きのう テレビを みませんでした", "きのう テレビを みます"], "answer": 2, "why": "Negasi lampau sopan kata kerja adalah ～ませんでした."}, {"question": "Kapan bentuk positif ～ます digunakan?", "options": ["Hanya untuk kejadian kemarin", "Untuk kebiasaan sekarang & rencana masa depan", "Khusus kalimat perintah saja", "Hanya dengan kata benda"], "answer": 1, "why": "Bentuk ～ます berfungsi untuk kebiasaan masa kini maupun rencana yang akan datang."}]}'::jsonb WHERE code = 'GP-JA-N5-006';
UPDATE grammar_points SET learning_guide = '{"analogy": "Partikel で punya dua arti praktis dalam bahasa Indonesia: ''naik/memakai ...'' (sarana/alat) dan ''di ...'' khusus ketika ada aktivitas yang dilakukan di tempat itu.", "when_to_use": ["Naik kendaraan menuju suatu tempat (naik kereta, naik bus, jalan kaki)", "Memakai alat atau bahasa saat beraktivitas (makan pakai sumpit, bicara pakai bahasa Jepang)", "Menyebut lokasi tempat terjadinya aktivitas (makan di restoran, belajar di perpustakaan)"], "formula_parts": [{"text": "Alat / Lokasi Aksi", "label": "Sarana atau tempat aktif", "role": "place"}, {"text": "で", "label": "Dengan / Di (de)", "role": "particle"}, {"text": "Kata Kerja Aksi", "label": "Kegiatan berlangsung", "role": "verb"}], "steps": ["Bedakan peran: apakah benda itu sarana/alat, atau tempat aktivitas aktif?", "Taruh sarana/alat atau tempat aktivitas di depan, lalu tempelkan で.", "Tambahkan objek (jika ada) dan akhiri dengan kata kerja."], "breakdowns": [{"tokens": [{"jp": "でんしゃ", "reading": "densha", "meaning": "kereta listrik", "role": "noun"}, {"jp": "で", "reading": "de", "meaning": "naik / dengan", "role": "particle"}, {"jp": "いきます", "reading": "ikimasu", "meaning": "pergi", "role": "verb"}], "translation": "Pergi naik kereta."}, {"tokens": [{"jp": "はし", "reading": "hashi", "meaning": "sumpit", "role": "noun"}, {"jp": "で", "reading": "de", "meaning": "memakai", "role": "particle"}, {"jp": "ごはん", "reading": "gohan", "meaning": "nasi", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "たべます", "reading": "tabemasu", "meaning": "makan", "role": "verb"}], "translation": "Makan nasi memakai sumpit."}, {"tokens": [{"jp": "としょかん", "reading": "toshokan", "meaning": "perpustakaan", "role": "place"}, {"jp": "で", "reading": "de", "meaning": "di (tempat aksi)", "role": "particle"}, {"jp": "ともだち", "reading": "tomodachi", "meaning": "teman", "role": "noun"}, {"jp": "と", "reading": "to", "meaning": "bersama", "role": "particle"}, {"jp": "べんきょうします", "reading": "benkyou shimasu", "meaning": "belajar", "role": "verb"}], "translation": "Belajar bersama teman di perpustakaan."}], "forms": [{"label": "Transportasi", "jp": "バスでいきます", "reading": "basu de ikimasu", "id": "pergi naik bus"}, {"label": "Bahasa / Alat", "jp": "にほんごではなします", "reading": "nihongo de hanashimasu", "id": "berbicara dalam bahasa Jepang"}, {"label": "Lokasi Aksi", "jp": "カフェでのみます", "reading": "kafe de nomimasu", "id": "minum di kafe"}], "mistakes": [{"wrong": "あるいてで いきます", "right": "あるいて いきます", "why": "Jalan kaki (aruite) adalah bentuk kata kerja, jadi tidak perlu ditempeli partikel で."}, {"wrong": "へやで あります", "right": "へやに あります", "why": "あります/います (keberadaan diam) memakai に, bukan で. Partikel で khusus untuk lokasi tindakan aktif."}], "quiz": [{"question": "Partikel yang tepat untuk ''Makan roti di kafetaria (しょくどう)'' adalah:", "options": ["に", "を", "で", "へ"], "answer": 2, "why": "Kafetaria adalah tempat berlangsungnya kegiatan aktif (makan), jadi pakai で."}, {"question": "Bagaimana mengatakan ''Menulis surat dengan pulpen (ペン)''?", "options": ["ペンに てがみを かきます", "ペンで てがみを かきます", "ペンを てがみを かきます", "ペンは てがみを かきます"], "answer": 1, "why": "Pulpen adalah alat untuk menulis, sehingga ditandai dengan で."}, {"question": "Manakah kalimat tentang perjalanan kaki yang alami?", "options": ["あるいてで かえります", "あるいてをかえります", "あるいて かえります", "あるくで かえります"], "answer": 2, "why": "Pengecualian penting: ''berjalan kaki'' adalah あるいて (tanpa で)."}]}'::jsonb WHERE code = 'GP-JA-N5-007';
UPDATE grammar_points SET learning_guide = '{"analogy": "Partikel に di depan waktu mirip seperti kata ''pada pukul...'' atau ''di hari...'' ketika jadwalnya berupa titik angka jam atau nama hari spesifik.", "when_to_use": ["Menyebut jam bangun tidur, mulai kerja, atau jadwal kereta", "Menyebut tanggal, bulan, atau hari spesifik dilakukannya janji", "Menjelaskan rentang atau titik kapan suatu pertemuan dimulai"], "formula_parts": [{"text": "Titik Waktu", "label": "Jam / Tanggal / Hari", "role": "time"}, {"text": "に", "label": "Pada (ni)", "role": "particle"}, {"text": "Kata Kerja", "label": "Kegiatan sesuai jadwal", "role": "verb"}], "steps": ["Cek dulu apakah waktunya punya angka jam, tanggal, atau nama hari.", "Jika iya (seperti ろくじ = jam 6, にちようび = hari Minggu), tempelkan に.", "Jika waktunya relatif tanpa angka (きょう = hari ini, まいにち = setiap hari, きのう = kemarin), JANGAN pakai に."], "breakdowns": [{"tokens": [{"jp": "ろくじ", "reading": "rokuji", "meaning": "jam 6", "role": "time"}, {"jp": "に", "reading": "ni", "meaning": "pada", "role": "particle"}, {"jp": "おきます", "reading": "okimasu", "meaning": "bangun", "role": "verb"}], "translation": "Bangun pada jam 6."}, {"tokens": [{"jp": "まいあさ", "reading": "maiasa", "meaning": "setiap pagi", "role": "time"}, {"jp": "はちじはん", "reading": "hachijihan", "meaning": "jam 8.30", "role": "time"}, {"jp": "に", "reading": "ni", "meaning": "pada", "role": "particle"}, {"jp": "いえ", "reading": "ie", "meaning": "rumah", "role": "place"}, {"jp": "を", "reading": "o", "meaning": "dari (keluar)", "role": "particle"}, {"jp": "でます", "reading": "demasu", "meaning": "keluar/berangkat", "role": "verb"}], "translation": "Setiap pagi berangkat dari rumah pukul 8.30."}, {"tokens": [{"jp": "にちようび", "reading": "nichiyoubi", "meaning": "hari Minggu", "role": "time"}, {"jp": "に", "reading": "ni", "meaning": "pada", "role": "particle"}, {"jp": "ともだち", "reading": "tomodachi", "meaning": "teman", "role": "noun"}, {"jp": "に", "reading": "ni", "meaning": "dengan (bertemu)", "role": "particle"}, {"jp": "あいます", "reading": "aimasu", "meaning": "bertemu", "role": "verb"}], "translation": "Pada hari Minggu bertemu teman."}], "forms": [{"label": "Pakai に (Jam)", "jp": "くじにねます", "reading": "kuji ni nemasu", "id": "tidur jam 9"}, {"label": "Pakai に (Tanggal)", "jp": "よっかにいきます", "reading": "yokka ni ikimasu", "id": "pergi tanggal 4"}, {"label": "Tanpa に (Relatif)", "jp": "あしたいきます", "reading": "ashita ikimasu", "id": "besok pergi (tanpa に)"}], "mistakes": [{"wrong": "きょうに べんきょうします", "right": "きょう べんきょうします", "why": "Kata waktu relatif seperti きょう (hari ini), あした (besok), きのう (kemarin), まいにち (setiap hari) tidak pernah memakai partikel に."}, {"wrong": "なんじで おきますか", "right": "なんじに おきますか", "why": "Untuk menanyakan titik jam, partikelnya adalah に (nanji ni), bukan で."}], "quiz": [{"question": "Kalimat mana yang BENAR penggunaan partikel waktunya?", "options": ["まいにちに にほんごを べんきょうします", "あしたに とうきょうへ いきます", "しちじに あさごはんを たべます", "きのうに ともだちと あそびました"], "answer": 2, "why": "しちじ (jam 7) adalah titik angka jam spesifik, sehingga wajib pakai に."}, {"question": "Lengkapi: ''らいしゅう ___ テストが あります'' (Minggu depan ada ujian).", "options": ["に", "(tidak perlu partikel)", "で", "を"], "answer": 1, "why": "らいしゅう (minggu depan) bersifat relatif terhadap pembicara, tidak memakai に."}, {"question": "Cara menanyakan ''Jam berapa kamu tidur?'' dengan sopan adalah:", "options": ["なんじに ねますか", "なんじで ねますか", "いつに ねますか", "なんじを ねますか"], "answer": 0, "why": "なんじ (jam berapa) adalah kata tanya titik jam, sehingga diikuti に."}]}'::jsonb WHERE code = 'GP-JA-N5-008';
UPDATE grammar_points SET learning_guide = '{"analogy": "Di bahasa Indonesia kita cukup bilang ''ada'', tapi di Jepang dibedakan: あります (arimasu) untuk benda mati & tumbuhan yang diam, sedangkan います (imasu) khusus manusia & hewan yang bisa bergerak sendiri.", "when_to_use": ["Menyebut benda apa yang ada di atas meja atau di dalam kamar", "Menyebut apakah seseorang atau hewan peliharaan sedang berada di suatu tempat", "Menanyakan letak fasilitas umum (toilet, ATM, stasiun) atau keberadaan keluarga"], "formula_parts": [{"text": "Tempat", "label": "Lokasi keberadaan", "role": "place"}, {"text": "に", "label": "Di (khusus diam)", "role": "particle"}, {"text": "Benda / Makhluk", "label": "Yang ada di sana", "role": "subject"}, {"text": "が", "label": "Penanda subjek", "role": "particle"}, {"text": "あります / います", "label": "Ada (mati / hidup)", "role": "verb"}], "steps": ["Sebutkan lokasinya dulu diikuti partikel に (bukan で).", "Sebutkan benda atau makhluk yang ada, lalu tempelkan partikel が.", "Pilih kata kerja penutupnya: あります untuk benda mati/acara/waktu, atau います untuk manusia/hewan."], "breakdowns": [{"tokens": [{"jp": "へや", "reading": "heya", "meaning": "kamar", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "di", "role": "particle"}, {"jp": "いす", "reading": "isu", "meaning": "kursi", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "あります", "reading": "arimasu", "meaning": "ada (benda mati)", "role": "verb"}], "translation": "Di kamar ada kursi."}, {"tokens": [{"jp": "にわ", "reading": "niwa", "meaning": "halaman", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "di", "role": "particle"}, {"jp": "ねこ", "reading": "neko", "meaning": "kucing", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "います", "reading": "imasu", "meaning": "ada (hewan)", "role": "verb"}], "translation": "Di halaman ada kucing."}, {"tokens": [{"jp": "つくえ", "reading": "tsukue", "meaning": "meja", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "うえ", "reading": "ue", "meaning": "atas", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "di", "role": "particle"}, {"jp": "ほん", "reading": "hon", "meaning": "buku", "role": "subject"}, {"jp": "と", "reading": "to", "meaning": "dan", "role": "particle"}, {"jp": "かぎ", "reading": "kagi", "meaning": "kunci", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "あります", "reading": "arimasu", "meaning": "ada", "role": "verb"}], "translation": "Di atas meja ada buku dan kunci."}], "forms": [{"label": "Benda (+)", "jp": "じかんがあります", "reading": "jikan ga arimasu", "id": "ada waktu / sempat"}, {"label": "Benda (-)", "jp": "じかんがありません", "reading": "jikan ga arimasen", "id": "tidak ada waktu"}, {"label": "Orang (+)", "jp": "きょうだいがいます", "reading": "kyoudai ga imasu", "id": "punya saudara"}, {"label": "Orang (-)", "jp": "だれもいません", "reading": "dare mo imasen", "id": "tidak ada siapa-siapa"}], "mistakes": [{"wrong": "こうえんに いぬが あります", "right": "こうえんに いぬが います", "why": "Anjing adalah makhluk hidup bernyawa, jadi wajib memakai います, bukan あります."}, {"wrong": "きょうしつで せんせいが います", "right": "きょうしつに せんせいが います", "why": "Untuk sekadar menyatakan ''berada di tempat'', gunakan に. Partikel で hanya dipakai jika ada tindakan aktif (seperti mengajar)."}], "quiz": [{"question": "Lengkapi: ''じむしょに たなかさんが ___'' (Di kantor ada Pak Tanaka).", "options": ["あります", "います", "です", "します"], "answer": 1, "why": "Pak Tanaka adalah manusia (makhluk hidup), jadi wajib memakai います."}, {"question": "Bunga atau pohon di taman memakai verba yang mana?", "options": ["います", "あります", "いきます", "します"], "answer": 1, "why": "Tumbuhan yang tidak berpindah tempat sendiri dihitung benda non-animasi dan memakai あります."}, {"question": "Bagaimana mengatakan ''Tidak ada uang'' dengan sopan?", "options": ["おかねが ありません", "おかねが いません", "おかねではありません", "おかねが なしです"], "answer": 0, "why": "Bentuk negatif dari あります adalah ありません."}]}'::jsonb WHERE code = 'GP-JA-N5-009';
UPDATE grammar_points SET learning_guide = '{"analogy": "と berarti ''dan'' untuk menyebutkan SEMUA barang yang ada (daftar lengkap, habis tidak ada sisanya). Sedangkan や (...など) artinya ''...dan lain-lain'' (hanya ambil 2–3 contoh perwakilan saja).", "when_to_use": ["Menyebut semua isi tas tanpa ada yang terlewat (pakai と)", "Menyebut beberapa contoh makanan kesukaan atau barang di toko dari banyak pilihan (pakai や...など)", "Memesan lebih dari satu item menu sekaligus"], "formula_parts": [{"text": "Benda A", "label": "Item pertama", "role": "noun"}, {"text": "と / や", "label": "Dan (lengkap) / Antara lain", "role": "particle"}, {"text": "Benda B", "label": "Item kedua", "role": "noun"}, {"text": "(など)", "label": "Dan lain-lain (opsional dgn や)", "role": "ending"}], "steps": ["Tentukan apakah daftarnya sudah komplet 100% atau hanya contoh saja.", "Kalau komplet (cuma dua itu saja), sambungkan dengan と.", "Kalau cuma sebut beberapa contoh dari banyak hal, sambungkan dengan や lalu tutup dengan など sebelum partikel berikutnya."], "breakdowns": [{"tokens": [{"jp": "つくえ", "reading": "tsukue", "meaning": "meja", "role": "place"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "うえ", "reading": "ue", "meaning": "atas", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "di", "role": "particle"}, {"jp": "ほん", "reading": "hon", "meaning": "buku", "role": "subject"}, {"jp": "と", "reading": "to", "meaning": "dan (lengkap)", "role": "particle"}, {"jp": "ペン", "reading": "pen", "meaning": "pulpen", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "あります", "reading": "arimasu", "meaning": "ada", "role": "verb"}], "translation": "Di atas meja hanya ada buku dan pulpen."}, {"tokens": [{"jp": "スーパー", "reading": "suupaa", "meaning": "supermarket", "role": "place"}, {"jp": "で", "reading": "de", "meaning": "di", "role": "particle"}, {"jp": "パン", "reading": "pan", "meaning": "roti", "role": "object"}, {"jp": "や", "reading": "ya", "meaning": "seperti... dan", "role": "particle"}, {"jp": "たまご", "reading": "tamago", "meaning": "telur", "role": "object"}, {"jp": "など", "reading": "nado", "meaning": "dll.", "role": "ending"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "かいました", "reading": "kaimashita", "meaning": "membeli", "role": "verb"}], "translation": "Saya membeli roti, telur, dan lain-lain di supermarket."}, {"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "の", "reading": "no", "meaning": "milik", "role": "particle"}, {"jp": "まち", "reading": "machi", "meaning": "kota", "role": "noun"}, {"jp": "には", "reading": "ni wa", "meaning": "di dalamnya", "role": "particle"}, {"jp": "こうえん", "reading": "kouen", "meaning": "taman", "role": "subject"}, {"jp": "や", "reading": "ya", "meaning": "antara lain", "role": "particle"}, {"jp": "びじゅつかん", "reading": "bijutsukan", "meaning": "museum seni", "role": "subject"}, {"jp": "など", "reading": "nado", "meaning": "dll.", "role": "ending"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "あります", "reading": "arimasu", "meaning": "ada", "role": "verb"}], "translation": "Di kota saya ada taman, museum seni, dan lain sebagainya."}], "forms": [{"label": "Daftar Penuh (と)", "jp": "コーヒーとこうちゃ", "reading": "koohii to koucha", "id": "kopi dan teh (hanya 2 itu)"}, {"label": "Contoh (や～など)", "jp": "コーヒーやこうちゃなど", "reading": "koohii ya koucha nado", "id": "kopi, teh, dan lain-lain"}], "mistakes": [{"wrong": "おおきいと きれいです", "right": "おおきくて きれいです", "why": "と hanya menyambungkan KATA BENDA, tidak boleh menyambung dua kata sifat atau dua kalimat."}, {"wrong": "りんごと みかん など を たべました", "right": "りんごや みかん など を たべました", "why": "Pasangan alami kata など (''dan lain-lain'') adalah や, bukan と."}], "quiz": [{"question": "Kalau di kotak pensil hanya ada tepat 2 benda (pensil & penghapus), partikel penyambungnya adalah:", "options": ["や", "と", "か", "の"], "answer": 1, "why": "と digunakan ketika daftar benda yang disebut lengkap tidak ada tambahannya."}, {"question": "Manakah kalimat yang paling alami untuk ''Di kulkas ada susu, keju, apel, dan masih banyak lagi''?", "options": ["れいぞうこに ぎゅうにゅうと チーズと りんご だけ あります", "れいぞうこに ぎゅうにゅうを チーズが あります", "れいぞうこに ぎゅうにゅうや チーズなど が あります", "れいぞうこに ぎゅうにゅうの チーズなど あります"], "answer": 2, "why": "Untuk menyebutkan sebagian contoh dari banyak benda, pakai [A] や [B] など."}, {"question": "Bisakah partikel と dipakai menyambung dua kata kerja (misal: ''makan と minum'')?", "options": ["Bisa kalau formal", "Bisa kalau di akhir kalimat", "Hanya saat lampau", "Tidak bisa, と khusus menyambung kata benda"], "answer": 3, "why": "と penyambung daftar hanya boleh dipakai di antara kata benda (untuk kata kerja nanti pakai bentuk-TE)."}]}'::jsonb WHERE code = 'GP-JA-N5-010';
UPDATE grammar_points SET learning_guide = '{"analogy": "Kata sifat berakhiran huruf ''i'' (seperti takai = mahal, samui = dingin) punya cara unik untuk bilang ''tidak'' atau ''kemarin'': buang huruf い paling belakang, lalu tukar dengan ekor baru (くない / かった).", "when_to_use": ["Menilai rasa makanan, cuaca, harga barang, atau ukuran benda", "Menyangkal sifat sesuatu (''tidak mahal'', ''tidak enak'')", "Menceritakan pengalaman yang sudah berlalu (''kemarin panas'', ''liburan kemarin menyenangkan'')"], "formula_parts": [{"text": "Akar Sifat-い", "label": "Buang huruf い akhir", "role": "adjective"}, {"text": "くないです / かったです", "label": "Tidak ... / Dulu ...", "role": "ending"}], "steps": ["Ambil kata sifat-i dan lepaskan huruf い paling belakang (misal: たかい → たか).", "Untuk bilang ''tidak...'', tempelkan ～くないです (misal: たかくないです).", "Untuk bilang ''dulu/kemarin...'', tempelkan ～かったです (misal: たかかったです). Ingat 1 pengecualian: いい (bagus) akarnya berubah jadi よ (よくないです / よかったです)."], "breakdowns": [{"tokens": [{"jp": "この", "reading": "kono", "meaning": "ini", "role": "noun"}, {"jp": "かばん", "reading": "kaban", "meaning": "tas", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "たかくないです", "reading": "takakunai desu", "meaning": "tidak mahal", "role": "adjective"}], "translation": "Tas ini tidak mahal."}, {"tokens": [{"jp": "きのう", "reading": "kinou", "meaning": "kemarin", "role": "time"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "てんき", "reading": "tenki", "meaning": "cuaca", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "とても", "reading": "totemo", "meaning": "sangat", "role": "adjective"}, {"jp": "よかったです", "reading": "yokatta desu", "meaning": "bagus (lampau)", "role": "adjective"}], "translation": "Cuaca kemarin sangat bagus."}, {"tokens": [{"jp": "きょうと", "reading": "Kyouto", "meaning": "Kyoto", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "あたらしい", "reading": "atarashii", "meaning": "baru", "role": "adjective"}, {"jp": "まち", "reading": "machi", "meaning": "kota", "role": "predicate"}, {"jp": "ではありませんが", "reading": "dewa arimasen ga", "meaning": "bukan tapi", "role": "connector"}, {"jp": "おもしろかったです", "reading": "omoshirokatta desu", "meaning": "menarik (lampau)", "role": "adjective"}], "translation": "Kyoto memang bukan kota baru, tapi sangat menarik."}], "forms": [{"label": "Positif", "jp": "さむいです", "reading": "samui desu", "id": "dingin"}, {"label": "Negatif", "jp": "さむくないです", "reading": "samukunai desu", "id": "tidak dingin"}, {"label": "Lampau (+)", "jp": "さむかったです", "reading": "samukatta desu", "id": "kemarin dingin"}, {"label": "Lampau (-)", "jp": "さむくなかったです", "reading": "samukunakatta desu", "id": "kemarin tidak dingin"}], "mistakes": [{"wrong": "たかい ではありません", "right": "たかくないです", "why": "Kata sifat-i tidak memakai ではありません, melainkan mengubah akhiran い menjadi くないです."}, {"wrong": "いくないです / いきません (untuk いい)", "right": "よくないです", "why": "Kata sifat いい (bagus/baik) bentuk dasarnya adalah よい, jadi saat berubah wajib memakai akar よ- → よくないです."}], "quiz": [{"question": "Bagaimana mengubah おいしい (enak) menjadi ''tidak enak''?", "options": ["おいしい ではありません", "おいしくないです", "おいしいくないです", "おいしではないです"], "answer": 1, "why": "Buang い paling belakang dari おいしい lalu ganti dengan くないです."}, {"question": "Bentuk negatif dari いい (bagus/baik) adalah:", "options": ["いくないです", "いいくないです", "よくないです", "いいではありません"], "answer": 2, "why": "いい berubah akarnya menjadi よ- saat dikonjugasikan: よくないです."}, {"question": "Untuk mengatakan ''Kemarin sangat panas (あつい)'', pilih bentuk yang tepat:", "options": ["きのうは とても あついでした", "きのうは とても あつくです", "きのうは とても あついかったです", "きのうは とても あつかったです"], "answer": 3, "why": "Buang い dari あつい menjadi あつ, lalu tambah かったです."}]}'::jsonb WHERE code = 'GP-JA-N5-011';
UPDATE grammar_points SET learning_guide = '{"analogy": "Kata sifat-Na (seperti kirei = cantik, shizuka = tenang) sifatnya persis seperti kata benda: kalau digabung ke benda di depannya minta bantuan ''な'', dan kalau negatif memakai ''ではありません''. Sementara より artinya ''lebih... daripada...''.", "when_to_use": ["Mendeskripsikan suasana tempat atau sifat orang dengan kata sifat-Na (terkenal, praktis, ramai)", "Membandingkan dua hal: mana yang lebih murah, lebih jauh, atau lebih enak", "Menyebutkan yang ''paling...'' di antara satu kategori (いちばん)"], "formula_parts": [{"text": "A は", "label": "Yang dinilai", "role": "topic"}, {"text": "B より", "label": "Daripada B", "role": "connector"}, {"text": "Kata Sifat (+ な + Benda)", "label": "Sifat pembanding", "role": "adjective"}, {"text": "です", "label": "(Sopan)", "role": "ending"}], "steps": ["Untuk menerangkan kata benda dengan sifat-Na, sisipkan な di antara keduanya (しずかな まち = kota tenang). Hati-hati: きれい (cantik) dan ゆうめい (terkenal) ikut golongan Na meski berakhiran bunyi ''i''!", "Untuk membandingkan dua hal: sebutkan A は B より [Sifat] です (''A lebih [Sifat] daripada B'').", "Untuk menyebut ''paling...'': pakai [Kategori] の なかで [A] が いちばん [Sifat] です."], "breakdowns": [{"tokens": [{"jp": "ここ", "reading": "koko", "meaning": "sini", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "しずかな", "reading": "shizuka na", "meaning": "yang tenang", "role": "adjective"}, {"jp": "まち", "reading": "machi", "meaning": "kota", "role": "predicate"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Di sini adalah kota yang tenang."}, {"tokens": [{"jp": "しんかんせん", "reading": "Shinkansen", "meaning": "kereta cepat", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "バス", "reading": "basu", "meaning": "bus", "role": "noun"}, {"jp": "より", "reading": "yori", "meaning": "daripada", "role": "connector"}, {"jp": "はやい", "reading": "hayai", "meaning": "lebih cepat", "role": "adjective"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Shinkansen lebih cepat daripada bus."}, {"tokens": [{"jp": "スポーツ", "reading": "supootsu", "meaning": "olahraga", "role": "noun"}, {"jp": "の", "reading": "no", "meaning": "di", "role": "particle"}, {"jp": "なかで", "reading": "naka de", "meaning": "antara", "role": "connector"}, {"jp": "サッカー", "reading": "sakkaa", "meaning": "sepak bola", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "いちばん", "reading": "ichiban", "meaning": "paling", "role": "adjective"}, {"jp": "すき", "reading": "suki", "meaning": "disukai", "role": "adjective"}, {"jp": "です", "reading": "desu", "meaning": "(sopan)", "role": "ending"}], "translation": "Di antara olahraga, saya paling suka sepak bola."}], "forms": [{"label": "Menerangkan Benda", "jp": "ゆうめいな おてら", "reading": "yuumei na otera", "id": "kuil yang terkenal"}, {"label": "Negatif Sifat-Na", "jp": "ひまでは ありません", "reading": "hima dewa arimasen", "id": "tidak senggang"}, {"label": "Perbandingan", "jp": "東京より おおきいです", "reading": "Toukyou yori ookii desu", "id": "lebih besar dari Tokyo"}], "mistakes": [{"wrong": "きれいの はな / きれくない", "right": "きれいな はな / きれいではありません", "why": "きれい (indah/bersih) adalah pengecualian terkenal: ia kata sifat-Na, bukan sifat-I!"}, {"wrong": "しずか です な", "right": "しずか です", "why": "Huruf な hanya dipakai jika langsung menempel di depan kata benda. Di depan です, な dihilangkan."}], "quiz": [{"question": "Pilih frasa yang benar untuk ''Orang yang terkenal'' (ゆうめい = terkenal, ひと = orang):", "options": ["ゆうめい ひと", "ゆうめいの ひと", "ゆうめいな ひと", "ゆうめいく ひと"], "answer": 2, "why": "ゆうめい adalah kata sifat-Na; bila menerangkan kata benda di belakangnya wajib menyisipkan な."}, {"question": "Apa arti kalimat ''きのうは きょうより すずしかったです''?", "options": ["Hari ini lebih sejuk dari kemarin", "Kemarin lebih sejuk daripada hari ini", "Kemarin dan hari ini sama sejuknya", "Kemarin tidak terlalu sejuk"], "answer": 1, "why": "A は B より [Sifat] artinya A lebih [Sifat] daripada B. Di sini A adalah kemarin (きのう)."}, {"question": "Manakah kalimat yang tepat untuk ''Saya tidak terlalu suka ikan (さかな)''?", "options": ["さかなが すきくないです", "さかなが すきでは ありません", "さかなを すきます", "さかなが すきな ではありません"], "answer": 1, "why": "すき adalah kata sifat-Na dan objek kesukaan ditandai が, sehingga negasinya: すきではありません."}]}'::jsonb WHERE code = 'GP-JA-N5-012';
UPDATE grammar_points SET learning_guide = '{"analogy": "～ませんか mirip ajakan halus ''Mau nggak kita...?'' (memberi ruang lawan bicara menjawab ya/tidak), sedangkan ～ましょう seperti ''Ayo kita...!'' atau ''Biar saya bantu ya!''.", "when_to_use": ["Mengajak teman makan siang, minum kopi, atau jalan-jalan akhir pekan", "Menyetujui ajakan teman dengan bersemangat", "Menawarkan bantuan ringan kepada orang lain (pakai ～ましょうか)"], "formula_parts": [{"text": "Akar Verba", "label": "Sama seperti bentuk ます", "role": "verb"}, {"text": "ませんか / ましょう", "label": "Maukah...? / Ayo...!", "role": "ending"}], "steps": ["Ambil kata kerja bentuk sopan lalu buang akhiran ます (misal: いきます → いき).", "Tambahkan ～ませんか kalau ingin mengajak secara sopan tanpa memaksa.", "Tambahkan ～ましょう kalau menjawab antusias (''Ayo!'') atau mengajak tim bekerja bersama."], "breakdowns": [{"tokens": [{"jp": "いっしょに", "reading": "issho ni", "meaning": "bersama-sama", "role": "connector"}, {"jp": "かえりませんか", "reading": "kaerimasen ka", "meaning": "maukah pulang?", "role": "verb"}], "translation": "Maukah pulang bersama-sama?"}, {"tokens": [{"jp": "ちゅうしょく", "reading": "chuushoku", "meaning": "makan siang", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "たべましょう", "reading": "tabemashou", "meaning": "ayo makan!", "role": "verb"}], "translation": "Ayo makan siang!"}, {"tokens": [{"jp": "あした", "reading": "ashita", "meaning": "besok", "role": "time"}, {"jp": "えき", "reading": "eki", "meaning": "stasiun", "role": "place"}, {"jp": "の", "reading": "no", "meaning": "(dari)", "role": "particle"}, {"jp": "まえ", "reading": "mae", "meaning": "depan", "role": "place"}, {"jp": "で", "reading": "de", "meaning": "di", "role": "particle"}, {"jp": "あいませんか", "reading": "aimasen ka", "meaning": "maukah bertemu?", "role": "verb"}], "translation": "Maukah kita bertemu di depan stasiun besok?"}], "forms": [{"label": "Ajakan Halus", "jp": "コーヒーをのみませんか", "reading": "koohii o nomimasen ka", "id": "maukah minum kopi?"}, {"label": "Menyetujui / Ayo", "jp": "ええ、のみましょう", "reading": "ee, nomimashou", "id": "ya, ayo kita minum!"}, {"label": "Tawar Bantuan", "jp": "てつだいましょうか", "reading": "tetsudaimashou ka", "id": "boleh saya bantu?"}], "mistakes": [{"wrong": "いっしょに いきましょう！(menolak tapi bilang ini)", "right": "すみません、きょうは ちょっと…", "why": "Di Jepang, menolak ajakan tidak langsung dijawab ''いえ、いきません'' (kasar); cukup bilang ''Maaf, hari ini agak... (chotto)''."}, {"wrong": "コーヒーを のみますか (saat berniat mengajak)", "right": "コーヒーを のみませんか", "why": "のみますか terdengar seperti sekadar menanyakan kebiasaan (''Apakah kamu minum kopi?''), sedangkan のみませんか bernada mengajak."}], "quiz": [{"question": "Mana bentuk ajakan paling sopan kepada rekan baru untuk makan bersama?", "options": ["いっしょに たべますか", "いっしょに たべませんか", "いっしょに たべましたか", "いっしょに たべません"], "answer": 1, "why": "Akhiran tanya negatif ～ませんか adalah cara paling sopan untuk mengajak."}, {"question": "Jika rekanmu mengajak ''こうえんへ いきませんか'', jawaban menerima yang pas adalah:", "options": ["はい、いきません", "いいえ、いきましょう", "ええ、いきましょう！", "いいえ、いきました"], "answer": 2, "why": "''ええ、いきましょう'' berarti ''Ya, ayo kita pergi!''."}, {"question": "Apa nuansa kalimat ''にもつを もちましょうか'' saat melihat teman membawa dus berat?", "options": ["Menawarkan bantuan untuk membawakan", "Menyuruh teman mengangkat barang", "Menolak membawa barang", "Menanyakan isi barang"], "answer": 0, "why": "Pola ～ましょうか menandakan pembicara menawarkan diri membantu sesuatu."}]}'::jsonb WHERE code = 'GP-JA-N5-013';
UPDATE grammar_points SET learning_guide = '{"analogy": "Bentuk-TE + ください itu artinya ''Tolong ... ya''. Uniknya, Bentuk-TE (yang berakhiran -te atau -de) juga berfungsi sebagai lem penyambung untuk menggabungkan beberapa aksi berurutan (''... lalu ...'').", "when_to_use": ["Meminta bantuan orang lain secara sopan (tolong tulis, tolong baca, tolong tunggu sebentar)", "Memberi petunjuk atau instruksi kerja atau arah jalan", "Menceritakan rentetan kegiatan berurutan dari pagi sampai malam"], "formula_parts": [{"text": "Verba Bentuk-TE", "label": "Bentuk sambung (-て / -で)", "role": "verb"}, {"text": "ください", "label": "Tolong (sopan)", "role": "ending"}], "steps": ["Ubah kata kerja ke Bentuk-TE: verba berakhiran i-chi-ri jadi って (kaimasu→かって), mi-bi-ni jadi んで (nomimasu→のんで), ki jadi いて (kakimasu→かいて), gi jadi いで, shi jadi して, grup 2 tinggal ganti ます jadi て (tabemasu→たべて).", "Tambahkan ください setelah Bentuk-TE untuk membuat kalimat permohonan sopan (''Tolong...'').", "Kalau mau menyambung dua kegiatan berurutan, cukup pakai Bentuk-TE di kalimat pertama tanpa ください."], "breakdowns": [{"tokens": [{"jp": "ここ", "reading": "koko", "meaning": "di sini", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "pada", "role": "particle"}, {"jp": "なまえ", "reading": "namae", "meaning": "nama", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "かいて", "reading": "kaite", "meaning": "tulis (TE)", "role": "verb"}, {"jp": "ください", "reading": "kudasai", "meaning": "tolong", "role": "ending"}], "translation": "Tolong tulis nama Anda di sini."}, {"tokens": [{"jp": "すみません", "reading": "sumimasen", "meaning": "permisi", "role": "connector"}, {"jp": "ゆっくり", "reading": "yukkuri", "meaning": "pelan-pelan", "role": "adjective"}, {"jp": "はなして", "reading": "hanashite", "meaning": "berbicara (TE)", "role": "verb"}, {"jp": "ください", "reading": "kudasai", "meaning": "tolong", "role": "ending"}], "translation": "Permisi, tolong bicara pelan-pelan."}, {"tokens": [{"jp": "あさ", "reading": "asa", "meaning": "pagi", "role": "time"}, {"jp": "おきて", "reading": "okite", "meaning": "bangun lalu", "role": "verb"}, {"jp": "シャワー", "reading": "shawaa", "meaning": "mandi", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "あびて", "reading": "abite", "meaning": "guyur lalu", "role": "verb"}, {"jp": "うち", "reading": "uchi", "meaning": "rumah", "role": "place"}, {"jp": "を", "reading": "o", "meaning": "dari", "role": "particle"}, {"jp": "でます", "reading": "demasu", "meaning": "berangkat", "role": "verb"}], "translation": "Pagi hari bangun, lalu mandi, kemudian berangkat dari rumah."}], "forms": [{"label": "Grup 1 (き→いて)", "jp": "かいてください", "reading": "kaite kudasai", "id": "tolong tulis"}, {"label": "Grup 1 (み→んで)", "jp": "よんでください", "reading": "yonde kudasai", "id": "tolong baca"}, {"label": "Grup 2 (～て)", "jp": "たべてください", "reading": "tabete kudasai", "id": "tolong makan"}, {"label": "Pengecualian (行)", "jp": "いってください", "reading": "itte kudasai", "id": "tolong pergi"}], "mistakes": [{"wrong": "いきます → いいて ください", "right": "いって ください", "why": "Meski いきます punya huruf き, kata kerja ''pergi'' ini adalah pengecualian wajib menjadi いって (itte)."}, {"wrong": "おねがいします かきます", "right": "かいて ください", "why": "おねがいします dipakai setelah kata benda (''Bantuannya ya''), sedangkan kata kerja memakai Bentuk-TE + ください."}], "quiz": [{"question": "Ubah ''のみます'' (minum) menjadi bentuk permohonan ''Tolong minum'':", "options": ["のみて ください", "のいて ください", "のんで ください", "のって ください"], "answer": 2, "why": "Kata kerja Grup 1 berakhiran み sebelum ます (no-mi-masu) berubah menjadi んで → のんで."}, {"question": "Bagaimana cara benar untuk ''Tolong lihat foto ini'' (みます = grup 2)?", "options": ["みて ください", "みって ください", "みんで ください", "みる ください"], "answer": 0, "why": "みます termasuk verba Grup 2 (satu suku kata vokal i), sehingga cukup buang ます dan tambah て → みて."}, {"question": "Dalam kalimat ''あさ ごはんを たべて、がっこうへ いきます'', fungsi Bentuk-TE pada たべて adalah:", "options": ["Menyuruh orang makan", "Menyambung dua aksi berurutan (''lalu'')", "Menyatakan sedang makan", "Menyangkal sudah makan"], "answer": 1, "why": "Bentuk-TE tanpa ください berfungsi sebagai kata sambung aksi berurutan (''makan dulu, lalu pergi'')."}]}'::jsonb WHERE code = 'GP-JA-N5-014';
UPDATE grammar_points SET learning_guide = '{"analogy": "～ています itu punya 2 arti praktis: seperti imbuhan ''sedang...'' (aksi yang masih berlangsung detik ini) ATAU menyatakan ''status tetap'' saat ini (tinggal di mana, bekerja di mana, sudah menikah).", "when_to_use": ["Menjelaskan aktivitas yang sedang terjadi sekarang (''sedang makan'', ''hujan sedang turun'')", "Menyebutkan kota tempat tinggal, tempat kerja, atau status menikah", "Menyebutkan hal yang biasa dilakukan berulang-ulang dalam keseharian"], "formula_parts": [{"text": "Verba Bentuk-TE", "label": "Aksi (-て / -で)", "role": "verb"}, {"text": "います", "label": "Sedang / Berstatus", "role": "ending"}], "steps": ["Ubah kata kerja ke Bentuk-TE terlebih dulu (sama seperti pola ～てください).", "Tambahkan います (atau versi singkat lisan ってます / てます saat ngobrol kasual, tapi di N5 pakai lengkap います).", "Untuk negatif (''tidak sedang...''), ubah menjadi ～ていません."], "breakdowns": [{"tokens": [{"jp": "いま", "reading": "ima", "meaning": "sekarang", "role": "time"}, {"jp": "あめ", "reading": "ame", "meaning": "hujan", "role": "subject"}, {"jp": "が", "reading": "ga", "meaning": "(subjek)", "role": "particle"}, {"jp": "ふっています", "reading": "futte imasu", "meaning": "sedang turun", "role": "verb"}], "translation": "Sekarang sedang turun hujan."}, {"tokens": [{"jp": "わたし", "reading": "watashi", "meaning": "saya", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "おおさか", "reading": "Oosaka", "meaning": "Osaka", "role": "place"}, {"jp": "に", "reading": "ni", "meaning": "di", "role": "particle"}, {"jp": "すんでいます", "reading": "sunde imasu", "meaning": "tinggal (status)", "role": "verb"}], "translation": "Saya tinggal di Osaka."}, {"tokens": [{"jp": "たなかさん", "reading": "Tanaka-san", "meaning": "Tuan Tanaka", "role": "topic"}, {"jp": "は", "reading": "wa", "meaning": "(topik)", "role": "particle"}, {"jp": "かいぎしつ", "reading": "kaigishitsu", "meaning": "ruang rapat", "role": "place"}, {"jp": "で", "reading": "de", "meaning": "di", "role": "particle"}, {"jp": "パソコン", "reading": "pasokon", "meaning": "laptop", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "つかっています", "reading": "tsukatte imasu", "meaning": "sedang memakai", "role": "verb"}], "translation": "Tuan Tanaka sedang memakai laptop di ruang rapat."}], "forms": [{"label": "Sedang Aksi", "jp": "べんきょうしています", "reading": "benkyou shite imasu", "id": "sedang belajar"}, {"label": "Tidak Sedang", "jp": "べんきょうしていません", "reading": "benkyou shite imasen", "id": "tidak sedang belajar"}, {"label": "Status Tetap", "jp": "けっこんしています", "reading": "kekkon shite imasu", "id": "sudah menikah"}], "mistakes": [{"wrong": "おおさかに すみます (utk tinggal sekarang)", "right": "おおさかに すんでいます", "why": "Kata kerja keadaan seperti tinggal (住む), mengenal (知る), dan menikah (結婚する) WAJIB memakai ～ています untuk menyatakan keadaan saat ini."}, {"wrong": "しっていません (bilang tidak tahu)", "right": "しりません", "why": "Pengecualian khusus: ''tahu'' = しっています, tapi ''tidak tahu'' selalu memakai しりません (bukan しっていません)."}], "quiz": [{"question": "Cara yang benar untuk berkata ''Saya sekarang tinggal di Jakarta'' adalah:", "options": ["ジャカルタに すみます", "ジャカルタに すんでいます", "ジャカルタで すみます", "ジャカルタを すんでいます"], "answer": 1, "why": "Tinggal di suatu kota adalah status berkelanjutan, sehingga memakai すんでいます (dan lokasi tinggal memakai に)."}, {"question": "Jika teman bertanya tentang seseorang dan kamu TIDAK mengenalnya, jawabannya yang natural adalah:", "options": ["しっていません", "しっています", "しりません", "しりています"], "answer": 2, "why": "Pengecualian terkenal: bentuk negatif ''tahu'' adalah しりません."}, {"question": "Kalimat ''いま おんがくを きいています'' artinya:", "options": ["Tolong dengarkan musik sekarang", "Saya sudah mendengarkan musik", "Sekarang saya sedang mendengarkan musik", "Saya ingin mendengarkan musik"], "answer": 2, "why": "Bentuk-TE (きいて) + います dengan penanda waktu いま menyatakan kegiatan sedang berlangsung."}]}'::jsonb WHERE code = 'GP-JA-N5-015';
UPDATE grammar_points SET learning_guide = '{"analogy": "～たいです artinya ''Saya ingin...''. Sementara pola [Tempat] へ [Verba-akar] に いきます artinya ''Pergi ke tempat tertentu UNTUK melakukan suatu kegiatan''.", "when_to_use": ["Mengungkapkan keinginan pribadi (ingin makan sushi, ingin pergi ke Jepang)", "Menjelaskan tujuan kepergian ke suatu tempat (pergi ke mall untuk belanja, pergi ke resto untuk makan)", "Memesan atau merencanakan aktivitas bersama teman"], "formula_parts": [{"text": "Akar Verba", "label": "Bentuk masu tanpa ます", "role": "verb"}, {"text": "たいです", "label": "Ingin ... (sifat-i)", "role": "ending"}, {"text": "/ へ [Verba] に いきます", "label": "Pergi ke ... untuk ...", "role": "connector"}], "steps": ["Untuk bilang ''ingin'': buang ます dari kata kerja, lalu tempelkan ～たいです (tabe-masu → tabe-tai desu).", "Uniknya, pola ～たい ini berubah layaknya Kata Sifat-I! Jadi ''tidak ingin'' adalah ～たくないです.", "Untuk bilang ''pergi ke X untuk melakukan Y'': [X] へ [Akar kata kerja / Kata benda aksi] に いきます."], "breakdowns": [{"tokens": [{"jp": "すし", "reading": "sushi", "meaning": "sushi", "role": "object"}, {"jp": "が", "reading": "ga", "meaning": "(objek ingin)", "role": "particle"}, {"jp": "たべたいです", "reading": "tabetai desu", "meaning": "ingin makan", "role": "verb"}], "translation": "Saya ingin makan sushi."}, {"tokens": [{"jp": "スーパー", "reading": "suupaa", "meaning": "supermarket", "role": "place"}, {"jp": "へ", "reading": "e", "meaning": "ke", "role": "particle"}, {"jp": "かいもの", "reading": "kaimono", "meaning": "belanja", "role": "noun"}, {"jp": "に", "reading": "ni", "meaning": "untuk", "role": "particle"}, {"jp": "いきます", "reading": "ikimasu", "meaning": "pergi", "role": "verb"}], "translation": "Pergi ke supermarket untuk berbelanja."}, {"tokens": [{"jp": "きょうと", "reading": "Kyouto", "meaning": "Kyoto", "role": "place"}, {"jp": "へ", "reading": "e", "meaning": "ke", "role": "particle"}, {"jp": "さくら", "reading": "sakura", "meaning": "bunga sakura", "role": "object"}, {"jp": "を", "reading": "o", "meaning": "(objek)", "role": "particle"}, {"jp": "み", "reading": "mi", "meaning": "melihat", "role": "verb"}, {"jp": "に", "reading": "ni", "meaning": "untuk", "role": "particle"}, {"jp": "いきました", "reading": "ikimashita", "meaning": "telah pergi", "role": "verb"}], "translation": "Saya pergi ke Kyoto untuk melihat bunga sakura."}], "forms": [{"label": "Ingin (+)", "jp": "いきたいです", "reading": "ikitai desu", "id": "ingin pergi"}, {"label": "Tidak Ingin (-)", "jp": "いきたくないです", "reading": "ikitakunai desu", "id": "tidak ingin pergi"}, {"label": "Dulu Ingin", "jp": "いきたかったです", "reading": "ikitakatta desu", "id": "kemarin ingin pergi"}, {"label": "Tujuan Aksi", "jp": "みに いきます", "reading": "mi ni ikimasu", "id": "pergi untuk melihat"}], "mistakes": [{"wrong": "にほんへ いきたいません", "right": "にほんへ いきたくないです", "why": "Bentuk ～たい ikut aturan Kata Sifat-I, jadi bentuk negatifnya adalah ～たくないです (bukan ません)."}, {"wrong": "コーヒーを みます たい (pakai ます)", "right": "コーヒーが / を のみたいです", "why": "ます wajib dibuang terlebih dulu sebelum menempelkan たい."}], "quiz": [{"question": "Bagaimana mengatakan ''Saya tidak ingin minum kopi sekarang''?", "options": ["コーヒーを のみません たい", "コーヒーを のみたい ではありません", "コーヒーを のみたくないです", "コーヒーを のみませんでした"], "answer": 2, "why": "Pola ～たい berubah layaknya adjektiva-i menjadi ～たくないです."}, {"question": "Lengkapi: ''としょかんへ ほんを ___ いきます'' (Pergi ke perpustakaan untuk meminjam buku; meminjam = かります).", "options": ["かりに", "かりて", "かりたい", "かるに"], "answer": 0, "why": "Tujuan kepergian memakai akar kata kerja (tanpa ます) + に + いきます → かりに."}, {"question": "Kalau kamu sedang berangan-angan ingin membeli mobil (かう = membeli), bagaimana bentuk yang tepat?", "options": ["くるまを かってです", "くるまを かいたいです", "くるまを かいに たいです", "くるまを かいません"], "answer": 1, "why": "かいます dibuang ます menjadi かい, lalu ditambah たいです → かいたいです."}]}'::jsonb WHERE code = 'GP-JA-N5-016';

COMMIT;
